INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面孔", "is_correct": false, "explanation": "体貌：「面孔」指人的脸，不能作为公司，「那家面孔」说不通。"}, {"text": "谜语", "is_correct": false, "explanation": "语义：「谜语」是一种文字游戏，不是公司，不能为工人建宿舍。"}, {"text": "生产企业", "is_correct": true, "explanation": "正确答案。「生产企业」是做东西的公司，可以为工人建宿舍。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：「乐器」是演奏用的器具，不是公司，不能为工人建宿舍。"}], "explanations": {"面孔": "体貌：「面孔」指人的脸，不能作为公司，「那家面孔」说不通。", "谜语": "语义：「谜语」是一种文字游戏，不是公司，不能为工人建宿舍。", "生产企业": "正确答案。「生产企业」是做东西的公司，可以为工人建宿舍。", "乐器": "语义：「乐器」是演奏用的器具，不是公司，不能为工人建宿舍。"}, "sentence_index": 6, "correct_answer": "生产企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家生产企业正在教小朋友唱歌。", "explanation": "这里应该用〈幼儿园〉。生产企业是做东西的公司，不教小朋友唱歌。"}, {"text": "这家生产企业每天都住满了客人。", "explanation": "这里应该用〈旅馆〉。生产企业是做东西的公司，不提供住宿。"}, {"text": "这家生产企业每天都有很多旅客上下车。", "explanation": "这里应该用〈车站〉。生产企业是做东西的公司，不接送旅客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条生产企业每天生产很多玩具。", "corrected_sentence": "这家生产企业每天生产很多玩具。", "error_description": "量词错误：「生产企业」是公司，应说「家」，不能用「条」（「条」用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本生产企业今年新招了很多工人。", "corrected_sentence": "那家生产企业今年新招了很多工人。", "error_description": "量词错误：「生产企业」是公司，应说「家」，不能用「本」（「本」用于书籍）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
