INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事产品生产的企业。", "primary_collocate": null, "pronunciation": "shēng chǎn qǐ yè", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩˦ tɕʰi˨˩˦ je˥˩", "syllable_count": 4, "sentences": [{"text": "这家生产企业已经通过了质量检查。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要求生产企业注意环境保护。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产企业要对产品的质量负责。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些生产企业把产品卖到了国外。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的规定对生产企业影响很大。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产企业和商店的合作很重要。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家生产企业用新机器提高了产量。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类生产企业必须保证食品安全。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多生产企业今年都招了新工人。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家生产企业正在研究新产品。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "生產企業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从事产品生产的企业，用于质量、规定、产量等场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小说", "is_correct": false, "explanation": "语义：「小说」是文学作品，不是企业，不能通过质量检查。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」是自然现象，不是企业，不能说「这家天气」，也不能通过质量检查。"}, {"text": "生产企业", "is_correct": true, "explanation": "正确答案。「生产企业」是从事产品生产的企业，可以通过质量检查。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，不能用来指企业。"}], "explanations": {"小说": "语义：「小说」是文学作品，不是企业，不能通过质量检查。", "天气": "语义：「天气」是自然现象，不是企业，不能说「这家天气」，也不能通过质量检查。", "生产企业": "正确答案。「生产企业」是从事产品生产的企业，可以通过质量检查。", "身材": "体貌：「身材」指人的体形，不能用来指企业。"}, "sentence_index": 0, "correct_answer": "生产企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家生产企业治好了很多病人。", "explanation": "这里应该用〈医院〉。生产企业从事产品生产，不给病人治病。"}, {"text": "这家生产企业给很多人理了发。", "explanation": "这里应该用〈理发店〉。生产企业从事产品生产，不提供理发服务。"}, {"text": "这家生产企业演出了很多戏。", "explanation": "这里应该用〈剧院〉。生产企业从事产品生产，不演出戏剧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：「诗歌」是文学作品，不是企业，不能用新机器提高产量。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：「脸色」指人的面部颜色，不能用来指企业。"}, {"text": "生产企业", "is_correct": true, "explanation": "正确答案。「生产企业」能用新机器提高产量，说得通。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：「乐谱」是记录音乐的符号，不是企业，不能提高产量。"}], "explanations": {"诗歌": "语义：「诗歌」是文学作品，不是企业，不能用新机器提高产量。", "脸色": "体貌：「脸色」指人的面部颜色，不能用来指企业。", "生产企业": "正确答案。「生产企业」能用新机器提高产量，说得通。", "乐谱": "语义：「乐谱」是记录音乐的符号，不是企业，不能提高产量。"}, "sentence_index": 6, "correct_answer": "生产企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家生产企业正在教孩子们画画。", "explanation": "这里应该用〈幼儿园〉。生产企业从事产品生产，不教孩子们画画。"}, {"text": "这家生产企业每天都住满了客人。", "explanation": "这里应该用〈旅馆〉。生产企业从事产品生产，不提供住宿。"}, {"text": "这家生产企业每天都治很多病人。", "explanation": "这里应该用〈诊所〉。生产企业从事产品生产，不给病人看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条生产企业去年赚了很多钱。", "corrected_sentence": "这家生产企业去年赚了很多钱。", "error_description": "量词错误：「生产企业」是企业，应说「家」，不能用「条」（「条」用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本生产企业正在研发新机器。", "corrected_sentence": "这家生产企业正在研发新机器。", "error_description": "量词错误：「生产企业」是企业，应说「家」，不能用「本」（「本」用于书籍）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
