INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "售价是东西卖多少钱。", "primary_collocate": null, "pronunciation": "shòu jià", "ipa": "ʂoʊ̯˥˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服的售价是两百块。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机的售价比去年便宜一点。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店把这本书的售价写在了封底上。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的售价太高，我买不起。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这双鞋的售价是多少吗？", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节的时候，水果的售价会下降。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这台电脑的售价已经很低了。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标签上写着每个杯子的售价。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面包售价不贵，味道也好。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "售价五十元的书包卖得很快。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "售價", "label": "繁体"}, {"form": "零售价", "label": "复合"}], "register": "中性", "sense_fingerprint": "商店卖东西时标出的钱数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf3d60e-a1e3-44ad-8ec7-68f909d098f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "售价", "is_correct": true, "explanation": "正确：“售价”指商品卖出的钱数，与“是两百块”搭配。"}, {"text": "尺码", "is_correct": false, "explanation": "语义：“尺码”指衣服的大小号，不是钱数，不能说“是两百块”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能用“两百块”来说明。"}, {"text": "销量", "is_correct": false, "explanation": "搭配：“销量”计数的单位是件，不能用“块”来计算。"}], "explanations": {"售价": "正确：“售价”指商品卖出的钱数，与“是两百块”搭配。", "尺码": "语义：“尺码”指衣服的大小号，不是钱数，不能说“是两百块”。", "颜色": "语义：“颜色”指色彩，不能用“两百块”来说明。", "销量": "搭配：“销量”计数的单位是件，不能用“块”来计算。"}, "sentence_index": 0, "correct_answer": "售价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "坐出租车去机场的售价是一百块。", "explanation": "这里应该用〈车费〉。售价指商品卖出的价格，出租车的服务收费要说车费。"}, {"text": "这所大学的售价每年都在涨。", "explanation": "这里应该用〈学费〉。售价只用于商品，学校提供的是教育服务，要说学费。"}, {"text": "这份工作的售价很高，大家都想做。", "explanation": "这里应该用〈报酬〉。售价指商品卖出的价格，工作的收入要说报酬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "售价", "is_correct": true, "explanation": "正确：“售价”指电脑卖出的价格，与“已经很低了”搭配。"}, {"text": "产地", "is_correct": false, "explanation": "语义：“产地”指出产的地方，不能说“已经很低了”。"}, {"text": "作者", "is_correct": false, "explanation": "语义：“作者”指创作的人，电脑没有作者，也不能说“很低”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来形容电脑。"}], "explanations": {"售价": "正确：“售价”指电脑卖出的价格，与“已经很低了”搭配。", "产地": "语义：“产地”指出产的地方，不能说“已经很低了”。", "作者": "语义：“作者”指创作的人，电脑没有作者，也不能说“很低”。", "身材": "体貌：“身材”指人的体形，不能用来形容电脑。"}, "sentence_index": 6, "correct_answer": "售价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在的售价是下午三点。", "explanation": "这里误把〈售价〉用于时间，把时间当成了可以标价出售的东西。售价只指商品卖出的价格，说时间应直接说明时刻。"}, {"text": "这位医生的售价很高，很多病人都想找他。", "explanation": "售价只用于商品，医生的诊疗是服务，要说收费或诊费。"}, {"text": "这场雨的售价很低。", "explanation": "这里误把〈售价〉用于雨，把雨当成了可以出售的商品。售价只指商品卖出的价格，描述雨的大小应说〈雨量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新车地售价已经公布了。", "corrected_sentence": "新车的售价已经公布了。", "error_description": "错误在“的”写成了“地”。“地”用于副词性修饰语，修饰名词“售价”要用“的”，应说“新车的售价”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器地售价是多少？", "corrected_sentence": "这台机器的售价是多少？", "error_description": "错误在“的”写成了“地”。“售价”是名词，前面的修饰语“这台机器”要用“的”，应说“这台机器的售价是多少？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
