INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商品出售时的价格。", "primary_collocate": null, "pronunciation": "shòu jià", "ipa": "ʂoʊ̯˥˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这个玩具的售价只要十五元。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员告诉我这条裤子的售价。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的房子售价每年都在上涨。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商品的售价都贴在架子上。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶叶的售价很高，因为是新茶。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道这台冰箱的售价。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了节，这些衣服的售价都降了。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "售价便宜的东西不一定不好。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的售价让我吃了一惊。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的售价比商店里低很多。", "target_word": "售价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "售價", "label": "繁体"}, {"form": "零售价", "label": "复合"}], "register": "中性", "sense_fingerprint": "商品出售时的价格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf3d60e-a1e3-44ad-8ec7-68f909d098f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "售价", "is_correct": true, "explanation": "正确：“售价”指商品卖出的价钱，与“只要十五元”搭配。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：“尺寸”指长宽高，不是钱数，不能说“只要十五元”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能用价钱来说明。"}, {"text": "库存", "is_correct": false, "explanation": "搭配：“库存”计数的单位是件，不能用“元”来计算。"}], "explanations": {"售价": "正确：“售价”指商品卖出的价钱，与“只要十五元”搭配。", "尺寸": "语义：“尺寸”指长宽高，不是钱数，不能说“只要十五元”。", "颜色": "语义：“颜色”指色彩，不能用价钱来说明。", "库存": "搭配：“库存”计数的单位是件，不能用“元”来计算。"}, "sentence_index": 0, "correct_answer": "售价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的售价很高，因为用电多。", "explanation": "这里应该用〈电费〉。售价指商品卖出的价格，电费是服务的收费，要说电费。"}, {"text": "我的售价每个月都很高。", "explanation": "这里应该用〈工资〉。售价只用于商品，个人的收入要说工资。"}, {"text": "他因为闯红灯交了售价。", "explanation": "这里应该用〈罚款〉。售价指商品的价格，违章的罚款不能说售价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "售价", "is_correct": true, "explanation": "正确：“售价”指衣服卖出的价格，可以说“降”。"}, {"text": "品牌", "is_correct": false, "explanation": "搭配：“降”不能用于品牌，不能说“品牌都降了”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不会因为过节而“降”。"}, {"text": "面料", "is_correct": false, "explanation": "语义：“面料”指布料，不能说“降了”。"}], "explanations": {"售价": "正确：“售价”指衣服卖出的价格，可以说“降”。", "品牌": "搭配：“降”不能用于品牌，不能说“品牌都降了”。", "颜色": "语义：“颜色”指色彩，不会因为过节而“降”。", "面料": "语义：“面料”指布料，不能说“降了”。"}, "sentence_index": 6, "correct_answer": "售价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的售价很高，大家都想请他帮忙。", "explanation": "这里误把〈售价〉用于人，把人的身价当成了商品价格。说人的身价应用〈身价〉，售价只指商品卖出的价格。"}, {"text": "这段回忆的售价很高。", "explanation": "这里误把〈售价〉用于回忆，把回忆的珍贵说成了商品价格。表达回忆的珍贵应说〈珍贵〉，售价只指商品卖出的价格。"}, {"text": "这个梦想的售价很高。", "explanation": "这里误把〈售价〉用于梦想，把梦想的价值当成了商品价格。说梦想的价值应用〈价值〉，售价只指商品卖出的价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店地售价很合理。", "corrected_sentence": "这家店的售价很合理。", "error_description": "错误在“的”写成了“地”。“售价”是名词，前面的修饰语“这家店”要用“的”，应说“这家店的售价很合理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鞋地售价是多少钱？", "corrected_sentence": "这种鞋的售价是多少钱？", "error_description": "错误在“的”写成了“地”。“售价”是名词，前面的修饰语“这种鞋”要用“的”，应说“这种鞋的售价是多少钱？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
