INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91935, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "用来说做一件事的次数。", "primary_collocate": null, "pronunciation": "fān", "ipa": "fan˥", "syllable_count": 1, "sentences": [{"text": "他把房间打扫了一番。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在门口打量了他一番。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打扮了一番才出门。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试了几番，都没有成功。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们聊了一番，就各自回家了。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我检查了一番，没发现问题。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问了一番，才知道这件事。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了一番，还是不买。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家商量了一番，决定明天去。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发整理了一番。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "动量词，放在动词后说明做了一次或几次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91935, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "番", "is_correct": true, "explanation": "番（fān，第一声）即本词，作动量词时表示做一件事的次数。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是饭。"}, {"text": "反", "is_correct": false, "explanation": "fǎn（第三声）与 fān（第一声）声调不同，意思是反对、相反。"}, {"text": "烦", "is_correct": false, "explanation": "fán（第二声）与 fān（第一声）声调不同，意思是烦恼。"}, {"text": "摊", "is_correct": false, "explanation": "tān（第一声）与 fān（第一声）只有声母不同（t 与 f），意思是摊开。"}, {"text": "分", "is_correct": false, "explanation": "fēn 与 fān 韵母不同（en 与 an），意思是分开。"}], "explanations": {"番": "番（fān，第一声）即本词，作动量词时表示做一件事的次数。", "饭": "fàn（第四声）与 fān（第一声）声调不同，意思是饭。", "反": "fǎn（第三声）与 fān（第一声）声调不同，意思是反对、相反。", "烦": "fán（第二声）与 fān（第一声）声调不同，意思是烦恼。", "摊": "tān（第一声）与 fān（第一声）只有声母不同（t 与 f），意思是摊开。", "分": "fēn 与 fān 韵母不同（en 与 an），意思是分开。"}, "sentence_index": null, "correct_answer": "番"}, "level_3": {"options": [{"text": "番", "is_correct": true, "explanation": "番作动量词，放在动词后说明做了一次，与“打扫了”搭配，意思完整。"}, {"text": "声", "is_correct": false, "explanation": "语义：“声”用于计量声音，与“打扫”这类动作不合。"}, {"text": "碗", "is_correct": false, "explanation": "搭配：“碗”是容器，不能用来计量“打扫”这类动作。"}, {"text": "口", "is_correct": false, "explanation": "搭配：“口”多用于吃喝或说话，不能用来计量“打扫”。"}], "explanations": {"番": "番作动量词，放在动词后说明做了一次，与“打扫了”搭配，意思完整。", "声": "语义：“声”用于计量声音，与“打扫”这类动作不合。", "碗": "搭配：“碗”是容器，不能用来计量“打扫”这类动作。", "口": "搭配：“口”多用于吃喝或说话，不能用来计量“打扫”。"}, "sentence_index": 0, "correct_answer": "番"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他眨了一番眼，没有说话。", "explanation": "这里应该用〈下〉。番多用于需要花时间或力气的动作，眨眼这类瞬时动作用〈下〉。"}, {"text": "他买了一番书，放在书架上。", "explanation": "这里应该用〈批〉。番用于做一件事的次数或过程，不用来计量书这类可数的东西；一批书应用〈批〉。"}, {"text": "他打了一番喷嚏，把大家都吓了一跳。", "explanation": "这里应该用〈个〉。番多用于需要时间或力气的动作，打喷嚏这类瞬时动作用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91935, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "番", "is_correct": true, "explanation": "番（fān，第一声）即本词，作动量词时表示做一件事的次数。"}, {"text": "犯", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是犯错。"}, {"text": "繁", "is_correct": false, "explanation": "fán（第二声）与 fān（第一声）声调不同，意思是繁多、繁忙。"}, {"text": "方", "is_correct": false, "explanation": "fāng 与 fān 韵母不同（ang 与 an），意思是方向、方法。"}, {"text": "攀", "is_correct": false, "explanation": "pān（第一声）与 fān（第一声）只有声母不同（p 与 f），意思是攀登。"}, {"text": "返", "is_correct": false, "explanation": "fǎn（第三声）与 fān（第一声）声调不同，意思是返回。"}], "explanations": {"番": "番（fān，第一声）即本词，作动量词时表示做一件事的次数。", "犯": "fàn（第四声）与 fān（第一声）声调不同，意思是犯错。", "繁": "fán（第二声）与 fān（第一声）声调不同，意思是繁多、繁忙。", "方": "fāng 与 fān 韵母不同（ang 与 an），意思是方向、方法。", "攀": "pān（第一声）与 fān（第一声）只有声母不同（p 与 f），意思是攀登。", "返": "fǎn（第三声）与 fān（第一声）声调不同，意思是返回。"}, "sentence_index": null, "correct_answer": "番"}, "level_3": {"options": [{"text": "番", "is_correct": true, "explanation": "番作动量词，放在动词后说明做了一次，与“问了”搭配，意思完整。"}, {"text": "粒", "is_correct": false, "explanation": "语义：“粒”指颗粒状的小物，不能用来计量“问”这类动作。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：“颗”多用于小而圆的东西，不能用来计量“问”。"}, {"text": "片", "is_correct": false, "explanation": "搭配：“片”多用于扁平之物，不能用来计量“问”。"}], "explanations": {"番": "番作动量词，放在动词后说明做了一次，与“问了”搭配，意思完整。", "粒": "语义：“粒”指颗粒状的小物，不能用来计量“问”这类动作。", "颗": "搭配：“颗”多用于小而圆的东西，不能用来计量“问”。", "片": "搭配：“片”多用于扁平之物，不能用来计量“问”。"}, "sentence_index": 6, "correct_answer": "番"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喝了一番牛奶，觉得很好喝。", "explanation": "这里应该用〈杯〉。番表示需要时间或力气的动作，不能用来计量牛奶这类可以喝的东西。"}, {"text": "我们吃了一番饭，很满足。", "explanation": "这里应该用〈顿〉。番不用于计量一餐饭，吃饭的次数要用〈顿〉。"}, {"text": "我坐了一番地铁，才到公司。", "explanation": "这里应该用〈趟〉。番用于做一件事的次数，多指需要花时间或力气的动作；乘车一次应说〈趟〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把厨房仔细打扫了番。", "corrected_sentence": "他把厨房仔细打扫了一番。", "error_description": "错误：“打扫了番”；正确：“打扫了一番”。“番”作动量词时前面须有数词（通常是“一”），漏掉数词即不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把书桌仔细整理了一个番。", "corrected_sentence": "她把书桌仔细整理了一番。", "error_description": "错误：“整理了一个番”；正确：“整理了一番”。“番”本身是动量词，数词“一”后不能再接量词“个”，动作次数直接用“一番”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
