INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91936, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，表示动作的次数或过程。", "primary_collocate": null, "pronunciation": "fān", "ipa": "fan˥", "syllable_count": 1, "sentences": [{"text": "听了他的一番话，我明白了很多。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一番努力，他终于成功了。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听完朋友的一番劝告，才做出了决定。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的一番鼓励，让我有了信心。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一番准备，比赛开始了。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我说了一番心里话。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她花了一番功夫，才做好这道菜。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一番讨论以后，大家同意了。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的一番解释，让我们明白了问题在哪里。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说了一番劝慰的话，我终于同意了。", "target_word": "番", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "量词，常用于话、努力、心意等表示过程的名词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91936, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "番", "is_correct": true, "explanation": "番（fān，第一声）即本词，作量词时用于话语、努力等，表示一段过程或一定的量。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是饭。"}, {"text": "反", "is_correct": false, "explanation": "fǎn（第三声）与 fān（第一声）声调不同，意思是反对、相反。"}, {"text": "烦", "is_correct": false, "explanation": "fán（第二声）与 fān（第一声）声调不同，意思是烦恼。"}, {"text": "方", "is_correct": false, "explanation": "fāng 与 fān 韵母不同（ang 与 an），意思是方向、方法。"}, {"text": "分", "is_correct": false, "explanation": "fēn 与 fān 韵母不同（en 与 an），意思是分开。"}], "explanations": {"番": "番（fān，第一声）即本词，作量词时用于话语、努力等，表示一段过程或一定的量。", "饭": "fàn（第四声）与 fān（第一声）声调不同，意思是饭。", "反": "fǎn（第三声）与 fān（第一声）声调不同，意思是反对、相反。", "烦": "fán（第二声）与 fān（第一声）声调不同，意思是烦恼。", "方": "fāng 与 fān 韵母不同（ang 与 an），意思是方向、方法。", "分": "fēn 与 fān 韵母不同（en 与 an），意思是分开。"}, "sentence_index": null, "correct_answer": "番"}, "level_3": {"options": [{"text": "番", "is_correct": true, "explanation": "番是量词，用于话语、努力等，表示一定的量或过程，与“明白了很多”相符。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”多用于可以握住的器物，不能用来计量“话”。"}, {"text": "根", "is_correct": false, "explanation": "语义：“根”多指细长的东西，与“话”的意思不合。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对之物，不能用来计量“话”。"}], "explanations": {"番": "番是量词，用于话语、努力等，表示一定的量或过程，与“明白了很多”相符。", "把": "搭配：“把”多用于可以握住的器物，不能用来计量“话”。", "根": "语义：“根”多指细长的东西，与“话”的意思不合。", "只": "搭配：“只”多用于动物或成对之物，不能用来计量“话”。"}, "sentence_index": 0, "correct_answer": "番"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天下了一番大雨，路上很难走。", "explanation": "这里应该用〈场〉。番用于话语、努力等过程，不用于大雨这类自然现象。"}, {"text": "我买了一番苹果，放在冰箱里。", "explanation": "这里应该用〈斤〉。番表示一段过程或努力，不能用来计量苹果这类具体物品。"}, {"text": "他拍了一番桌子，大家都吓了一跳。", "explanation": "这里应该用〈下〉。番表示一段过程或努力，拍桌子这类瞬时动作用〈下〉，不用番。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91936, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "番", "is_correct": true, "explanation": "番（fān，第一声）即本词，作量词时表示一段过程或努力。"}, {"text": "犯", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是犯错。"}, {"text": "繁", "is_correct": false, "explanation": "fán（第二声）与 fān（第一声）声调不同，意思是繁多、繁忙。"}, {"text": "摊", "is_correct": false, "explanation": "tān（第一声）与 fān（第一声）只有声母不同（t 与 f），意思是摊开。"}, {"text": "攀", "is_correct": false, "explanation": "pān（第一声）与 fān（第一声）只有声母不同（p 与 f），意思是攀登。"}, {"text": "返", "is_correct": false, "explanation": "fǎn（第三声）与 fān（第一声）声调不同，意思是返回。"}], "explanations": {"番": "番（fān，第一声）即本词，作量词时表示一段过程或努力。", "犯": "fàn（第四声）与 fān（第一声）声调不同，意思是犯错。", "繁": "fán（第二声）与 fān（第一声）声调不同，意思是繁多、繁忙。", "摊": "tān（第一声）与 fān（第一声）只有声母不同（t 与 f），意思是摊开。", "攀": "pān（第一声）与 fān（第一声）只有声母不同（p 与 f），意思是攀登。", "返": "fǎn（第三声）与 fān（第一声）声调不同，意思是返回。"}, "sentence_index": null, "correct_answer": "番"}, "level_3": {"options": [{"text": "番", "is_correct": true, "explanation": "番是量词，用于功夫、努力等，表示一定的量或过程，与“花了”“才做好”相符。"}, {"text": "滴", "is_correct": false, "explanation": "语义：“滴”指液体的小点，与“功夫”所指的时间和精力不合。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”多用于平面之物，不能用来计量“功夫”。"}, {"text": "块", "is_correct": false, "explanation": "搭配：“块”指块状物，不能用来计量“功夫”。"}], "explanations": {"番": "番是量词，用于功夫、努力等，表示一定的量或过程，与“花了”“才做好”相符。", "滴": "语义：“滴”指液体的小点，与“功夫”所指的时间和精力不合。", "张": "搭配：“张”多用于平面之物，不能用来计量“功夫”。", "块": "搭配：“块”指块状物，不能用来计量“功夫”。"}, "sentence_index": 6, "correct_answer": "番"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会场里响起一番掌声，很热闹。", "explanation": "这里应该用〈阵〉。番用于话语、努力等过程，不用于一阵一阵的掌声。"}, {"text": "老师给了我一番机会，我很感激。", "explanation": "这里应该用〈次〉。番不能用来计量机会，表示机会的次数要用〈次〉。"}, {"text": "来了一番客人，把屋子都挤满了。", "explanation": "这里应该用〈批〉。番表示一段过程或努力，不用来计量一群人；一群客人应用〈批〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他经过番思考，终于想出了办法。", "corrected_sentence": "他经过一番思考，终于想出了办法。", "error_description": "错误：“经过番思考”；正确：“经过一番思考”。“番”作量词时前面要有数词“一”，不能单独与名词搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她认真地做了番准备，才出门。", "corrected_sentence": "她认真地做了一番准备，才出门。", "error_description": "错误：“做了番准备”；正确：“做了一番准备”。量词“番”前面要有数词“一”，不能直接放在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
