INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "真挚的爱情或爱。", "primary_collocate": null, "pronunciation": "zhēn ài", "ipa": "ʈʂən˥ aɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他们之间有真爱，所以不怕吵架。", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真爱不是钱能买到的。", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于找到了自己的真爱。", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我相信世界上有真爱。", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真爱需要时间，也需要信任。", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一个关于真爱的故事。", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了真爱，他放弃了大城市的工作。", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，真爱就是一起慢慢变老。", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么知道他是你的真爱？", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的真爱让大家很感动。", "target_word": "真爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "真愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，真挚的爱情或爱，如“找到真爱”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真爱", "is_correct": true, "explanation": "真爱指真挚的爱情，与“不怕吵架”的因果相合，说明感情牢固。"}, {"text": "仇恨", "is_correct": false, "explanation": "语义：“仇恨”与“不怕吵架”的因果相悖，之间有仇恨不会不怕吵架。"}, {"text": "误会", "is_correct": false, "explanation": "语义：“误会”与“所以不怕吵架”没有因果关系，句子不通。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“账单”是具体的单据，不能说“之间有账单”。"}], "explanations": {"真爱": "真爱指真挚的爱情，与“不怕吵架”的因果相合，说明感情牢固。", "仇恨": "语义：“仇恨”与“不怕吵架”的因果相悖，之间有仇恨不会不怕吵架。", "误会": "语义：“误会”与“所以不怕吵架”没有因果关系，句子不通。", "账单": "搭配：“账单”是具体的单据，不能说“之间有账单”。"}, "sentence_index": 0, "correct_answer": "真爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把真爱装进了箱子里。", "explanation": "这里的“真爱”指抽象的爱情，不能像具体物品一样装进箱子。"}, {"text": "这份真爱的工资很高。", "explanation": "这里的“真爱”指真挚的爱情，不能用来修饰工资这类收入。"}, {"text": "她终于找到了一本真爱。", "explanation": "这里应该用〈份〉。真爱是抽象的爱情，计量时用“份”，不用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真爱", "is_correct": true, "explanation": "真爱表示真挚的爱情，与“放弃大城市的工作”的动机相合。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是日常用品，不能成为放弃工作的理由，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能作为放弃工作的目的，句子不通。"}, {"text": "容貌", "is_correct": false, "explanation": "语义：“容貌”指外表长相，不能作为放弃大城市工作的理由。"}], "explanations": {"真爱": "真爱表示真挚的爱情，与“放弃大城市的工作”的动机相合。", "雨伞": "语义：“雨伞”是日常用品，不能成为放弃工作的理由，句子不通。", "颜色": "语义：“颜色”不能作为放弃工作的目的，句子不通。", "容貌": "语义：“容貌”指外表长相，不能作为放弃大城市工作的理由。"}, "sentence_index": 6, "correct_answer": "真爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店专卖各种真爱。", "explanation": "这里的“真爱”指真挚的爱情，不能像商品一样拿来买卖。"}, {"text": "她终于找到了一把真爱。", "explanation": "这里应该用〈份〉。真爱是抽象的爱情，不能用“把”计量。"}, {"text": "这件衣服是真爱的，不是假的。", "explanation": "这里的“真爱”指真挚的爱情，不能用来表示“真品”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于找到了属于自己真爱。", "corrected_sentence": "他终于找到了属于自己的真爱。", "error_description": "错误：“属于自己真爱”；正确：“属于自己的真爱”。“自己”作定语修饰“真爱”时须加“的”，否则“自己真爱”会被理解成动词结构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个关于真爱故事。", "corrected_sentence": "这是一个关于真爱的故事。", "error_description": "错误：“关于真爱故事”；正确：“关于真爱的故事”。“关于真爱”作定语修饰“故事”时必须加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
