INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91941, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拜是双手合在一起，或者弯下身子，对别人表示很尊敬。", "primary_collocate": null, "pronunciation": "bài", "ipa": "paɪ̯˥˩", "syllable_count": 1, "sentences": [{"text": "他对着佛像拜了三下。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她双手合十，对着月亮拜了拜。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在祖先的像前拜了一下。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进门以后，他先向老人拜了拜。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在神像前拜着，嘴里小声说话。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学着大人的样子，向老师拜了一下。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天早上都在佛像前拜一拜。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他弯下身子，向客人拜了一拜。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩在奶奶面前双手合在一起，拜了一拜。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人家站在墓前，深深地拜了三次。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拜了", "label": "体标"}, {"form": "拜过", "label": "体标"}, {"form": "拜着", "label": "体标"}], "register": "中性", "sense_fingerprint": "双手合十或弯身行礼，表示尊敬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '334d3bb3-d40f-4673-8ec2-5f77f12859af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拜", "is_correct": true, "explanation": "拜：双手合十或弯身行礼，表示尊敬。"}, {"text": "派", "is_correct": false, "explanation": "派的声母是 p，拜的声母是 b（pài 与 bài），意思是派遣、派出。"}, {"text": "白", "is_correct": false, "explanation": "白与拜声调不同（bái 与 bài），意思是白色。"}, {"text": "摆", "is_correct": false, "explanation": "摆与拜声调不同（bǎi 与 bài），意思是摆放。"}], "explanations": {"拜": "拜：双手合十或弯身行礼，表示尊敬。", "派": "派的声母是 p，拜的声母是 b（pài 与 bài），意思是派遣、派出。", "白": "白与拜声调不同（bái 与 bài），意思是白色。", "摆": "摆与拜声调不同（bǎi 与 bài），意思是摆放。"}, "sentence_index": null, "correct_answer": "拜"}, "level_3": {"options": [{"text": "拜", "is_correct": true, "explanation": "拜：“对着佛像拜了三下”表示向佛像行礼，符合语境。"}, {"text": "亲", "is_correct": false, "explanation": "语义：亲指亲吻，与向佛像行礼表示敬意的意思不符。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是攻击性的动作，与对佛像表示敬意相反。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝用于饮料，“对着佛像喝了三下”说不通，也不表示行礼。"}], "explanations": {"拜": "拜：“对着佛像拜了三下”表示向佛像行礼，符合语境。", "亲": "语义：亲指亲吻，与向佛像行礼表示敬意的意思不符。", "踢": "语义：踢是攻击性的动作，与对佛像表示敬意相反。", "喝": "语义：喝用于饮料，“对着佛像喝了三下”说不通，也不表示行礼。"}, "sentence_index": 0, "correct_answer": "拜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "进门以后，他先向老人拜了招呼。", "explanation": "这里应该用〈打〉。“打招呼”是固定搭配，“拜”不能接“招呼”作宾语。"}, {"text": "他对着祖宗的牌位拜了三份礼物。", "explanation": "这里应该用〈献〉。“拜”是行礼的动作，不能用来表示献上礼物；献礼要用〈献〉。"}, {"text": "他向客人拜了一躬。", "explanation": "这里应该用〈鞠〉。“一躬”与“鞠躬”搭配，“拜”不能和“一躬”组成这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91941, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拜", "is_correct": true, "explanation": "拜：双手合十或弯身行礼，表示尊敬。"}, {"text": "办", "is_correct": false, "explanation": "办与拜韵母不同（bàn 与 bài），意思是办理。"}, {"text": "百", "is_correct": false, "explanation": "百与拜声调不同（bǎi 与 bài），意思是一百。"}, {"text": "柏", "is_correct": false, "explanation": "柏与拜声调不同（bǎi 与 bài），意思是柏树。"}], "explanations": {"拜": "拜：双手合十或弯身行礼，表示尊敬。", "办": "办与拜韵母不同（bàn 与 bài），意思是办理。", "百": "百与拜声调不同（bǎi 与 bài），意思是一百。", "柏": "柏与拜声调不同（bǎi 与 bài），意思是柏树。"}, "sentence_index": null, "correct_answer": "拜"}, "level_3": {"options": [{"text": "拜", "is_correct": true, "explanation": "拜：“奶奶每天早上都在佛像前拜一拜”表示行礼，符合语境。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：扫用于扫除地面等，不能和“一拜”搭配。"}, {"text": "念", "is_correct": false, "explanation": "语义：念指诵读，与“一拜”这种行礼动作不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗是清洁动作，“洗一拜”不成立。"}], "explanations": {"拜": "拜：“奶奶每天早上都在佛像前拜一拜”表示行礼，符合语境。", "扫": "搭配：扫用于扫除地面等，不能和“一拜”搭配。", "念": "语义：念指诵读，与“一拜”这种行礼动作不符。", "洗": "搭配：洗是清洁动作，“洗一拜”不成立。"}, "sentence_index": 6, "correct_answer": "拜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "搬家那天，他拜朋友帮忙搬东西。", "explanation": "这里应该用〈拜托〉。“拜”单用指行礼，表示请求要说“拜托”，不能直接用“拜”。"}, {"text": "他对着国旗拜了一下。", "explanation": "这里应该用〈敬礼〉。“拜”多用于神佛、祖先或长辈，向国旗表示敬意不用“拜”。"}, {"text": "宴会上，他向大家拜了一杯酒。", "explanation": "这里应该用〈敬〉。敬酒是向人举杯致意，“拜”不能用来敬酒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在佛前了拜三次，然后离开寺院。", "corrected_sentence": "她在佛前拜了三次，然后离开寺院。", "error_description": "体标“了”要放在动词“拜”后面，不能放在“拜”前面。错误是“了拜”，正确是“拜了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对着老人拜了三个，表示感谢。", "corrected_sentence": "他对着老人拜了三次，表示感谢。", "error_description": "“拜”是动作，表示动作的次数要用动量词“次”，不能用“个”。错误是“拜了三个”，正确是“拜了三次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
