INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过一定礼节与人结成师徒或亲属等关系。", "primary_collocate": null, "pronunciation": "bài", "ipa": "paɪ̯˥˩", "syllable_count": 1, "sentences": [{"text": "他拜李师傅为师，学了三年木工。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想学画画，可以拜他为师。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王拜了一位老医生做师父。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拜过一位有名的画家为师。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拜了一位老中医为义父，跟着他学医。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学武术，就拜了一位老拳师。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拜了师傅以后，每天早上都练功。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拜那位老人为干爹，已经五年了。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拜了那位歌手为师，每周去上课。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去想学手艺，都要先拜一位师傅为师。", "target_word": "拜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拜了", "label": "体标"}, {"form": "拜过", "label": "体标"}], "register": "中性", "sense_fingerprint": "通过礼节与人结成师徒、亲属等关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '334d3bb3-d40f-4673-8ec2-5f77f12859af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拜", "is_correct": true, "explanation": "拜：通过一定礼节与人结成师徒等关系。"}, {"text": "派", "is_correct": false, "explanation": "派的声母是 p，拜的声母是 b（pài 与 bài），意思是派遣、派出。"}, {"text": "白", "is_correct": false, "explanation": "白与拜声调不同（bái 与 bài），意思是白色。"}, {"text": "摆", "is_correct": false, "explanation": "摆与拜声调不同（bǎi 与 bài），意思是摆放。"}], "explanations": {"拜": "拜：通过一定礼节与人结成师徒等关系。", "派": "派的声母是 p，拜的声母是 b（pài 与 bài），意思是派遣、派出。", "白": "白与拜声调不同（bái 与 bài），意思是白色。", "摆": "摆与拜声调不同（bǎi 与 bài），意思是摆放。"}, "sentence_index": null, "correct_answer": "拜"}, "level_3": {"options": [{"text": "拜", "is_correct": true, "explanation": "拜：“他拜李师傅为师”表示通过礼节结成师徒关系，符合语境。"}, {"text": "骂", "is_correct": false, "explanation": "语义：骂是斥责，与结成师徒关系的礼节不符。"}, {"text": "管", "is_correct": false, "explanation": "搭配：管表示管理或照管，不能与“为师”组成结成师徒的说法。"}, {"text": "罚", "is_correct": false, "explanation": "语义：罚是处分，与拜师的意思不符。"}], "explanations": {"拜": "拜：“他拜李师傅为师”表示通过礼节结成师徒关系，符合语境。", "骂": "语义：骂是斥责，与结成师徒关系的礼节不符。", "管": "搭配：管表示管理或照管，不能与“为师”组成结成师徒的说法。", "罚": "语义：罚是处分，与拜师的意思不符。"}, "sentence_index": 0, "correct_answer": "拜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她拜了一个学生，每天教他画画。", "explanation": "这里应该用〈收〉。拜是徒弟向师傅行礼、正式拜师，师傅收徒要说〈收〉，方向不能颠倒。"}, {"text": "她拜过一位有名的画家为朋友。", "explanation": "这里应该用〈结交〉。“拜”表示通过礼节结成师徒等关系，与“为朋友”不符。"}, {"text": "学校拜了一位有名的画家当老师。", "explanation": "这里应该用〈聘请〉。“拜”用于个人正式收徒，学校请老师要用“聘请”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91942, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拜", "is_correct": true, "explanation": "拜：通过一定礼节与人结成师徒等关系。"}, {"text": "办", "is_correct": false, "explanation": "办与拜韵母不同（bàn 与 bài），意思是办理。"}, {"text": "百", "is_correct": false, "explanation": "百与拜声调不同（bǎi 与 bài），意思是一百。"}, {"text": "柏", "is_correct": false, "explanation": "柏与拜声调不同（bǎi 与 bài），意思是柏树。"}], "explanations": {"拜": "拜：通过一定礼节与人结成师徒等关系。", "办": "办与拜韵母不同（bàn 与 bài），意思是办理。", "百": "百与拜声调不同（bǎi 与 bài），意思是一百。", "柏": "柏与拜声调不同（bǎi 与 bài），意思是柏树。"}, "sentence_index": null, "correct_answer": "拜"}, "level_3": {"options": [{"text": "拜", "is_correct": true, "explanation": "拜：“弟弟拜了师傅以后”表示拜师，符合语境。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是动作，不能表示结成师徒关系。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：跑是不及物动作，不能说“跑了师傅”。"}, {"text": "砸", "is_correct": false, "explanation": "语义：砸表示击打，与拜师的礼节不符。"}], "explanations": {"拜": "拜：“弟弟拜了师傅以后”表示拜师，符合语境。", "踢": "语义：踢是动作，不能表示结成师徒关系。", "跑": "搭配：跑是不及物动作，不能说“跑了师傅”。", "砸": "语义：砸表示击打，与拜师的礼节不符。"}, "sentence_index": 6, "correct_answer": "拜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过去想学手艺，都要先拜一位师傅为老板。", "explanation": "这里应该用〈为师〉。“拜”结成的是师徒关系，不能与“老板”构成这种关系。"}, {"text": "过去想学手艺，都要先拜一位师傅为徒弟。", "explanation": "这里应该用〈为师〉。拜的是师傅，应说“拜……为师”；“为徒弟”把关系说反了。"}, {"text": "过去想学手艺，都要先拜一位师傅为客户。", "explanation": "这里应该用〈为师〉。“拜”结成的是师徒关系，“客户”不属于这种关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候拜了过一位师傅。", "corrected_sentence": "他小时候拜过一位师傅。", "error_description": "体标“过”不能和“了”并用，表示曾经拜过要说“拜过”。错误是“拜了过”，正确是“拜过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他十几岁就过拜一位木匠为师。", "corrected_sentence": "他十几岁就拜过一位木匠为师。", "error_description": "体标“过”要放在动词后面，不能放在动词前面。错误是“过拜”，正确是“拜过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
