INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91943, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "器材是做事用的工具和东西。", "primary_collocate": null, "pronunciation": "qì cái", "ipa": "tɕʰi˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "学校买了一批新的体育器材。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套摄影器材很贵。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把器材都放进了仓库。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们带着修路的器材去了山上。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的器材要小心使用。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把用完的器材放回原来的地方。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没有器材，没法修这台机器。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院新来了一批检查身体的器材。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师借给我一套画画的器材。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些器材都是爸爸自己买的。", "target_word": "器材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套器材", "label": "量词"}, {"form": "一批器材", "label": "量词"}, {"form": "体育器材", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：做事用的工具和东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91943, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "器材", "is_correct": true, "explanation": "正确。“体育器材”指体育活动用的器具，是这里唯一能填入空位的词。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏音乐用的，与“体育”不相符。"}, {"text": "体育馆", "is_correct": false, "explanation": "搭配：“买了一批”只说物品，体育馆是建筑，不能成批购买。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不能说学校买了一批“体育教室”。"}], "explanations": {"器材": "正确。“体育器材”指体育活动用的器具，是这里唯一能填入空位的词。", "乐器": "语义：乐器是演奏音乐用的，与“体育”不相符。", "体育馆": "搭配：“买了一批”只说物品，体育馆是建筑，不能成批购买。", "教室": "语义：教室是上课的地方，不能说学校买了一批“体育教室”。"}, "sentence_index": 0, "correct_answer": "器材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店每天都要采购新鲜的器材。", "explanation": "这里应该用〈食材〉。“新鲜”形容食物，器材是做事用的工具，不能说新鲜的器材。"}, {"text": "孩子们抢着吃器材，因为很好吃。", "explanation": "这里应该用〈食物〉。食物可以吃，器材是做事用的工具，不能吃。"}, {"text": "他每天认真弹奏器材。", "explanation": "这里应该用〈乐器〉。弹奏的是乐器，器材是做事用的工具，不能用“弹奏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "器材", "is_correct": true, "explanation": "正确。“没有器材”说明缺少修理用的工具，与“没法修”前后呼应。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：修机器不需要歌曲，“没有歌曲，没法修机器”因果关系不成立。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果与修机器无关，“没有水果，没法修机器”说不通。"}, {"text": "作文", "is_correct": false, "explanation": "搭配：“修”的对象是机器，不能把“作文”当作修理的条件。"}], "explanations": {"器材": "正确。“没有器材”说明缺少修理用的工具，与“没法修”前后呼应。", "歌曲": "语义：修机器不需要歌曲，“没有歌曲，没法修机器”因果关系不成立。", "水果": "语义：水果与修机器无关，“没有水果，没法修机器”说不通。", "作文": "搭配：“修”的对象是机器，不能把“作文”当作修理的条件。"}, "sentence_index": 6, "correct_answer": "器材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天冷了，他盖着器材睡觉。", "explanation": "这里应该用〈被子〉。盖在身上睡觉用被子，器材是做事用的工具，不能用来盖。"}, {"text": "我用器材写字。", "explanation": "这里应该用〈笔〉。写字用笔，器材是做事用的工具，不能用来写字。"}, {"text": "他把器材喝下去了。", "explanation": "这里应该用〈饮料〉。喝的是饮料，器材是做事用的工具，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校新买了一只体育器材。", "corrected_sentence": "学校新买了一套体育器材。", "error_description": "量词错误：“器材”应用“套”或“批”计量，错误的“一只器材”应改为“一套体育器材”。“只”不能用于成套的器具。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器坏了，我们借了一本器材来修。", "corrected_sentence": "这台机器坏了，我们借了一套器材来修。", "error_description": "量词错误：“器材”不用“本”计量，应说“一套器材”。“本”是书册的量词，不能用于成套的器具。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
