INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "时间较短的影片。", "primary_collocate": null, "pronunciation": "duǎn piàn", "ipa": "tu̯an˨˩˦ pʰi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我在手机上看了一个短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个短片只有三十秒。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡前都看短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我发来一个孩子的短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个短片拍的是我家的小狗。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司做了一个介绍新产品的短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旅行的短片放在网上了。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课前，老师给我们放了一个短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学做短片，不知道从哪儿开始。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短片里的音乐很好听。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "部", "label": "量词"}], "register": "中性", "sense_fingerprint": "时间较短的影片，如手机或网上看的小视频", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a182e01-4fd0-41b9-afec-41667e58b233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短片", "is_correct": true, "explanation": "正确：“短片”指时间较短的影片或视频，手机上能看，与句意相符。"}, {"text": "电影院", "is_correct": false, "explanation": "语义：“电影院”是放映场所，不能在手机上“看”，与“手机上”矛盾。"}, {"text": "剧院", "is_correct": false, "explanation": "语义：“剧院”是演出场所，不能在手机上看，与“手机上”矛盾。"}, {"text": "荧幕", "is_correct": false, "explanation": "语域：“荧幕”是偏书面的说法，口语多说“屏幕”；且“看了一个荧幕”指屏幕本身，不是可看的内容。"}], "explanations": {"短片": "正确：“短片”指时间较短的影片或视频，手机上能看，与句意相符。", "电影院": "语义：“电影院”是放映场所，不能在手机上“看”，与“手机上”矛盾。", "剧院": "语义：“剧院”是演出场所，不能在手机上看，与“手机上”矛盾。", "荧幕": "语域：“荧幕”是偏书面的说法，口语多说“屏幕”；且“看了一个荧幕”指屏幕本身，不是可看的内容。"}, "sentence_index": 0, "correct_answer": "短片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个短片讲的是一座城市的历史，有两个小时。", "explanation": "这里应该用〈长视频〉。“短片”指时间较短的视频，讲两个小时的内容要说“长视频”。"}, {"text": "这部短片分成了三十集，每周播一集。", "explanation": "这里应该用〈电视剧〉。“短片”是单独的短作品，不会分三十集播出；分集播出的作品要说“电视剧”。"}, {"text": "这部短片贴在教室的墙上，大家都能看到。", "explanation": "这里应该用〈海报〉。“短片”是影片，不能贴在墙上；贴在墙上的是海报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短片", "is_correct": true, "explanation": "正确：“短片”是拍成的视频，可以放在网上，与“旅行的”相符。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是出门携带的物品，不能“放在网上”，与句意矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不能“放在网上”，也不是“旅行的”内容。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能“放在网上”，与句意矛盾。"}], "explanations": {"短片": "正确：“短片”是拍成的视频，可以放在网上，与“旅行的”相符。", "行李": "语义：“行李”是出门携带的物品，不能“放在网上”，与句意矛盾。", "冰箱": "语义：“冰箱”是家用电器，不能“放在网上”，也不是“旅行的”内容。", "椅子": "语义：“椅子”是家具，不能“放在网上”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "短片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个短片的比分是二比一，很精彩。", "explanation": "这里应该用〈比赛〉。“短片”是影片，没有比分；比分只用于比赛。"}, {"text": "这个短片有十课，每课讲一个语法。", "explanation": "这里应该用〈教材〉。“短片”是视频，没有“课”的结构；课和语法属于教材。"}, {"text": "这个短片有三百公里长，很壮观。", "explanation": "这里应该用〈河〉。“短片”指很短的影片，不能用来形容三百公里的长度；这样的长度只用于河流等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她给朋友发了一只短片。", "corrected_sentence": "她给朋友发了一个短片。", "error_description": "错误：量词“只”用于动物，短片应用“个”。正确形式是“发了一个短片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友昨晚给我发了一张短片。", "corrected_sentence": "朋友昨晚给我发了一个短片。", "error_description": "错误：量词“张”用于纸张、照片等平面物，短片应用“个”。正确形式是“发了一个短片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
