INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "支援是别人有难处的时候，你送东西或者去帮忙。", "primary_collocate": null, "pronunciation": "zhī yuán", "ipa": "ʈʂɨ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "邻居家有困难，我们去支援他们。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友家的房子进水了，我立刻去支援他。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里发生火灾，大家都来支援。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病住院，同事们捐钱支援他。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家没钱买书，老师常常支援我。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最困难的时候，是你支援了她。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友遇到麻烦，我一定去支援。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨冲坏了房子，邻居们都来支援我们。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他支援过我很多次，我不会忘。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学有难处，大家都愿意支援他。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支援了", "label": "体标"}, {"form": "支援过", "label": "体标"}], "register": "中性", "sense_fingerprint": "别人遇到困难时送东西或去帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支援", "is_correct": true, "explanation": "正确：zhī yuán，指别人有难处时送东西或去帮忙。"}, {"text": "资源", "is_correct": false, "explanation": "资 zī（第一声）与 zhī（第一声）声母不同，z 与 zh 相混，意思是资源。"}, {"text": "职员", "is_correct": false, "explanation": "职 zhí（第二声）与 zhī（第一声）声调不同，意思是职员。"}, {"text": "志愿", "is_correct": false, "explanation": "志 zhì（第四声）与 zhī（第一声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是志愿。"}, {"text": "机缘", "is_correct": false, "explanation": "jī（第一声）与 zhī（第一声）声母不同，j 与 zh 相混，意思是机缘。"}], "explanations": {"支援": "正确：zhī yuán，指别人有难处时送东西或去帮忙。", "资源": "资 zī（第一声）与 zhī（第一声）声母不同，z 与 zh 相混，意思是资源。", "职员": "职 zhí（第二声）与 zhī（第一声）声调不同，意思是职员。", "志愿": "志 zhì（第四声）与 zhī（第一声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是志愿。", "机缘": "jī（第一声）与 zhī（第一声）声母不同，j 与 zh 相混，意思是机缘。"}, "sentence_index": null, "correct_answer": "支援"}, "level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "句中“有困难”的人需要别人帮忙，“支援”指送东西或去帮忙，符合语境。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”是丢下不管，与“有困难”的人需要帮助、我们去帮忙的语境相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥笑，与我们去帮忙的善意语境相矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”多用于场所、展览，不能直接以“他们”这样的人作对象来表示去帮忙。"}], "explanations": {"支援": "句中“有困难”的人需要别人帮忙，“支援”指送东西或去帮忙，符合语境。", "抛弃": "语义：“抛弃”是丢下不管，与“有困难”的人需要帮助、我们去帮忙的语境相反。", "嘲笑": "语义：“嘲笑”是讥笑，与我们去帮忙的善意语境相矛盾。", "参观": "搭配：“参观”多用于场所、展览，不能直接以“他们”这样的人作对象来表示去帮忙。"}, "sentence_index": 0, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都支援他的决定。", "explanation": "这里应该用〈支持〉。支援指用人力、物资去帮助有困难的人或单位，对决定和意见表示赞成要用支持。"}, {"text": "父母的话支援了我，我很有信心。", "explanation": "这里应该用〈鼓励〉。支援指用人力、物资去帮忙，给人精神上的激励要用鼓励。"}, {"text": "这根柱子支援着屋顶。", "explanation": "这里应该用〈支撑〉。支援的对象是人或单位，柱子承托屋顶要用支撑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "句中“朋友遇到麻烦”，说话人说“我一定去”，“支援”指去帮忙，符合语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受、不答应，与“我一定去”的主动帮忙相矛盾。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”是躲开，与“我一定去”的意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”需要带所讨论的内容，不能只说“我一定去讨论”来表示去帮朋友。"}], "explanations": {"支援": "句中“朋友遇到麻烦”，说话人说“我一定去”，“支援”指去帮忙，符合语境。", "拒绝": "语义：“拒绝”是不接受、不答应，与“我一定去”的主动帮忙相矛盾。", "逃避": "语义：“逃避”是躲开，与“我一定去”的意思相反。", "讨论": "配价：“讨论”需要带所讨论的内容，不能只说“我一定去讨论”来表示去帮朋友。"}, "sentence_index": 6, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们支援新同学的加入。", "explanation": "这里应该用〈欢迎〉。支援指用人力、物资去帮忙，对新人的加入表示欢迎要用欢迎。"}, {"text": "大家支援他的生日。", "explanation": "这里应该用〈庆祝〉。支援的对象是需要帮助的人或单位，给生日表示喜庆要用庆祝。"}, {"text": "老师支援了我的努力。", "explanation": "这里应该用〈表扬〉。支援指给予实际帮助，对别人的努力给予肯定要用表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "救援队支援地很及时。", "corrected_sentence": "救援队支援得很及时。", "error_description": "错误：“支援地很及时”。正确：“支援得很及时”。补语标记应用“得”，不能用表示修饰的“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年去支援过了灾区。", "corrected_sentence": "他去年去支援过灾区。", "error_description": "错误：“支援过了灾区”。正确：“支援过灾区”。“过”已表示经历，与“了”不能同用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
