INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用人力、物力、财力或其他方式支持和援助。", "primary_collocate": null, "pronunciation": "zhī yuán", "ipa": "ʈʂɨ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "国家用物资支援受灾的地区。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派了十个工人去支援工厂。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们去山区支援当地的医院。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多国家用资金支援灾区。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的医生支援了武汉的医院。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用技术支援这个小城市。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把粮食送去，支援前线。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工厂缺人，老厂派人来支援。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司愿意出钱支援学校建图书馆。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府一直在资金上支援农村教育。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支援了", "label": "体标"}, {"form": "支援过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用人力物力财力支持援助某地或某单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支援", "is_correct": true, "explanation": "正确：zhī yuán，指用人力、物力、财力等支持和帮助。"}, {"text": "资源", "is_correct": false, "explanation": "资 zī（第一声）与 zhī（第一声）声母不同，z 与 zh 相混，意思是资源。"}, {"text": "职员", "is_correct": false, "explanation": "职 zhí（第二声）与 zhī（第一声）声调不同，意思是职员。"}, {"text": "志愿", "is_correct": false, "explanation": "志 zhì（第四声）与 zhī（第一声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是志愿。"}, {"text": "机缘", "is_correct": false, "explanation": "jī（第一声）与 zhī（第一声）声母不同，j 与 zh 相混，意思是机缘。"}], "explanations": {"支援": "正确：zhī yuán，指用人力、物力、财力等支持和帮助。", "资源": "资 zī（第一声）与 zhī（第一声）声母不同，z 与 zh 相混，意思是资源。", "职员": "职 zhí（第二声）与 zhī（第一声）声调不同，意思是职员。", "志愿": "志 zhì（第四声）与 zhī（第一声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是志愿。", "机缘": "jī（第一声）与 zhī（第一声）声母不同，j 与 zh 相混，意思是机缘。"}, "sentence_index": null, "correct_answer": "支援"}, "level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "句中“用物资”和“受灾的地区”，“支援”指用物资帮助地区，符合语境。"}, {"text": "回避", "is_correct": false, "explanation": "语义：“回避”是躲开，与国家用物资去帮助受灾地区的意思相反。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”用于活动、组织，不能直接接“受灾的地区”作宾语。"}, {"text": "出售", "is_correct": false, "explanation": "配价：“出售”的宾语应是商品，不能接“受灾的地区”，句子不成立。"}], "explanations": {"支援": "句中“用物资”和“受灾的地区”，“支援”指用物资帮助地区，符合语境。", "回避": "语义：“回避”是躲开，与国家用物资去帮助受灾地区的意思相反。", "参加": "搭配：“参加”用于活动、组织，不能直接接“受灾的地区”作宾语。", "出售": "配价：“出售”的宾语应是商品，不能接“受灾的地区”，句子不成立。"}, "sentence_index": 0, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们支援这个方案。", "explanation": "这里应该用〈支持〉。支援指用人力、物资去帮助，对方案表示赞成要用支持。"}, {"text": "他用现金支援了房租。", "explanation": "这里应该用〈支付〉。支援指给需要帮助的人或单位送去物资，付房租要用支付。"}, {"text": "大家支援她的善良。", "explanation": "这里应该用〈赞美〉。支援指给予实际帮助，对别人的品质表示称赞要用赞美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "句中“把粮食送去”，“支援前线”指用物资去帮助前线，符合语境。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是乐于接待，与“把粮食送去”的帮助语境不符，“欢迎前线”不成立。"}, {"text": "谴责", "is_correct": false, "explanation": "语义：“谴责”是严厉批评，与送粮食的善意语境相反。"}, {"text": "撤退", "is_correct": false, "explanation": "配价：“撤退”要接离开的地点，如“撤离前线”，不能直接说“撤退前线”。"}], "explanations": {"支援": "句中“把粮食送去”，“支援前线”指用物资去帮助前线，符合语境。", "欢迎": "语义：“欢迎”是乐于接待，与“把粮食送去”的帮助语境不符，“欢迎前线”不成立。", "谴责": "语义：“谴责”是严厉批评，与送粮食的善意语境相反。", "撤退": "配价：“撤退”要接离开的地点，如“撤离前线”，不能直接说“撤退前线”。"}, "sentence_index": 6, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家支援新年的到来。", "explanation": "这里应该用〈欢迎〉。支援指用人力、物资去帮忙，对新年的到来表示迎接要用欢迎。"}, {"text": "全家支援奶奶的寿辰。", "explanation": "这里应该用〈庆祝〉。支援指给需要帮助的人或单位送去物资，给寿辰表示祝贺要用庆祝。"}, {"text": "政府支援了英雄的事迹。", "explanation": "这里应该用〈表彰〉。支援指给予实际帮助，对英雄的事迹予以公开赞扬要用表彰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们正在支援了灾区的重建。", "corrected_sentence": "工人们正在支援灾区的重建。", "error_description": "错误：“正在支援了”。正确：“正在支援”。“正在”表示动作进行，与表示完成的“了”不能同用，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂的工人们一直支援了农村的学校。", "corrected_sentence": "工厂的工人们一直支援着农村的学校。", "error_description": "错误：“一直支援了”。正确：“一直支援着”。“一直”表示持续，句中没有时段词，应用持续体“着”，不用表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91949, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明白", "is_correct": true, "explanation": "正确：困惑与明白意思相对，困惑是想不明白，明白是想清楚了。"}, {"text": "热心", "is_correct": false, "explanation": "无关：热心形容待人的态度，与困惑没有反义关系。"}, {"text": "诚实", "is_correct": false, "explanation": "无关：诚实形容品性，与困惑没有反义关系。"}, {"text": "宽厚", "is_correct": false, "explanation": "无关：宽厚形容待人的品性，与困惑没有反义关系。"}], "correct_answer": "明白", "explanations": {"明白": "正确：困惑与明白意思相对，困惑是想不明白，明白是想清楚了。", "热心": "无关：热心形容待人的态度，与困惑没有反义关系。", "诚实": "无关：诚实形容品性，与困惑没有反义关系。", "宽厚": "无关：宽厚形容待人的品性，与困惑没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91949, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明白", "is_correct": true, "explanation": "正确：困惑与明白意思相对，困惑是想不明白，明白是想清楚了。"}, {"text": "活泼", "is_correct": false, "explanation": "无关：活泼形容性格或样子，与困惑没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "无关：认真形容做事的态度，与困惑没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "无关：勇敢形容面对困难的品质，与困惑没有反义关系。"}], "correct_answer": "明白", "explanations": {"明白": "正确：困惑与明白意思相对，困惑是想不明白，明白是想清楚了。", "活泼": "无关：活泼形容性格或样子，与困惑没有反义关系。", "认真": "无关：认真形容做事的态度，与困惑没有反义关系。", "勇敢": "无关：勇敢形容面对困难的品质，与困惑没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91949, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "困惑是想不明白，心里乱乱的。", "primary_collocate": null, "pronunciation": "kùn huò", "ipa": "kʰuən˥˩ xuo˥˩", "syllable_count": 2, "sentences": [{"text": "这件事我想了很久，还是很困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答让我心里很困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对自己的选择有点儿困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想不明白，所以很困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她皱着眉头，一脸困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么会这样？我真的很困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对这么多问题，他越来越困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的结尾我看了好几遍，心里还是很困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不明白她的意思，心里十分困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来有点儿困惑，没有说话。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "困惑的", "label": "定语形式"}, {"form": "困惑地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "想不明白、心里混乱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02255d63-88e7-4cee-a6d4-c25bafea51c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困惑", "is_correct": true, "explanation": "正确：困惑表示想不明白、心里乱，符合“想了很久”之后的状态。"}, {"text": "有力", "is_correct": false, "explanation": "语义：“有力”形容力量或言辞，不能形容想不明白的心理状态。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”一般形容声音，不能说人“还是很清脆”。"}, {"text": "大方", "is_correct": false, "explanation": "体貌：“大方”形容人的举止神态，不用来说想不明白。"}], "explanations": {"困惑": "正确：困惑表示想不明白、心里乱，符合“想了很久”之后的状态。", "有力": "语义：“有力”形容力量或言辞，不能形容想不明白的心理状态。", "清脆": "搭配：“清脆”一般形容声音，不能说人“还是很清脆”。", "大方": "体貌：“大方”形容人的举止神态，不用来说想不明白。"}, "sentence_index": 0, "correct_answer": "困惑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "连续工作十个小时，他很困惑。", "explanation": "这里应该用〈困顿〉。困惑表示想不明白，工作后的疲乏要说困顿。"}, {"text": "考试到深夜，他很困惑，眼睛都睁不开了。", "explanation": "这里应该用〈困倦〉。困惑表示想不明白，眼睛睁不开、想睡觉要说困倦。"}, {"text": "长途跋涉后，他很困惑。", "explanation": "这里应该用〈疲倦〉。困惑表示想不明白，身体累要说疲倦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困惑", "is_correct": true, "explanation": "正确：困惑表示想不明白，符合“越来越”这种心理的变化。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，不能用来描述心理变化。"}, {"text": "透亮", "is_correct": false, "explanation": "体貌：“透亮”形容光线或眼睛，不形容人面对问题时的心理状态。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”形容身体或物件，与“面对这么多问题”的心理变化不协调。"}], "explanations": {"困惑": "正确：困惑表示想不明白，符合“越来越”这种心理的变化。", "响亮": "语义：“响亮”形容声音，不能用来描述心理变化。", "透亮": "体貌：“透亮”形容光线或眼睛，不形容人面对问题时的心理状态。", "结实": "语义：“结实”形容身体或物件，与“面对这么多问题”的心理变化不协调。"}, "sentence_index": 6, "correct_answer": "困惑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被蚊子叮了一晚上，很困惑。", "explanation": "这里应该用〈痒〉。困惑表示想不明白，被叮后的感觉要说痒。"}, {"text": "他的手被开水烫伤了，很困惑。", "explanation": "这里应该用〈疼〉。困惑表示想不明白，身体受伤的感觉要说疼。"}, {"text": "饿了一整天，他很困惑。", "explanation": "这里应该用〈饥饿〉。困惑表示想不明白，饿的感觉要说饥饿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她困惑得看着我。", "corrected_sentence": "她困惑地看着我。", "error_description": "“得”误用：状语“困惑”后应用“地”，“得”用于补语，不能用在状语后。应说“困惑地看着我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他困惑样子让人担心。", "corrected_sentence": "他困惑的样子让人担心。", "error_description": "定语与名词之间漏了“的”。双音节形容词作定语时通常要加“的”，应说“困惑的样子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91950, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明白", "is_correct": true, "explanation": "正确：困惑与明白意思相对，一个是想不清楚，一个是想清楚了。"}, {"text": "热情", "is_correct": false, "explanation": "无关：热情形容态度，与困惑没有反义关系。"}, {"text": "诚恳", "is_correct": false, "explanation": "无关：诚恳形容待人的态度，与困惑没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "无关：勇敢形容面对困难的品质，与困惑没有反义关系。"}], "correct_answer": "明白", "explanations": {"明白": "正确：困惑与明白意思相对，一个是想不清楚，一个是想清楚了。", "热情": "无关：热情形容态度，与困惑没有反义关系。", "诚恳": "无关：诚恳形容待人的态度，与困惑没有反义关系。", "勇敢": "无关：勇敢形容面对困难的品质，与困惑没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91950, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明白", "is_correct": true, "explanation": "正确：困惑与明白意思相对，一个是想不清楚，一个是想清楚了。"}, {"text": "轻松", "is_correct": false, "explanation": "无关：轻松形容心情或事情不费力，与困惑没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：安静形容环境或状态平和，与困惑没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "无关：温和形容性格或态度，与困惑没有反义关系。"}], "correct_answer": "明白", "explanations": {"明白": "正确：困惑与明白意思相对，一个是想不清楚，一个是想清楚了。", "轻松": "无关：轻松形容心情或事情不费力，与困惑没有反义关系。", "安静": "无关：安静形容环境或状态平和，与困惑没有反义关系。", "温和": "无关：温和形容性格或态度，与困惑没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91950, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "感到疑惑，不知如何是好。", "primary_collocate": null, "pronunciation": "kùn huò", "ipa": "kʰuən˥˩ xuo˥˩", "syllable_count": 2, "sentences": [{"text": "听了这个消息，他感到很困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着地图，不知道该往哪儿走，很困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话让我更困惑了。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题太难了，同学们都很困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他困惑地问：“我到底做错了什么？”", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一脸困惑，不知道怎么回答。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这个新规定，大家都有点儿困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很困惑，他为什么突然不说话了？", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到奇怪的路牌，游客们十分困惑。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他困惑的样子让大家都笑了。", "target_word": "困惑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "困惑的", "label": "定语形式"}, {"form": "困惑地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "感到疑惑、不知所措", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02255d63-88e7-4cee-a6d4-c25bafea51c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困惑", "is_correct": true, "explanation": "正确：困惑表示感到疑惑、不知如何是好，符合“听了这个消息”后的心理。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”形容认识或说明的明白程度，不能用来形容感受。"}, {"text": "结实", "is_correct": false, "explanation": "体貌：“结实”形容身体或物件的状态，不形容人的心理感受。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”指能看透，不能用来形容一个人的感受。"}], "explanations": {"困惑": "正确：困惑表示感到疑惑、不知如何是好，符合“听了这个消息”后的心理。", "清楚": "语义：“清楚”形容认识或说明的明白程度，不能用来形容感受。", "结实": "体貌：“结实”形容身体或物件的状态，不形容人的心理感受。", "透明": "语义：“透明”指能看透，不能用来形容一个人的感受。"}, "sentence_index": 0, "correct_answer": "困惑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里十二点了，他很困惑，想睡觉。", "explanation": "这里应该用〈困倦〉。困惑表示心里疑惑、不知如何是好；想睡觉要说困倦。"}, {"text": "这份工作很困惑，他每天都很累。", "explanation": "这里应该用〈辛苦〉。困惑形容人的心理状态，不用来形容工作的劳累；说工作累要用“辛苦”。"}, {"text": "他跑了十公里，很困惑。", "explanation": "这里应该用〈疲惫〉。困惑表示想不明白，跑完步身体累要说“疲惫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困惑", "is_correct": true, "explanation": "正确：困惑表示感到疑惑，符合“大家都有点儿”对新规定的反应。"}, {"text": "复杂", "is_correct": false, "explanation": "语义：“复杂”形容事物，说“大家有点儿复杂”指人，语义不通。"}, {"text": "笔直", "is_correct": false, "explanation": "体貌：“笔直”形容线条或姿态，不能形容人的心理状态。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，不能用来描述大家对规定的反应。"}], "explanations": {"困惑": "正确：困惑表示感到疑惑，符合“大家都有点儿”对新规定的反应。", "复杂": "语义：“复杂”形容事物，说“大家有点儿复杂”指人，语义不通。", "笔直": "体貌：“笔直”形容线条或姿态，不能形容人的心理状态。", "响亮": "语义：“响亮”形容声音，不能用来描述大家对规定的反应。"}, "sentence_index": 6, "correct_answer": "困惑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被蚊子叮得很困惑。", "explanation": "这里应该用〈痒〉。困惑表示疑惑、不知如何是好，被叮后的感觉要说痒。"}, {"text": "他的手被开水烫伤，很困惑。", "explanation": "这里应该用〈疼〉。困惑表示疑惑、不知所措，身体受伤的感觉要说疼。"}, {"text": "他一天没喝水，很困惑。", "explanation": "这里应该用〈口渴〉。困惑表示疑惑，口干的感觉要说口渴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都对这个新规定很困惑着。", "corrected_sentence": "大家都对这个新规定很困惑。", "error_description": "“困惑”是形容词，前面有“很”修饰时，后面不能加“着”。应说“很困惑”，不说“很困惑着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她困惑眼神让人心疼。", "corrected_sentence": "她困惑的眼神让人心疼。", "error_description": "定语与名词之间漏了“的”。双音节形容词作定语时通常要加“的”，应说“困惑的眼神”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
