INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91951, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没想到，看见了某个人。", "primary_collocate": null, "pronunciation": "pèng dào", "ipa": "pʰɤŋ˥˩ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我在超市碰到了老同学。", "target_word": "碰到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天上班路上，我碰到了王老师。", "target_word": "碰到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电梯里碰到了以前的邻居。", "target_word": "碰到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你猜我今天在车站碰到谁了？", "target_word": "碰到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到会在北京碰到你。", "target_word": "碰到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末逛街时，她碰到了大学同学。", "target_word": "碰到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外碰到老乡，我特别高兴。", "target_word": "碰到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在公园碰到过他两次。", "target_word": "碰到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班回家的路上，我碰到了老板。", "target_word": "碰到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在书店碰到了小学老师。", "target_word": "碰到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "碰到了", "label": "体标"}, {"form": "碰到过", "label": "体标"}], "register": "口语", "sense_fingerprint": "没有约好，意外遇见某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9d6783f-ace1-4265-9d14-fc3a3d5379b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91951, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "碰到", "is_correct": true, "explanation": "正确答案是“碰到”（pèng dào），即偶然遇见某人。"}, {"text": "碰倒", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，碰倒指撞翻，意思不同。"}, {"text": "捧到", "is_correct": false, "explanation": "pěng（第三声）与 pèng（第四声）声调不同，捧到指双手托着送到某处。"}, {"text": "梦到", "is_correct": false, "explanation": "mèng 与 pèng 声母不同（m 与 p），梦到指做梦时出现某人或某事。"}, {"text": "蹦到", "is_correct": false, "explanation": "bèng 与 pèng 声母不同（b 与 p），蹦到指跳到某处。"}], "explanations": {"碰到": "正确答案是“碰到”（pèng dào），即偶然遇见某人。", "碰倒": "dǎo（第三声）与 dào（第四声）声调不同，碰倒指撞翻，意思不同。", "捧到": "pěng（第三声）与 pèng（第四声）声调不同，捧到指双手托着送到某处。", "梦到": "mèng 与 pèng 声母不同（m 与 p），梦到指做梦时出现某人或某事。", "蹦到": "bèng 与 pèng 声母不同（b 与 p），蹦到指跳到某处。"}, "sentence_index": null, "correct_answer": "碰到"}, "level_3": {"options": [{"text": "拜访", "is_correct": false, "explanation": "语义：拜访指有意去看望某人，意外遇见不是拜访，超市里不能“拜访”同学。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛掉的意思，“扔了老同学”与句意不符。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指赠送或送别，与“意外遇见老同学”的句意不合。"}, {"text": "碰到", "is_correct": true, "explanation": "正确：“碰到”表示没想到而遇见某人，与“在超市”和“老同学”相符。"}], "explanations": {"拜访": "语义：拜访指有意去看望某人，意外遇见不是拜访，超市里不能“拜访”同学。", "扔": "语义：扔是抛掉的意思，“扔了老同学”与句意不符。", "送": "语义：“送”指赠送或送别，与“意外遇见老同学”的句意不合。", "碰到": "正确：“碰到”表示没想到而遇见某人，与“在超市”和“老同学”相符。"}, "sentence_index": 0, "correct_answer": "碰到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我特意碰到王老师，想请他帮忙。", "explanation": "这里应该用〈拜访〉。碰到是没想到而遇见，不能与“特意”搭配，有计划地去看人要用〈拜访〉。"}, {"text": "我明天要去碰到客户，谈合同。", "explanation": "这里应该用〈见〉。碰到是意外的遇见，不能用于事先约好的见面。"}, {"text": "飞机终于碰到了北京。", "explanation": "这里应该用〈到〉。碰到表示意外遇见某人，不能表示抵达某个地点，抵达要用〈到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91951, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "语义：“擦”指用布等抹去脏东西，“擦老乡”不合句意。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”含贬义，与“我特别高兴”矛盾。"}, {"text": "骂", "is_correct": false, "explanation": "语义：遇见老乡不会去骂，“骂老乡，我特别高兴”与句意不合。"}, {"text": "碰到", "is_correct": true, "explanation": "正确：“碰到”表示在国外意外遇见老乡，与“我特别高兴”相符。"}], "explanations": {"擦": "语义：“擦”指用布等抹去脏东西，“擦老乡”不合句意。", "欺负": "语义：“欺负”含贬义，与“我特别高兴”矛盾。", "骂": "语义：遇见老乡不会去骂，“骂老乡，我特别高兴”与句意不合。", "碰到": "正确：“碰到”表示在国外意外遇见老乡，与“我特别高兴”相符。"}, "sentence_index": 6, "correct_answer": "碰到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我碰到他很多年了。", "explanation": "这里应该用〈认识〉。碰到是一次意外的相遇，不能表示持续多年的关系。"}, {"text": "我们约好了明天下午三点在咖啡馆碰到。", "explanation": "这里应该用〈见面〉。碰到是没想到而遇见某人，不能用于事先约好的见面。"}, {"text": "我每个周末都特意去爷爷家碰到他。", "explanation": "这里应该用〈看望〉。碰到是没想到而遇见某人，不能与“特意”这种有计划的行为搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在街上没碰到了一个老朋友。", "corrected_sentence": "我在街上碰到了一个老朋友。", "error_description": "否定错误。“没”与“了”不能同用：否定已完成的动作用“没碰到”，肯定已完成的动作用“碰到了”。此句应去掉“没”，改为“碰到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前在火车上碰到着一个熟人。", "corrected_sentence": "我以前在火车上碰到过一个熟人。", "error_description": "体标错误。“碰到过”表示有过这样的经历，“着”表示动作持续，此处应用“过”，改为“碰到过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
