INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91955, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "团年是过年前一家人聚在一起吃饭。", "primary_collocate": null, "pronunciation": "tuán nián", "ipa": "tʰwan³⁵ njɛn³⁵", "syllable_count": 2, "sentences": [{"text": "今年我们全家在奶奶家团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "腊月二十八，大家都回老家团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年过年前，我们都要团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作太忙，没有回家团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天晚上一起团年，你也来吧。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一早就去买菜，晚上要和家人团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年前一天，一家人高高兴兴地团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我们去饭店团年，不在家做饭了。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，团年的时候人要到齐。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远在外地的孩子都赶回来团年了。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "团年了", "label": "体标"}, {"form": "团年饭", "label": "复合"}], "register": "口语", "sense_fingerprint": "过年前全家人聚在一起吃饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "团年", "is_correct": true, "explanation": "正确。“团年”指过年前全家人聚在一起吃饭，符合“全家在奶奶家”的语境。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“在奶奶家”后不说“考试”，考试一般在学校或考场进行。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：搬家指迁居，与“全家在奶奶家聚在一起”的意思不符。"}, {"text": "出差", "is_correct": false, "explanation": "语义：出差是外出办公，与全家在奶奶家过年的语境冲突。"}], "explanations": {"团年": "正确。“团年”指过年前全家人聚在一起吃饭，符合“全家在奶奶家”的语境。", "考试": "搭配：“在奶奶家”后不说“考试”，考试一般在学校或考场进行。", "搬家": "语义：搬家指迁居，与“全家在奶奶家聚在一起”的意思不符。", "出差": "语义：出差是外出办公，与全家在奶奶家过年的语境冲突。"}, "sentence_index": 0, "correct_answer": "团年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大年初一，我们挨家挨户团年。", "explanation": "这里应该用〈拜年〉。团年指过年前全家一起吃饭，大年初一挨家走动不叫团年。"}, {"text": "同学们周末去KTV团年。", "explanation": "这里应该用〈聚会〉。团年只指一家人过年前的聚餐，同学聚会不叫团年。"}, {"text": "小明在学校的运动会上团年。", "explanation": "这里应该用〈比赛〉。团年是过年前一家人聚餐，运动会上比赛，不能说团年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "团年", "is_correct": true, "explanation": "正确。“过年前一天，一家人高高兴兴地团年”，符合过年前全家聚餐的意思。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣与“高高兴兴”的情绪相反，句子说不通。"}, {"text": "吵架", "is_correct": false, "explanation": "搭配：“高高兴兴地”不能修饰“吵架”。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不能“高高兴兴”地进行，与语境冲突。"}], "explanations": {"团年": "正确。“过年前一天，一家人高高兴兴地团年”，符合过年前全家聚餐的意思。", "哭泣": "语义：哭泣与“高高兴兴”的情绪相反，句子说不通。", "吵架": "搭配：“高高兴兴地”不能修饰“吵架”。", "生病": "语义：生病不能“高高兴兴”地进行，与语境冲突。"}, "sentence_index": 6, "correct_answer": "团年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "除夕，我们去坟前团年。", "explanation": "这里应该用〈祭祖〉。去坟前是祭祖，团年是家人在饭桌上吃团圆饭，不用于坟前。"}, {"text": "小时候，我考试前都团年。", "explanation": "这里应该用〈复习〉。团年是过年前全家聚餐，考试前是复习，不能用团年。"}, {"text": "我们在生日那天团年。", "explanation": "这里应该用〈过生日〉。团年特指春节前全家聚餐，不用于生日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春节前一天，我们一家人饭店团年。", "corrected_sentence": "春节前一天，我们一家人在饭店团年。", "error_description": "漏掉介词“在”：“饭店”是团年的地点，应说“在饭店团年”，不能直接说“饭店团年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天晚上我们把饭店团年。", "corrected_sentence": "明天晚上我们在饭店团年。", "error_description": "把字句错误：“团年”是不及物动词，不能放在“把”的后面，应说“在饭店团年”，用“在”引出地点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
