INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91956, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "旧俗指除夕全家团聚吃年夜饭。", "primary_collocate": null, "pronunciation": "tuán nián", "ipa": "tʰwan³⁵ njɛn³⁵", "syllable_count": 2, "sentences": [{"text": "旧时除夕，一家人要团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，除夕晚上团年是老规矩。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们老家，除夕夜全家都要团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照老习俗，除夕那天要团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除夕团年时，要先给祖先敬酒。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷小时候，除夕团年要放鞭炮。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除夕团年的规矩，我们家一直保留着。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前除夕，不管多远的人，都要回家团年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，除夕不团年，就不算过年。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，除夕团年时我最爱吃鱼。", "target_word": "团年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "团年了", "label": "体标"}, {"form": "团年饭", "label": "复合"}], "register": "通用", "sense_fingerprint": "旧俗，除夕夜全家团聚吃年夜饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "团年", "is_correct": true, "explanation": "正确。“团年”是旧时除夕全家聚餐的习俗，符合“旧时除夕”的语境。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班不是旧时除夕的习俗，与“旧时除夕，一家人要……”的意思不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不是除夕的习俗，句子说不通。"}, {"text": "施工", "is_correct": false, "explanation": "语义：施工是建造工程，不是除夕一家人的习俗，句子说不通。"}], "explanations": {"团年": "正确。“团年”是旧时除夕全家聚餐的习俗，符合“旧时除夕”的语境。", "上班": "语义：上班不是旧时除夕的习俗，与“旧时除夕，一家人要……”的意思不符。", "考试": "语义：考试不是除夕的习俗，句子说不通。", "施工": "语义：施工是建造工程，不是除夕一家人的习俗，句子说不通。"}, "sentence_index": 0, "correct_answer": "团年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "按照老习俗，正月十五晚上要团年，吃元宵。", "explanation": "这里应该用〈过元宵节〉。团年是除夕全家吃年夜饭，正月十五吃元宵是过元宵节，不叫团年。"}, {"text": "公司年底请全体员工去饭店团年。", "explanation": "这里应该用〈聚餐〉。团年指除夕一家人团聚吃年夜饭，同事一起吃饭叫聚餐。"}, {"text": "除夕，我们去坟前团年。", "explanation": "这里应该用〈祭祖〉。去坟前是祭祖，团年是家人在饭桌上吃团圆饭，不用于坟前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "团年", "is_correct": true, "explanation": "正确。“除夕团年的规矩”指除夕全家聚餐的旧俗，符合语境。"}, {"text": "上课", "is_correct": false, "explanation": "语义：上课是学校的活动，不是除夕的规矩。"}, {"text": "出差", "is_correct": false, "explanation": "语义：出差是公务外出办事，与家中传承的除夕习俗不相干，句子说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与除夕的习俗无关，句子说不通。"}], "explanations": {"团年": "正确。“除夕团年的规矩”指除夕全家聚餐的旧俗，符合语境。", "上课": "语义：上课是学校的活动，不是除夕的规矩。", "出差": "语义：出差是公务外出办事，与家中传承的除夕习俗不相干，句子说不通。", "游泳": "语义：游泳与除夕的习俗无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "团年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上在床上团年。", "explanation": "这里应该用〈睡觉〉。团年是除夕全家吃年夜饭，早上在床上是睡觉，不能说团年。"}, {"text": "我每天中午在学校食堂团年。", "explanation": "这里应该用〈吃饭〉。团年只指除夕全家吃年夜饭，平时在食堂只是吃饭。"}, {"text": "同学们在教室团年。", "explanation": "这里应该用〈上课〉。团年是家庭习俗，同学在教室里不是团年，而是上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旧时除夕，一家人家里团年。", "corrected_sentence": "旧时除夕，一家人在家里团年。", "error_description": "漏掉介词“在”：“家里”是团年的地点，应说“在家里团年”，不能直接说“家里团年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "除夕那天，我们一家人把饭店团年。", "corrected_sentence": "除夕那天，我们一家人在饭店团年。", "error_description": "把字句错误：“团年”是不及物动词，不能用“把”引出处所，应说“在饭店团年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
