INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91958, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一端或一侧经过到另一端或另一侧。", "primary_collocate": null, "pronunciation": "chuān guò", "ipa": "ʈʂʰwan˥ kwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "火车穿过长长的山洞。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光穿过窗户照在桌上。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河穿过整个城市。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风穿过树叶，发出沙沙的声音。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条铁路穿过大山。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "针穿过布，线也跟着过去了。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子弹穿过墙，留下一个洞。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光穿过玻璃，进了房间。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机穿过云层，飞向北京。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条地铁线穿过城市中心。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体、光线、道路等从一端经过到另一端", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa83287-1e2b-4500-b69a-3fd58334cdca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿过", "is_correct": true, "explanation": "“穿过”表示从一端经过到另一端，这里说火车从山洞的一头经过到另一头。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能说“驾驶山洞”。"}, {"text": "报告", "is_correct": false, "explanation": "语义：“报告”指把情况告诉别人，与火车和山洞无关。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”指占有某物，火车不能占有山洞。"}], "explanations": {"穿过": "“穿过”表示从一端经过到另一端，这里说火车从山洞的一头经过到另一头。", "驾驶": "搭配：“驾驶”的对象是车辆，不能说“驾驶山洞”。", "报告": "语义：“报告”指把情况告诉别人，与火车和山洞无关。", "拥有": "语义：“拥有”指占有某物，火车不能占有山洞。"}, "sentence_index": 0, "correct_answer": "穿过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次竞赛他穿过了初赛。", "explanation": "这里应该用〈通过〉。“穿过”指从一端到另一端的移动，不能用于比赛的阶段，“通过初赛”表示晋级。"}, {"text": "我们在海边穿过了假期。", "explanation": "这里应该用〈度过〉。“穿过”表示从一端到另一端，不能用于时间，度过假期要说“度过”。"}, {"text": "这台机器已经穿过十年了。", "explanation": "这里应该用〈用了〉。“用了十年”表示使用的时间，“穿过”表示从一端到另一端，不能用于机器的使用时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿过", "is_correct": true, "explanation": "“穿过”表示从一边经过到另一边，这里说子弹穿过墙，留下一个洞。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”要有送出的物品和接收的人，“子弹送墙”结构不完整，语义也不通。"}, {"text": "赐予", "is_correct": false, "explanation": "语域：“赐予”是书面用语，多用于给予恩惠，与子弹穿墙的描述不协调。"}, {"text": "粉刷", "is_correct": false, "explanation": "体貌：“粉刷”指给墙面涂颜色、改变外观，子弹不能粉刷墙。"}], "explanations": {"穿过": "“穿过”表示从一边经过到另一边，这里说子弹穿过墙，留下一个洞。", "送": "配价：“送”要有送出的物品和接收的人，“子弹送墙”结构不完整，语义也不通。", "赐予": "语域：“赐予”是书面用语，多用于给予恩惠，与子弹穿墙的描述不协调。", "粉刷": "体貌：“粉刷”指给墙面涂颜色、改变外观，子弹不能粉刷墙。"}, "sentence_index": 6, "correct_answer": "穿过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩穿过了我。", "explanation": "这里应该用〈超过〉。“穿过”指从一端到另一端，不能表示在成绩上胜过别人。"}, {"text": "这回就穿过他吧。", "explanation": "这里应该用〈放过〉。“穿过”指从一端到另一端，不能表示饶过某人。"}, {"text": "她终于穿过了任务。", "explanation": "这里应该用〈完成〉。“穿过”表示从一端到另一端，不能用来表示做完任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条小路穿过过村子。", "corrected_sentence": "这条小路穿过村子。", "error_description": "“过”只能用一次。错误形式是“穿过过村子”，正确形式是“穿过村子”，多出的“过”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这趟列车很穿过山谷。", "corrected_sentence": "这趟列车穿过山谷。", "error_description": "“很”不能修饰动作动词“穿过”。错误形式是“很穿过”，正确形式是“穿过”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91959, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无权", "is_correct": true, "explanation": "正确答案。“无权”指没有做某事的权利，与“有权”相反。"}, {"text": "批准", "is_correct": false, "explanation": "批准表示上级同意某事，与“有权”没有反义关系。"}, {"text": "答应", "is_correct": false, "explanation": "答应表示应允，不是“有权”的反义词。"}, {"text": "完成", "is_correct": false, "explanation": "完成表示做完某事，与“有权”没有反义关系。"}], "correct_answer": "无权", "explanations": {"无权": "正确答案。“无权”指没有做某事的权利，与“有权”相反。", "批准": "批准表示上级同意某事，与“有权”没有反义关系。", "答应": "答应表示应允，不是“有权”的反义词。", "完成": "完成表示做完某事，与“有权”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91959, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无权", "is_correct": true, "explanation": "正确答案。“无权”指没有做某事的权利，与“有权”相反。"}, {"text": "授予", "is_correct": false, "explanation": "授予表示给予权利，与“有权”相关但不是反义词。"}, {"text": "考虑", "is_correct": false, "explanation": "考虑表示思量，与“有权”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察表示仔细看，与“有权”没有反义关系。"}], "correct_answer": "无权", "explanations": {"无权": "正确答案。“无权”指没有做某事的权利，与“有权”相反。", "授予": "授予表示给予权利，与“有权”相关但不是反义词。", "考虑": "考虑表示思量，与“有权”没有反义关系。", "观察": "观察表示仔细看，与“有权”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91959, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "有权是你可以做这件事，别人不能不让你做。", "primary_collocate": null, "pronunciation": "yǒu quán", "ipa": "jou˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "每个人都有权说出自己的想法。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是这间房子的主人，有权决定谁进来。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子有权去学校学习。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我花钱买了票，我有权坐这个位子。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有权不回答这个问题。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人有权要求换一个房间。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买了东西的人有权问价格。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有权选择自己喜欢的工作。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都有权过自己想过的生活。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不喜欢，也有权说不。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "有可以做某事、别人不能阻止的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2bbdfe-45ed-43d8-ab7a-6e76fe728753') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有权", "is_correct": true, "explanation": "正确答案。yǒu quán，意思是拥有做某事的权利。"}, {"text": "有钱", "is_correct": false, "explanation": "qián 与 quán 的元音不同（i 与 u），意思是拥有钱财。"}, {"text": "有缘", "is_correct": false, "explanation": "yuán 与 quán 的声母不同（y 与 q），意思是有缘分。"}, {"text": "有券", "is_correct": false, "explanation": "quàn（第四声）与 quán（第二声）声调不同，意思是拥有优惠券。"}], "explanations": {"有权": "正确答案。yǒu quán，意思是拥有做某事的权利。", "有钱": "qián 与 quán 的元音不同（i 与 u），意思是拥有钱财。", "有缘": "yuán 与 quán 的声母不同（y 与 q），意思是有缘分。", "有券": "quàn（第四声）与 quán（第二声）声调不同，意思是拥有优惠券。"}, "sentence_index": null, "correct_answer": "有权"}, "level_3": {"options": [{"text": "有权", "is_correct": true, "explanation": "正确答案。“有权”表示有权利说出自己的想法，符合句意。"}, {"text": "权利", "is_correct": false, "explanation": "语法：「权利」是名词，不能直接带动词短语“说出自己的想法”。"}, {"text": "权力", "is_correct": false, "explanation": "语法：「权力」是名词，指控制力量，不能直接带动词短语。"}, {"text": "有力", "is_correct": false, "explanation": "语义：「有力」形容有力量，不能表示有做某事的权利。"}], "explanations": {"有权": "正确答案。“有权”表示有权利说出自己的想法，符合句意。", "权利": "语法：「权利」是名词，不能直接带动词短语“说出自己的想法”。", "权力": "语法：「权力」是名词，指控制力量，不能直接带动词短语。", "有力": "语义：「有力」形容有力量，不能表示有做某事的权利。"}, "sentence_index": 0, "correct_answer": "有权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有权跑得很快。", "explanation": "这里应该用〈有能力〉。「有权」指有做某事的权利，身体或能力方面要用「有能力」。"}, {"text": "我今天有权陪你。", "explanation": "这里应该用〈有空〉。「有权」表示有权利做某事，时间是否方便要用「有空」。"}, {"text": "这个老人有权走很远的路。", "explanation": "这里应该用〈有力气〉。「有权」指依法或依规定具有做某事的权利，体力方面要用「有力气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有权", "is_correct": true, "explanation": "正确答案。“有权”表示买了东西的人有权利问价格，符合句意。"}, {"text": "权利", "is_correct": false, "explanation": "语法：「权利」是名词，不能直接带动词短语“问价格”。"}, {"text": "阻止", "is_correct": false, "explanation": "搭配：「阻止」多用于阻拦他人的行为，句中主语是买东西的人，不能自己阻止自己问价格。"}, {"text": "限制", "is_correct": false, "explanation": "语义：「限制」表示加以约束，与句中“有权问价格”的意思相反。"}], "explanations": {"有权": "正确答案。“有权”表示买了东西的人有权利问价格，符合句意。", "权利": "语法：「权利」是名词，不能直接带动词短语“问价格”。", "阻止": "搭配：「阻止」多用于阻拦他人的行为，句中主语是买东西的人，不能自己阻止自己问价格。", "限制": "语义：「限制」表示加以约束，与句中“有权问价格”的意思相反。"}, "sentence_index": 6, "correct_answer": "有权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我有权赢这场比赛。", "explanation": "这里应该用〈有把握〉。「有权」指权利，对结果有信心要用「有把握」。"}, {"text": "这次比赛他有权进步很大。", "explanation": "这里应该用〈进步〉。「有权」指权利，表示能力或成绩的提高要用「进步」。"}, {"text": "这个办法有权很有效。", "explanation": "这里应该用〈有效〉。「有权」指权利，办法的效果要用「有效」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生不有权向老师提问。", "corrected_sentence": "学生有权向老师提问。", "error_description": "“有权”的否定错误。在“有权”前加“不”，构成“不有权”，不成立；表示没有权利应说“无权”或“没有权利”。正确形式是“有权”，不加否定词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "租客不有权提前退租。", "corrected_sentence": "租客有权提前退租。", "error_description": "“有权”的否定错误。在“有权”前加“不”，构成“不有权”，不成立；表示没有权利应说“无权”或“没有权利”。正确形式是“有权”，不加否定词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
