INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91962, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "成批、大规模地制造产品。", "primary_collocate": null, "pronunciation": "dà liàng shēng chǎn", "ipa": "ta˥˩ ljɑŋ˥˩ ʂɤŋ˥ ʈʂʰan˨˩˦", "syllable_count": 4, "sentences": [{"text": "这个牌子的自行车是大量生产的。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车公司用机器大量生产零件。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布料太便宜了，因为是大量生产的。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家工厂每天大量生产塑料瓶。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工做的东西贵，大量生产的东西便宜。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的工厂开始大量生产电动车了。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只想着大量生产，还要注意质量。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们大量生产运动鞋，卖给世界各地。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说下个月要大量生产这种蛋糕。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她家的小工厂大量生产过口罩。", "target_word": "大量生产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大量生产了", "label": "完成体"}, {"form": "大量生产过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "成批、大规模地制造产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5a5e0a7-1931-406f-8fa8-4b6b6a09a7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大量生产", "is_correct": true, "explanation": "“是……的”结构中，“大量生产”说明自行车是成批制造出来的，句意通顺。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：自行车不会唱歌，这样说句子不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：自行车不会生病，用在“是……的”结构中没有意义。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能表示制造方式，不能用在“是……的”结构中。"}], "explanations": {"大量生产": "“是……的”结构中，“大量生产”说明自行车是成批制造出来的，句意通顺。", "唱歌": "语义：自行车不会唱歌，这样说句子不通。", "生病": "语义：自行车不会生病，用在“是……的”结构中没有意义。", "散步": "配价：“散步”是不及物动词，不能表示制造方式，不能用在“是……的”结构中。"}, "sentence_index": 0, "correct_answer": "大量生产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位画家大量生产了一幅油画。", "explanation": "这里应该用〈创作〉。油画是画家亲手画成的独一无二的作品，一幅画不能说大量生产，应说创作。"}, {"text": "仓库大量生产了很多货物。", "explanation": "这里应该用〈储存〉。仓库存放货物，不是制造产品的地方，应说储存货物。"}, {"text": "这位诗人大量生产了一首诗。", "explanation": "这里应该用〈写作〉。诗是作者逐字写成的单件作品，一首诗不能说大量生产，应说写作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大量生产", "is_correct": true, "explanation": "“只想着大量生产”指只追求成批制造，与后面的“还要注意质量”形成对比，句意通顺。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽不是人可以“只想着”去追求的目标，句子没有意义。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“只想着……，还要注意质量”要求前面是可以追求的目标，“哭”不能这样搭配。"}, {"text": "打喷嚏", "is_correct": false, "explanation": "语义：打喷嚏是身体的反应，不能作为“只想着”的对象。"}], "explanations": {"大量生产": "“只想着大量生产”指只追求成批制造，与后面的“还要注意质量”形成对比，句意通顺。", "咳嗽": "语义：咳嗽不是人可以“只想着”去追求的目标，句子没有意义。", "哭": "搭配：“只想着……，还要注意质量”要求前面是可以追求的目标，“哭”不能这样搭配。", "打喷嚏": "语义：打喷嚏是身体的反应，不能作为“只想着”的对象。"}, "sentence_index": 6, "correct_answer": "大量生产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大量生产了很多快乐。", "explanation": "这里应该用〈享受〉。大量生产指制造产品，快乐是感受到的，不能说大量生产。"}, {"text": "这场比赛大量生产了很多冠军。", "explanation": "这里应该用〈产生〉。大量生产是制造产品，比赛产生的是结果，不能说大量生产冠军。"}, {"text": "他大量生产了很多时间。", "explanation": "这里应该用〈浪费〉。大量生产的对象是产品，时间不能大量生产，应说浪费时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂正在大量生产了玩具。", "corrected_sentence": "这家工厂正在大量生产玩具。", "error_description": "体标错误：“正在”表示动作在进行，不能和表示完成的“了”同用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年我们工厂要大量生产过手机。", "corrected_sentence": "明年我们工厂要大量生产手机。", "error_description": "体标错误：“过”表示已经有过的经历，不能用于“明年……要”这种将来的事，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91963, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "富", "is_correct": true, "explanation": "正确：“富”与“穷”是反义词，指钱财多。"}, {"text": "饱", "is_correct": false, "explanation": "“饱”指吃够了，与“穷”没有反义关系。"}, {"text": "忙", "is_correct": false, "explanation": "“忙”指事情多，与“穷”没有反义关系。"}, {"text": "热", "is_correct": false, "explanation": "“热”指温度高，与“穷”没有反义关系。"}], "correct_answer": "富", "explanations": {"富": "正确：“富”与“穷”是反义词，指钱财多。", "饱": "“饱”指吃够了，与“穷”没有反义关系。", "忙": "“忙”指事情多，与“穷”没有反义关系。", "热": "“热”指温度高，与“穷”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91963, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "富", "is_correct": true, "explanation": "正确：“富”与“穷”是反义词，指钱财多。"}, {"text": "冷", "is_correct": false, "explanation": "“冷”指温度低，与“穷”没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”指位置或数量大，与“穷”没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”指光线强，与“穷”没有反义关系。"}], "correct_answer": "富", "explanations": {"富": "正确：“富”与“穷”是反义词，指钱财多。", "冷": "“冷”指温度低，与“穷”没有反义关系。", "高": "“高”指位置或数量大，与“穷”没有反义关系。", "亮": "“亮”指光线强，与“穷”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91963, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有钱。", "primary_collocate": null, "pronunciation": "qióng", "ipa": "tɕʰjʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他家很穷，没有钱买新衣服。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在很穷，只有十块钱了。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前我们家穷，常常吃不饱。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月底了，我穷得连饭都吃不起。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是穷，只是不想花钱。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很穷，买不起新手机。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候穷过，所以很会省钱。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友穷了，我们应该帮他。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱都花完了，我又变穷了。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然穷，他还是每天笑着生活。", "target_word": "穷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "窮", "label": "繁体"}], "register": "口语", "sense_fingerprint": "没有钱，手头缺钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '501e030f-9419-4045-ab4d-0d12862286c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91963, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "穷", "is_correct": true, "explanation": "正确：穷（qióng）指没有钱。"}, {"text": "熊", "is_correct": false, "explanation": "熊（xióng）与穷（qióng）声母不同，意思是熊。"}, {"text": "炯", "is_correct": false, "explanation": "炯（jiǒng）与穷（qióng）声母不同、声调也不同，意思是明亮。"}, {"text": "强", "is_correct": false, "explanation": "强（qiáng）与穷（qióng）韵母不同，意思是强大。"}, {"text": "雄", "is_correct": false, "explanation": "雄（xióng）与穷（qióng）声母不同，意思是雄性的。"}], "explanations": {"穷": "正确：穷（qióng）指没有钱。", "熊": "熊（xióng）与穷（qióng）声母不同，意思是熊。", "炯": "炯（jiǒng）与穷（qióng）声母不同、声调也不同，意思是明亮。", "强": "强（qiáng）与穷（qióng）韵母不同，意思是强大。", "雄": "雄（xióng）与穷（qióng）声母不同，意思是雄性的。"}, "sentence_index": null, "correct_answer": "穷"}, "level_3": {"options": [{"text": "穷", "is_correct": true, "explanation": "正确：“穷”指没有钱，与“没有钱买新衣服”相符。"}, {"text": "富", "is_correct": false, "explanation": "语义：“富”指有钱，与后句“没有钱买新衣服”矛盾。"}, {"text": "忙", "is_correct": false, "explanation": "语义：“忙”指事务多，与后句“没有钱买新衣服”无关，句意不通。"}, {"text": "绿", "is_correct": false, "explanation": "语义：颜色不能用来说明家境。"}], "explanations": {"穷": "正确：“穷”指没有钱，与“没有钱买新衣服”相符。", "富": "语义：“富”指有钱，与后句“没有钱买新衣服”矛盾。", "忙": "语义：“忙”指事务多，与后句“没有钱买新衣服”无关，句意不通。", "绿": "语义：颜色不能用来说明家境。"}, "sentence_index": 0, "correct_answer": "穷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的水资源很穷，每年都缺水。", "explanation": "这里“穷”用于资源不对。资源少应说〈贫乏〉，“穷”只用于人或家庭缺钱。"}, {"text": "这条河里的鱼很穷，钓了一天也没钓到。", "explanation": "这里应该用〈少〉。数量不多要说〈少〉，“穷”只指人或家庭缺钱。"}, {"text": "他的知识很穷，很少读书。", "explanation": "这里应该用〈匮乏〉。知识不足要说〈匮乏〉，“穷”只指缺钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91963, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "穷", "is_correct": true, "explanation": "正确：穷（qióng）指没有钱。"}, {"text": "倾", "is_correct": false, "explanation": "近似混淆：qīng 与 qióng 声调不同、韵腹不同，意思是倾斜。"}, {"text": "请", "is_correct": false, "explanation": "近似混淆：qǐng 与 qióng 声调不同、韵腹不同，意思是请求。"}, {"text": "呛", "is_correct": false, "explanation": "近似混淆：qiàng 与 qióng 声调不同、韵母不同，意思是呛到、刺激。"}], "explanations": {"穷": "正确：穷（qióng）指没有钱。", "倾": "近似混淆：qīng 与 qióng 声调不同、韵腹不同，意思是倾斜。", "请": "近似混淆：qǐng 与 qióng 声调不同、韵腹不同，意思是请求。", "呛": "近似混淆：qiàng 与 qióng 声调不同、韵母不同，意思是呛到、刺激。"}, "sentence_index": null, "correct_answer": "穷"}, "level_3": {"options": [{"text": "穷", "is_correct": true, "explanation": "正确：“穷过”表示过去缺钱的经历，与“很会省钱”有因果联系。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”指身高，与省钱没有关系。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”指身材，不能说明会省钱。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”与省钱没有因果联系，句子不通。"}], "explanations": {"穷": "正确：“穷过”表示过去缺钱的经历，与“很会省钱”有因果联系。", "高": "语义：“高”指身高，与省钱没有关系。", "胖": "语义：“胖”指身材，不能说明会省钱。", "亮": "语义：“亮”与省钱没有因果联系，句子不通。"}, "sentence_index": 6, "correct_answer": "穷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的电力很穷，经常停电。", "explanation": "这里“穷”用于电力不对。供应不足应说〈紧缺〉，“穷”只指缺钱。"}, {"text": "他的衣服很穷，但洗得很干净。", "explanation": "这里应该用〈寒酸〉。衣着简陋、看起来穷要说〈寒酸〉，“穷”指缺钱本身。"}, {"text": "他的数学基础很穷，需要从头学起。", "explanation": "这里应该用〈薄弱〉。基础不牢要说〈薄弱〉，“穷”只指缺钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家最近穷很，只能吃素菜。", "corrected_sentence": "我们家最近很穷，只能吃素菜。", "error_description": "程度副词位置错误：“很”应放在形容词“穷”之前，说“很穷”，不能说“穷很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爸爸年轻时穷了过，后来做生意才有钱。", "corrected_sentence": "我爸爸年轻时穷过，后来做生意才有钱。", "error_description": "动态助词错误：“穷”后已用“过”表示经历，不能再加“了”，应说“穷过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
