INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表演；在舞台或镜头前扮演角色或展示技艺。", "primary_collocate": null, "pronunciation": "yǎn", "ipa": "jɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "她在电影里演一位老师。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小学戏，现在在舞台上演大戏。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人在台上演了一段京剧。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她演过三部电视剧。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在镜头前演得很自然。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个剧团明晚在大剧院演新戏。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他演的医生让大家都很喜欢。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里谁演女主角？", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马戏团的人在台上演着有趣的节目。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在镜头前演哭的样子，真的很像。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演了", "label": "完成体"}, {"form": "演过", "label": "经历体"}, {"form": "演着", "label": "持续体"}, {"form": "演出", "label": "复合"}, {"form": "演员", "label": "复合"}], "register": "中性", "sense_fingerprint": "在舞台或镜头前表演，扮演角色或展示技艺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2bbdfe-45ed-43d8-ab7a-6e76fe728753') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91966, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演", "is_correct": true, "explanation": "演（yǎn，第三声）：在舞台或镜头前表演角色、展示技艺，正确答案。"}, {"text": "盐", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，意思是盐。"}, {"text": "烟", "is_correct": false, "explanation": "yān（第一声）与 yǎn（第三声）声调不同，意思是烟。"}, {"text": "养", "is_correct": false, "explanation": "yǎng 与 yǎn 声调相同，但韵母不同（ang 与 an），意思是饲养。"}, {"text": "验", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是检验。"}], "explanations": {"演": "演（yǎn，第三声）：在舞台或镜头前表演角色、展示技艺，正确答案。", "盐": "yán（第二声）与 yǎn（第三声）声调不同，意思是盐。", "烟": "yān（第一声）与 yǎn（第三声）声调不同，意思是烟。", "养": "yǎng 与 yǎn 声调相同，但韵母不同（ang 与 an），意思是饲养。", "验": "yàn（第四声）与 yǎn（第三声）声调不同，意思是检验。"}, "sentence_index": null, "correct_answer": "演"}, "level_3": {"options": [{"text": "演", "is_correct": true, "explanation": "演：在电影里扮演老师这一角色，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吃东西，“吃一位老师”与电影场景不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“老师”这种角色作宾语，“唱一位老师”不成立。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”不能带“一位老师”作宾语，句子不成立。"}], "explanations": {"演": "演：在电影里扮演老师这一角色，符合句意。", "吃": "语义：“吃”指吃东西，“吃一位老师”与电影场景不符。", "唱": "搭配：“唱”不能带“老师”这种角色作宾语，“唱一位老师”不成立。", "跑": "配价：“跑”不能带“一位老师”作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他演过三杯咖啡。", "explanation": "这里应该用〈喝〉。演指在舞台或镜头前扮演角色或展示技艺，喝咖啡要用喝。"}, {"text": "她演过三个学生写字。", "explanation": "这里应该用〈教〉。演指表演角色或技艺，教人写字要用教。"}, {"text": "他演过三幅画。", "explanation": "这里应该用〈画〉。演指在舞台或镜头前扮演角色或展示技艺，画画要用画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91966, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "演", "is_correct": true, "explanation": "演（yǎn，第三声）：在舞台或镜头前表演角色、展示技艺，正确答案。"}, {"text": "严", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，意思是严格。"}, {"text": "宴", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是宴席。"}, {"text": "厌", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是讨厌。"}, {"text": "艳", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是鲜艳。"}], "explanations": {"演": "演（yǎn，第三声）：在舞台或镜头前表演角色、展示技艺，正确答案。", "严": "yán（第二声）与 yǎn（第三声）声调不同，意思是严格。", "宴": "yàn（第四声）与 yǎn（第三声）声调不同，意思是宴席。", "厌": "yàn（第四声）与 yǎn（第三声）声调不同，意思是讨厌。", "艳": "yàn（第四声）与 yǎn（第三声）声调不同，意思是鲜艳。"}, "sentence_index": null, "correct_answer": "演"}, "level_3": {"options": [{"text": "演", "is_correct": true, "explanation": "演：在镜头前扮演医生，“演的医生”指所扮演的角色，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹调，“煮的医生”与“大家都很喜欢”的语境不符。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”不能修饰“医生”，“摘的医生”不成立。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是器物，不能修饰“医生”，“修的医生”不成立。"}], "explanations": {"演": "演：在镜头前扮演医生，“演的医生”指所扮演的角色，符合句意。", "煮": "语义：“煮”指烹调，“煮的医生”与“大家都很喜欢”的语境不符。", "摘": "搭配：“摘”不能修饰“医生”，“摘的医生”不成立。", "修": "搭配：“修”的对象是器物，不能修饰“医生”，“修的医生”不成立。"}, "sentence_index": 6, "correct_answer": "演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她晚上在灯下演一朵花。", "explanation": "这里应该用〈绣〉。演指在舞台或镜头前扮演角色或展示技艺，绣花要用绣。"}, {"text": "她每天演车去上班。", "explanation": "这里应该用〈开〉。演指表演角色或技艺，驾驶车辆要用开。"}, {"text": "农民在田里演菜。", "explanation": "这里应该用〈种〉。演指表演角色或技艺，种植蔬菜要用种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在电影里过演一个小偷。", "corrected_sentence": "他在电影里演过一个小偷。", "error_description": "经历体“过”位置错误。“过”应紧跟在动词“演”后，写作“演过”，“过演”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他演地很自然。", "corrected_sentence": "他演得很自然。", "error_description": "补语标记用错。“演得很自然”中连接动词与补语的应为“得”，写作“地”是误用了状语标记“地”，应改为“演得很自然”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
