INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91967, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "奔是很快地跑向一个地方。", "primary_collocate": null, "pronunciation": "bēn", "ipa": "pən˥", "syllable_count": 1, "sentences": [{"text": "听到铃声，孩子们奔出了教室。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放下书包就奔进厨房。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看见主人，立刻奔了过来。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家都奔回家去。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一口气奔上了五楼。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到火车要开了，他赶紧奔到站台。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们奔到门口迎接爸爸。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说有好消息，她奔进屋里告诉妈妈。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一结束，球迷们奔下看台。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他接过电话，转身奔出办公室。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奔了", "label": "体标"}, {"form": "奔过", "label": "体标"}], "register": "中性", "sense_fingerprint": "很快地跑向某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf3d60e-a1e3-44ad-8ec7-68f909d098f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91967, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奔", "is_correct": true, "explanation": "奔 bēn（第一声）：很快地跑向某个地方。"}, {"text": "本", "is_correct": false, "explanation": "本 běn（第三声）与 bēn（第一声）声调不同，意思是书本。"}, {"text": "笨", "is_correct": false, "explanation": "笨 bèn（第四声）与 bēn（第一声）声调不同，意思是笨拙。"}, {"text": "崩", "is_correct": false, "explanation": "崩 bēng 与 bēn 的韵尾不同（ng 与 n），声调相同，意思是崩塌。"}, {"text": "喷", "is_correct": false, "explanation": "喷 pēn 与 bēn 的声母不同（p 与 b），声调相同，意思是喷出。"}], "explanations": {"奔": "奔 bēn（第一声）：很快地跑向某个地方。", "本": "本 běn（第三声）与 bēn（第一声）声调不同，意思是书本。", "笨": "笨 bèn（第四声）与 bēn（第一声）声调不同，意思是笨拙。", "崩": "崩 bēng 与 bēn 的韵尾不同（ng 与 n），声调相同，意思是崩塌。", "喷": "喷 pēn 与 bēn 的声母不同（p 与 b），声调相同，意思是喷出。"}, "sentence_index": null, "correct_answer": "奔"}, "level_3": {"options": [{"text": "奔", "is_correct": true, "explanation": "奔：很快地跑出去，与“听到铃声”后急忙离开的情景相合。"}, {"text": "挪", "is_correct": false, "explanation": "语义：“挪”指慢慢移动，与听到铃声后急忙离开的情景相反。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中行进，教室里没有水，与句子情景不合。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”是及物动词，需要带被扔之物作宾语，这里没有宾语。"}], "explanations": {"奔": "奔：很快地跑出去，与“听到铃声”后急忙离开的情景相合。", "挪": "语义：“挪”指慢慢移动，与听到铃声后急忙离开的情景相反。", "游": "语义：“游”指在水中行进，教室里没有水，与句子情景不合。", "扔": "配价：“扔”是及物动词，需要带被扔之物作宾语，这里没有宾语。"}, "sentence_index": 0, "correct_answer": "奔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶汽水放了一夜，已经奔了气。", "explanation": "这里应该用〈跑〉。“跑气”指饮料中的气体散失，“奔”只用于人或兽快速移动，不能用于汽水漏气。"}, {"text": "这篇文章奔了三页。", "explanation": "这里应该用〈写〉。“奔”表示快速跑动，不能用来描述文章的篇幅。"}, {"text": "这首歌奔了三分钟。", "explanation": "这里应该用〈唱〉。“奔”表示快速跑动，不能用来描述歌曲的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91967, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奔", "is_correct": true, "explanation": "奔 bēn（第一声）：很快地跑向某个地方。"}, {"text": "喷", "is_correct": false, "explanation": "喷 pēn 与 bēn 的声母不同（p 与 b），声调相同，意思是喷出。"}, {"text": "分", "is_correct": false, "explanation": "分 fēn 与 bēn 的声母不同（f 与 b），声调相同，意思是分开。"}, {"text": "绷", "is_correct": false, "explanation": "绷 bēng 与 bēn 的韵尾不同（ng 与 n），声调相同，意思是绷紧。"}], "explanations": {"奔": "奔 bēn（第一声）：很快地跑向某个地方。", "喷": "喷 pēn 与 bēn 的声母不同（p 与 b），声调相同，意思是喷出。", "分": "分 fēn 与 bēn 的声母不同（f 与 b），声调相同，意思是分开。", "绷": "绷 bēng 与 bēn 的韵尾不同（ng 与 n），声调相同，意思是绷紧。"}, "sentence_index": null, "correct_answer": "奔"}, "level_3": {"options": [{"text": "奔", "is_correct": true, "explanation": "奔：快速跑动，与“迎接爸爸”时急着到门口的情景相合。"}, {"text": "躺", "is_correct": false, "explanation": "语义：“躺”是横卧不动，与“迎接爸爸”时快速移动的动作不合。"}, {"text": "漂", "is_correct": false, "explanation": "语义：“漂”指随水或风飘动，孩子不会这样移动到门口。"}, {"text": "抬", "is_correct": false, "explanation": "配价：“抬”需要带宾语（抬东西），“孩子们抬到门口”缺宾语，不成立。"}], "explanations": {"奔": "奔：快速跑动，与“迎接爸爸”时急着到门口的情景相合。", "躺": "语义：“躺”是横卧不动，与“迎接爸爸”时快速移动的动作不合。", "漂": "语义：“漂”指随水或风飘动，孩子不会这样移动到门口。", "抬": "配价：“抬”需要带宾语（抬东西），“孩子们抬到门口”缺宾语，不成立。"}, "sentence_index": 6, "correct_answer": "奔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他慢慢奔回家，没有着急。", "explanation": "这里应该用〈走〉。“奔”表示很快地跑，与“慢慢”的意思矛盾。"}, {"text": "蝴蝶在花丛中奔来奔去。", "explanation": "这里应该用〈飞〉。“奔”只用于人或兽快速跑动，不能描述蝴蝶在空中的飞行。"}, {"text": "他吃饭奔得很快。", "explanation": "这里应该用〈吃〉，说成“他吃饭吃得很快”。“奔”表示快速跑动，不能用来描述吃饭的速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他奔很快，一下子就到了学校。", "corrected_sentence": "他奔得很快，一下子就到了学校。", "error_description": "错误：“奔很快”。正确：“奔得很快”。动词与表示程度的补语之间要用“得”连接，不能直接说“动词+很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忘了带钥匙，又回奔了家里。", "corrected_sentence": "他忘了带钥匙，又奔回了家里。", "error_description": "错误：“回奔”。正确：“奔回”。趋向补语“回”应紧跟在动词“奔”之后，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
