INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "急跑；朝着某个方向快速前进。", "primary_collocate": null, "pronunciation": "bēn", "ipa": "pən˥", "syllable_count": 1, "sentences": [{"text": "他骑上车，很快就奔到学校了。", "target_word": "奔", "complexity_tier": "T3", "furigana": "tā qí shàng chē, hěn kuài jiù bēn dào xué xiào le.", "sentence_source": "generated"}, {"text": "下课后，同学们奔到操场去踢球。", "target_word": "奔", "complexity_tier": "T3", "furigana": "xià kè hòu, tóng xué men bēn dào cāo chǎng qù tī qiú.", "sentence_source": "generated"}, {"text": "他拿着钥匙奔出门去。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到哭声，妈妈急忙奔到孩子身边。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马奔过草地，跑得很快。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员奔过终点线，大家都鼓掌。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见公共汽车来了，我奔上前去。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放下行李，奔进家人怀里。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩奔下山坡，笑着喊爸爸。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火警响了，消防员们奔出大门。", "target_word": "奔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奔了", "label": "体标"}, {"form": "奔过", "label": "体标"}], "register": "中性", "sense_fingerprint": "急跑，朝着某个方向快速前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf3d60e-a1e3-44ad-8ec7-68f909d098f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91968, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奔", "is_correct": true, "explanation": "奔 bēn（第一声）：急跑，朝某个方向快速前进。"}, {"text": "本", "is_correct": false, "explanation": "本 běn（第三声）与 bēn（第一声）声调不同，意思是书本。"}, {"text": "笨", "is_correct": false, "explanation": "笨 bèn（第四声）与 bēn（第一声）声调不同，意思是笨拙。"}, {"text": "崩", "is_correct": false, "explanation": "崩 bēng 与 bēn 的韵尾不同（ng 与 n），声调相同，意思是崩塌。"}, {"text": "喷", "is_correct": false, "explanation": "喷 pēn 与 bēn 的声母不同（p 与 b），声调相同，意思是喷出。"}], "explanations": {"奔": "奔 bēn（第一声）：急跑，朝某个方向快速前进。", "本": "本 běn（第三声）与 bēn（第一声）声调不同，意思是书本。", "笨": "笨 bèn（第四声）与 bēn（第一声）声调不同，意思是笨拙。", "崩": "崩 bēng 与 bēn 的韵尾不同（ng 与 n），声调相同，意思是崩塌。", "喷": "喷 pēn 与 bēn 的声母不同（p 与 b），声调相同，意思是喷出。"}, "sentence_index": null, "correct_answer": "奔"}, "level_3": {"options": [{"text": "奔", "is_correct": true, "explanation": "奔：快速前进，与“骑上车，很快就到学校”的意思相合。"}, {"text": "挪", "is_correct": false, "explanation": "语义：“挪”指慢慢移动，与“很快就”的语境相反。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中行进，骑车前往学校不涉及水。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”是及物动词，需要带被扔之物作宾语，这里没有宾语。"}], "explanations": {"奔": "奔：快速前进，与“骑上车，很快就到学校”的意思相合。", "挪": "语义：“挪”指慢慢移动，与“很快就”的语境相反。", "游": "语义：“游”指在水中行进，骑车前往学校不涉及水。", "扔": "配价：“扔”是及物动词，需要带被扔之物作宾语，这里没有宾语。"}, "sentence_index": 0, "correct_answer": "奔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到哭声，妈妈慢慢奔到孩子身边。", "explanation": "这里应该用〈走〉。“奔”表示很快地跑，与“慢慢”的意思矛盾。"}, {"text": "啤酒放久了，已经奔了气。", "explanation": "这里应该用〈跑〉。“跑气”指饮料中的气体散失，“奔”不能用于啤酒漏气。"}, {"text": "小鱼在水里奔来奔去。", "explanation": "这里应该用〈游〉。“奔”只用于人或兽快速跑动，不能描述鱼在水中的游动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91968, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奔", "is_correct": true, "explanation": "奔 bēn（第一声）：急跑，朝某个方向快速前进。"}, {"text": "喷", "is_correct": false, "explanation": "喷 pēn 与 bēn 的声母不同（p 与 b），声调相同，意思是喷出。"}, {"text": "分", "is_correct": false, "explanation": "分 fēn 与 bēn 的声母不同（f 与 b），声调相同，意思是分开。"}, {"text": "绷", "is_correct": false, "explanation": "绷 bēng 与 bēn 的韵尾不同（ng 与 n），声调相同，意思是绷紧。"}], "explanations": {"奔": "奔 bēn（第一声）：急跑，朝某个方向快速前进。", "喷": "喷 pēn 与 bēn 的声母不同（p 与 b），声调相同，意思是喷出。", "分": "分 fēn 与 bēn 的声母不同（f 与 b），声调相同，意思是分开。", "绷": "绷 bēng 与 bēn 的韵尾不同（ng 与 n），声调相同，意思是绷紧。"}, "sentence_index": null, "correct_answer": "奔"}, "level_3": {"options": [{"text": "奔", "is_correct": true, "explanation": "奔：快速跑动，与“看见公共汽车来了”后急忙上前的情景相合。"}, {"text": "躺", "is_correct": false, "explanation": "语义：“躺”是横卧休息，与看见车来后快速上前的动作不合。"}, {"text": "漂", "is_correct": false, "explanation": "语义：“漂”指随水或风飘动，人不会这样上前。"}, {"text": "抬", "is_correct": false, "explanation": "配价：“抬”需要带宾语（抬东西），“我抬上前去”缺宾语，不成立。"}], "explanations": {"奔": "奔：快速跑动，与“看见公共汽车来了”后急忙上前的情景相合。", "躺": "语义：“躺”是横卧休息，与看见车来后快速上前的动作不合。", "漂": "语义：“漂”指随水或风飘动，人不会这样上前。", "抬": "配价：“抬”需要带宾语（抬东西），“我抬上前去”缺宾语，不成立。"}, "sentence_index": 6, "correct_answer": "奔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小鸭子在湖里奔来奔去。", "explanation": "这里应该用〈游〉。“奔”只用于人或兽快速跑动，不能描述鸭子在水中的游动。"}, {"text": "小鸟在树枝上奔来奔去。", "explanation": "这里应该用〈跳〉。“奔”指人或兽快速跑动，不能描述鸟儿在树枝间跳跃。"}, {"text": "这份报告奔了三页。", "explanation": "这里应该用〈写〉。“奔”表示快速跑动，不能用来描述报告的篇幅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validat