INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "娱乐场是人们去玩、去放松的地方。", "primary_collocate": null, "pronunciation": "yú lè chǎng", "ipa": "y˧˥ lɤ˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "下班后，他想去娱乐场放松一下。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座娱乐场有电影院和游泳池。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇上只有一个娱乐场。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好在娱乐场门口见面。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娱乐场里有很多年轻人。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个娱乐场对小孩儿很安全。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假的时候，娱乐场总是很热闹。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娱乐场旁边有一家小餐馆。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在娱乐场玩了一下午。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的娱乐场越来越多了。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "娱乐场所", "label": "复合"}], "register": "中性", "sense_fingerprint": "娱乐场：人们去玩、去放松的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf3d60e-a1e3-44ad-8ec7-68f909d098f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "娱乐场", "is_correct": true, "explanation": "娱乐场：人们去玩、去放松的地方，与“放松一下”相合。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，不是用来放松的场所。"}, {"text": "公司", "is_correct": false, "explanation": "语义：下班后人已离开公司，不会再去公司放松。"}, {"text": "墓地", "is_correct": false, "explanation": "语域：墓地气氛肃穆，与“放松”的轻松语气不合。"}], "explanations": {"娱乐场": "娱乐场：人们去玩、去放松的地方，与“放松一下”相合。", "医院": "语义：医院是看病的地方，不是用来放松的场所。", "公司": "语义：下班后人已离开公司，不会再去公司放松。", "墓地": "语域：墓地气氛肃穆，与“放松”的轻松语气不合。"}, "sentence_index": 0, "correct_answer": "娱乐场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们约好在一只娱乐场门口见面。", "explanation": "这里应该用〈座〉。“只”用于动物，不能修饰场所。"}, {"text": "我们约好在那辆娱乐场门口见面。", "explanation": "这里应该用〈座〉或〈家〉。“辆”用于车辆，不能用来数场所。"}, {"text": "我们约好在那张娱乐场门口见面。", "explanation": "这里应该用〈座〉或〈家〉。“张”用于平面物件，不能用来数场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "娱乐场", "is_correct": true, "explanation": "娱乐场：人们聚集热闹的场所，与“总是很热闹”相合。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是场所，不能“热闹”，也无法聚集人群。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不会“热闹”。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，不是场所，不会“热闹”。"}], "explanations": {"娱乐场": "娱乐场：人们聚集热闹的场所，与“总是很热闹”相合。", "课本": "语义：课本不是场所，不能“热闹”，也无法聚集人群。", "冰箱": "语义：冰箱是家电，不会“热闹”。", "铅笔": "语义：铅笔是文具，不是场所，不会“热闹”。"}, "sentence_index": 6, "correct_answer": "娱乐场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们城市里又开了一本娱乐场。", "explanation": "这里应该用〈家〉。“本”用于书册，不能用来数场所。"}, {"text": "这个城市又新开了一把娱乐场。", "explanation": "这里应该用〈座〉或〈家〉。“把”用于有柄的器具，不能用来数场所。"}, {"text": "这个城市又新开了一条娱乐场。", "explanation": "这里应该用〈座〉或〈家〉。“条”用于河流、道路等细长的事物，不能用来数场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们一起去了那只娱乐场。", "corrected_sentence": "周末我们一起去了那座娱乐场。", "error_description": "错误：“那只娱乐场”。正确：“那座娱乐场”。“只”用于动物，大型场所应用量词“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这顶娱乐场新开了一年。", "corrected_sentence": "这座娱乐场新开了一年。", "error_description": "错误：“这顶娱乐场”。正确：“这座娱乐场”。“顶”用于帽子、帐篷等，大型场所应用量词“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
