INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人们游玩、消遣的场所。", "primary_collocate": null, "pronunciation": "yú lè chǎng", "ipa": "y˧˥ lɤ˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "周末我带孩子去娱乐场玩。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家娱乐场里有很多游戏机。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娱乐场的门口排着长队。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在娱乐场里玩得很开心。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城东新开了一家大娱乐场。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个娱乐场晚上十点才关门。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司附近没有娱乐场。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娱乐场里的音乐太吵了。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候常去那个娱乐场玩。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娱乐场的门票一人五十元。", "target_word": "娱乐场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}, {"form": "娱乐场所", "label": "复合"}], "register": "中性", "sense_fingerprint": "娱乐场：供人们游玩、消遣的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf3d60e-a1e3-44ad-8ec7-68f909d098f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "娱乐场", "is_correct": true, "explanation": "娱乐场：供人们游玩、消遣的场所，与“带孩子去玩”相合。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，不是供人游玩的场所。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库是存放货物的地方，不供人游玩，与“带孩子去玩”不合。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理业务的地方，不能用来带孩子去玩。"}], "explanations": {"娱乐场": "娱乐场：供人们游玩、消遣的场所，与“带孩子去玩”相合。", "医院": "语义：医院是看病的地方，不是供人游玩的场所。", "仓库": "语义：仓库是存放货物的地方，不供人游玩，与“带孩子去玩”不合。", "银行": "语义：银行是办理业务的地方，不能用来带孩子去玩。"}, "sentence_index": 0, "correct_answer": "娱乐场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "城东新开了一只娱乐场。", "explanation": "这里应该用〈座〉。“只”用于动物或成对的小物件，不能用来数场所。"}, {"text": "我们小区门口新开了一把娱乐场。", "explanation": "这里应该用〈座〉或〈家〉。“把”用于有柄的器具或椅子，不能用来数场所。"}, {"text": "周末我们一起去了那条娱乐场。", "explanation": "这里应该用〈座〉或〈家〉。“条”用于河流、道路等细长的事物，不能用来数场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "娱乐场", "is_correct": true, "explanation": "娱乐场：供人们游玩、消遣的场所，与“附近没有”的地点语境相合。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是场所，不能说“附近没有课本”指某个地点。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是场所，“附近没有空气”不成话。"}, {"text": "春天", "is_correct": false, "explanation": "搭配：“附近”指具体地点，“春天”是时间，两者不搭。"}], "explanations": {"娱乐场": "娱乐场：供人们游玩、消遣的场所，与“附近没有”的地点语境相合。", "课本": "语义：课本不是场所，不能说“附近没有课本”指某个地点。", "空气": "语义：“空气”不是场所，“附近没有空气”不成话。", "春天": "搭配：“附近”指具体地点，“春天”是时间，两者不搭。"}, "sentence_index": 6, "correct_answer": "娱乐场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在一本娱乐场里玩了一下午。", "explanation": "这里应该用〈个〉或〈座〉。“本”用于书册，不能用来数场所。"}, {"text": "我家门口新开了一顶娱乐场。", "explanation": "这里应该用〈座〉或〈家〉。“顶”用于帽子、帐篷等，不能用来数场所。"}, {"text": "他家附近新开了一辆娱乐场。", "explanation": "这里应该用〈座〉或〈家〉。“辆”用于车辆，不能用来数场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城东新建了一只娱乐场，很多人都去玩。", "corrected_sentence": "城东新建了一座娱乐场，很多人都去玩。", "error_description": "错误：“一只娱乐场”。正确：“一座娱乐场”。“只”用于动物等，大型场所应用量词“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我上班的路上有一张娱乐场。", "corrected_sentence": "我上班的路上有一座娱乐场。", "error_description": "错误：“一张娱乐场”。正确：“一座娱乐场”。“张”用于平面物件，大型场所应用量词“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
