INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91975, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "少了，不够。", "primary_collocate": null, "pronunciation": "quē", "ipa": "tɕʰɥe˥", "syllable_count": 1, "sentences": [{"text": "这本书缺了两页。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双袜子缺了一只，找不到了。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套杯子缺了一个，不能卖。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份名单缺了他的名字。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拼图缺了一块，怎么也拼不完。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数一数，还缺三个本子。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表缺一个日期。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单缺了一页，我们找服务员要。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这副扑克缺了两张牌，没法玩。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子里的零件缺了几个。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺了", "label": "体标"}, {"form": "缺少", "label": "复合"}], "register": "中性", "sense_fingerprint": "缺：整体中少了一部分，不完整", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dde39b2-d898-475e-ae86-85b21cca451a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91975, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "缺", "is_correct": true, "explanation": "缺（quē，第一声）表示少了一部分，不完整，是本词。"}, {"text": "约", "is_correct": false, "explanation": "约（yuē，第一声）与 quē 只差声母（y 与 q），声调相同，意思是“约定”。"}, {"text": "撅", "is_correct": false, "explanation": "撅（juē，第一声）与 quē 只差声母（j 与 q），声调相同，意思是“撅起”。"}, {"text": "却", "is_correct": false, "explanation": "却（què，第四声）与 quē 只差声调，意思是转折副词“却”。"}], "explanations": {"缺": "缺（quē，第一声）表示少了一部分，不完整，是本词。", "约": "约（yuē，第一声）与 quē 只差声母（y 与 q），声调相同，意思是“约定”。", "撅": "撅（juē，第一声）与 quē 只差声母（j 与 q），声调相同，意思是“撅起”。", "却": "却（què，第四声）与 quē 只差声调，意思是转折副词“却”。"}, "sentence_index": null, "correct_answer": "缺"}, "level_3": {"options": [{"text": "缺", "is_correct": true, "explanation": "正确：“缺”表示书少了两页，是本词的意思。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，不能带“书”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“书”和“页”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热烹饪，与书页无关。"}], "explanations": {"缺": "正确：“缺”表示书少了两页，是本词的意思。", "喝": "搭配：“喝”的宾语应是饮品，不能带“书”作宾语。", "唱": "搭配：“唱”不能与“书”和“页”搭配。", "煮": "语义：“煮”指加热烹饪，与书页无关。"}, "sentence_index": 0, "correct_answer": "缺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天缺了一天课。", "explanation": "这里的“缺”指缺课、缺勤，是另一个义项，与本词“整体中少了一部分”的意思不同。"}, {"text": "最近天气干，城里很缺水。", "explanation": "这里的“缺”指某种东西数量不够，是另一个义项，与本词“整体中少了一部分”的意思不同。"}, {"text": "她今天上班缺了两个小时。", "explanation": "这里的“缺”指缺勤、没到场，是另一个义项，与本词“整体中少了一部分”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91975, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "缺", "is_correct": true, "explanation": "缺（quē，第一声）表示少了一部分，不完整，是本词。"}, {"text": "却", "is_correct": false, "explanation": "却（què，第四声）与 quē（第一声）声调不同，意思是“却”。"}, {"text": "靴", "is_correct": false, "explanation": "靴（xuē）与 quē 声母不同（x 与 q），意思是“靴子”。"}, {"text": "切", "is_correct": false, "explanation": "切（qiē）与 quē 介音不同（i 与 u），意思是“切开”。"}, {"text": "瘸", "is_correct": false, "explanation": "瘸（qué，第二声）与 quē 声调不同，意思是“瘸腿”。"}], "explanations": {"缺": "缺（quē，第一声）表示少了一部分，不完整，是本词。", "却": "却（què，第四声）与 quē（第一声）声调不同，意思是“却”。", "靴": "靴（xuē）与 quē 声母不同（x 与 q），意思是“靴子”。", "切": "切（qiē）与 quē 介音不同（i 与 u），意思是“切开”。", "瘸": "瘸（qué，第二声）与 quē 声调不同，意思是“瘸腿”。"}, "sentence_index": null, "correct_answer": "缺"}, "level_3": {"options": [{"text": "缺", "is_correct": true, "explanation": "正确：“缺”表示表中还少一个日期。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，与填写表格的语境不符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣物，不能说穿日期。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用气流推动，与表格无关。"}], "explanations": {"缺": "正确：“缺”表示表中还少一个日期。", "踢": "语义：“踢”指用脚击打，与填写表格的语境不符。", "穿": "搭配：“穿”的宾语应是衣物，不能说穿日期。", "吹": "语义：“吹”指用气流推动，与表格无关。"}, "sentence_index": 6, "correct_answer": "缺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不缺钱，就是很忙。", "explanation": "这里的“缺”指东西数量不够，是另一个义项，与本词“整体中少了一部分”的意思不同。"}, {"text": "这个城市很缺老师。", "explanation": "这里的“缺”指人手不够，是另一个义项，与本词“整体中少了一部分”的意思不同。"}, {"text": "他上周缺了三节课，老师很着急。", "explanation": "这里的“缺”指缺课、缺勤，是另一个义项，与本词“整体中少了一部分”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
