INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅画被缺了一角。", "corrected_sentence": "这幅画缺了一角。", "error_description": "错误形式：“被缺了一角”。正确形式：“缺了一角”。原因：“缺”表示事物本身少了一部分，不是能受他人支配的动作，不能用“被”字引出，“被”字多余。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
