INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "缺少；不够。", "primary_collocate": null, "pronunciation": "quē", "ipa": "tɕʰɥe˥", "syllable_count": 1, "sentences": [{"text": "这个队还缺一个守门员。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家最近缺水，不能洗太久。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不缺钱，只缺时间。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭时发现缺盐了。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司缺有经验的人。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里缺水，树很少。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天开会，还缺几把椅子。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个汤好像缺味道，再放点盐吧。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校缺老师，一个人要教两个班。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他什么都不缺，就缺一个朋友。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺了", "label": "体标"}, {"form": "缺少", "label": "复合"}, {"form": "缺乏", "label": "复合"}], "register": "中性", "sense_fingerprint": "缺：缺少某种东西或人，数量不够", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dde39b2-d898-475e-ae86-85b21cca451a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91976, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "缺", "is_correct": true, "explanation": "缺（quē，第一声）表示缺少、不够，是本词。"}, {"text": "却", "is_correct": false, "explanation": "却（què，第四声）与 quē（第一声）声调不同，意思是“却”。"}, {"text": "靴", "is_correct": false, "explanation": "靴（xuē）与 quē 声母不同（x 与 q），意思是“靴子”。"}, {"text": "切", "is_correct": false, "explanation": "切（qiē）与 quē 介音不同（i 与 u），意思是“切开”。"}, {"text": "瘸", "is_correct": false, "explanation": "瘸（qué，第二声）与 quē 声调不同，意思是“瘸腿”。"}], "explanations": {"缺": "缺（quē，第一声）表示缺少、不够，是本词。", "却": "却（què，第四声）与 quē（第一声）声调不同，意思是“却”。", "靴": "靴（xuē）与 quē 声母不同（x 与 q），意思是“靴子”。", "切": "切（qiē）与 quē 介音不同（i 与 u），意思是“切开”。", "瘸": "瘸（qué，第二声）与 quē 声调不同，意思是“瘸腿”。"}, "sentence_index": null, "correct_answer": "缺"}, "level_3": {"options": [{"text": "缺", "is_correct": true, "explanation": "正确：“缺”表示队里缺少一个守门员，与“还”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说吃守门员。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象通常是动物或婴儿，不能用于守门员。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，与“队伍还需要一个人”的句意不符。"}], "explanations": {"缺": "正确：“缺”表示队里缺少一个守门员，与“还”搭配。", "吃": "搭配：“吃”的宾语应是食物，不能说吃守门员。", "喂": "搭配：“喂”的对象通常是动物或婴儿，不能用于守门员。", "洗": "语义：“洗”指清洁，与“队伍还需要一个人”的句意不符。"}, "sentence_index": 0, "correct_answer": "缺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他上周缺了两节课，老师问了原因。", "explanation": "这里的“缺”指缺课、缺勤，是另一个义项，与本词“缺少、不够”的意思不同。"}, {"text": "她这个月缺了三次会。", "explanation": "这里的“缺”指缺席、没到场，是另一个义项，与本词“缺少、不够”的意思不同。"}, {"text": "这个人太缺德了，经常骗人。", "explanation": "这里的“缺”指缺少道德、品行不端，是另一个义项，与本词“缺少、不够”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91976, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "缺", "is_correct": true, "explanation": "缺（quē，第一声）表示缺少、不够，是本词。"}, {"text": "约", "is_correct": false, "explanation": "约（yuē，第一声）与 quē 只差声母（y 与 q），声调相同，意思是“约定”。"}, {"text": "撅", "is_correct": false, "explanation": "撅（juē，第一声）与 quē 只差声母（j 与 q），声调相同，意思是“撅起”。"}, {"text": "瘸", "is_correct": false, "explanation": "瘸（qué，第二声）与 quē 只差声调，意思是“瘸腿”。"}], "explanations": {"缺": "缺（quē，第一声）表示缺少、不够，是本词。", "约": "约（yuē，第一声）与 quē 只差声母（y 与 q），声调相同，意思是“约定”。", "撅": "撅（juē，第一声）与 quē 只差声母（j 与 q），声调相同，意思是“撅起”。", "瘸": "瘸（qué，第二声）与 quē 只差声调，意思是“瘸腿”。"}, "sentence_index": null, "correct_answer": "缺"}, "level_3": {"options": [{"text": "缺", "is_correct": true, "explanation": "正确：“缺”表示还少几把椅子，与“还”和“几把”搭配。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与为明天开会准备椅子的语境相反。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“椅子”作宾语。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，与准备会议用椅子的语境不符。"}], "explanations": {"缺": "正确：“缺”表示还少几把椅子，与“还”和“几把”搭配。", "扔": "语义：“扔”指丢弃，与为明天开会准备椅子的语境相反。", "唱": "搭配：“唱”不能带“椅子”作宾语。", "踢": "语义：“踢”指用脚击打，与准备会议用椅子的语境不符。"}, "sentence_index": 6, "correct_answer": "缺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她昨天缺了一天班。", "explanation": "这里的“缺”指缺勤、没到场，是另一个义项，与本词“缺少、不够”的意思不同。"}, {"text": "这种人太缺德，我们少和他来往。", "explanation": "这里的“缺”指缺少道德、品行不端，是另一个义项，与本词“缺少、不够”的意思不同。"}, {"text": "他连着缺了三天课，家长很着急。", "explanation": "这里的“缺”指缺课、缺勤，是另一个义项，与本词“缺少、不够”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班还把缺一个人。", "corrected_sentence": "我们班还缺一个人。", "error_description": "错误形式：“还把缺一个人”。正确形式：“还缺一个人”。原因：“缺”是动词，不能用“把”字引出，“把”后面要有受事宾语，“把缺”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市缺得两个收银员。", "corrected_sentence": "这家超市缺两个收银员。", "error_description": "错误形式：“缺得两个收银员”。正确形式：“缺两个收银员”。原因：“得”字要引出补语，“缺”后直接接数量宾语，多出的“得”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
