INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91977, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发言是在开会的时候，站起来说出自己的想法。", "primary_collocate": null, "pronunciation": "fā yán", "ipa": "fa˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "开会时，大家都安静地听他发言。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站起来发言，大家都看着她。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次讨论会上，同学们都想发言。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁想在会上发言，请先举手。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开会发言的时候声音很大，大家都听得清楚。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理发言以后，会议就结束了。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次在全班同学面前发言，心跳得很快。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上有三位老人发言，讲得都很好。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议时间不多了，请每位代表简单发言。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上只发言了一分钟。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发过言", "label": "体标"}, {"form": "发了言", "label": "体标"}, {"form": "发言人", "label": "复合"}, {"form": "發言", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开会时站起来说出自己的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2bbdfe-45ed-43d8-ab7a-6e76fe728753') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发言", "is_correct": true, "explanation": "发言：在会上表达想法，“听他发言”符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不能让人安静地听，句子荒谬。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与开会场合无关，“听他游泳”不成立。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“听”的对象是说话或声音，“跳舞”不能被听，句子荒谬。"}], "explanations": {"发言": "发言：在会上表达想法，“听他发言”符合句意。", "睡觉": "语义：“睡觉”不能让人安静地听，句子荒谬。", "游泳": "语义：“游泳”与开会场合无关，“听他游泳”不成立。", "跳舞": "语义：“听”的对象是说话或声音，“跳舞”不能被听，句子荒谬。"}, "sentence_index": 0, "correct_answer": "发言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在家里跟爸爸发言，说了一件小事。", "explanation": "这里应该用〈说话〉。发言指在会议等集体场合站起来表达想法，家里聊天要用说话。"}, {"text": "他一个人在房间里发言了一首歌。", "explanation": "这里应该用〈唱〉。发言指在会议或集体场合表达意见，唱歌要用唱。"}, {"text": "孩子在湖边大声发言了三遍。", "explanation": "这里应该用〈呼喊〉。发言指有条理地表达意见，湖边大声呼喊要用呼喊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发言", "is_correct": true, "explanation": "发言：在全班同学面前表达意见，符合句意。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与全班同学面前的紧张情境不符。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”是外出办事，不能在全班同学面前进行，句子荒谬。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“心跳得很快”的紧张情境相悖，句子不通。"}], "explanations": {"发言": "发言：在全班同学面前表达意见，符合句意。", "洗澡": "语义：“洗澡”与全班同学面前的紧张情境不符。", "出差": "语义：“出差”是外出办事，不能在全班同学面前进行，句子荒谬。", "睡觉": "语义：“睡觉”与“心跳得很快”的紧张情境相悖，句子不通。"}, "sentence_index": 6, "correct_answer": "发言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人在菜地里发言了很久。", "explanation": "这里应该用〈干活〉。发言指在会议或集体场合表达意见，在菜地里劳作要用干活。"}, {"text": "宝宝在被子里发言了一夜。", "explanation": "这里应该用〈说梦话〉。发言指在会议或集体场合表达意见，宝宝躺在被子里含糊地说话要用说梦话。"}, {"text": "她在厨房里发言了很久。", "explanation": "这里应该用〈念叨〉。发言指在会议或集体场合表达意见，在厨房里反复念叨要用念叨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在会上了发言，心里很紧张。", "corrected_sentence": "我在会上发了言，心里很紧张。", "error_description": "体标“了”位置错误。“了”应放在“发”和“言”之间，写作“发了言”，“了发言”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在会上做了一只发言。", "corrected_sentence": "他在会上做了一次发言。", "error_description": "量词用错。“发言”计量应用“次”，“只”用于动物、手等，不能修饰发言。应为“做了一次发言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
