INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在会议或集体场合上表达意见、看法。", "primary_collocate": null, "pronunciation": "fā yán", "ipa": "fa˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "开会时，王经理第一个站起来发言。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家按顺序发言，不要随便打断别人。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很紧张，轮到他发言时，手一直在发抖。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李在班会上发言，说了自己的想法。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开始前，主持人请代表们依次发言。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她准备了很久，终于敢在大会上发言了。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师鼓励我们在课堂讨论中积极发言。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的会上，你有什么想法就发言吧。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举手想发言，可是主持人没有看见。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时每个人发言的时间只有三分钟。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发过言", "label": "体标"}, {"form": "发了言", "label": "体标"}, {"form": "发言人", "label": "复合"}, {"form": "發言", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在会议等集体场合表达意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2bbdfe-45ed-43d8-ab7a-6e76fe728753') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发言", "is_correct": true, "explanation": "发言：在会上站起来表达意见，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“开会时站起来”的场合不符，句子荒谬。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要水的场合，在会上站起来不成立。"}, {"text": "出差", "is_correct": false, "explanation": "配价：“出差”不能与“站起来”构成动作，且需要说明去向，句子不成立。"}], "explanations": {"发言": "发言：在会上站起来表达意见，符合句意。", "睡觉": "语义：“睡觉”与“开会时站起来”的场合不符，句子荒谬。", "游泳": "语义：“游泳”需要水的场合，在会上站起来不成立。", "出差": "配价：“出差”不能与“站起来”构成动作，且需要说明去向，句子不成立。"}, "sentence_index": 0, "correct_answer": "发言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小李在家里跟妈妈发言。", "explanation": "这里应该用〈说话〉。发言指在会议或集体场合表达意见，家里聊天要用说话。"}, {"text": "我们俩在咖啡馆里发言了很久。", "explanation": "这里应该用〈聊〉。发言指在会议或集体场合表达意见，两人闲聊要用聊。"}, {"text": "他在山上大声发言了三遍。", "explanation": "这里应该用〈喊〉。发言指有条理地表达意见，山上大声呼喊要用喊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发言", "is_correct": true, "explanation": "发言：在课堂讨论中表达意见，符合句意。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与课堂讨论无关，句子不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与课堂讨论的语境不符。"}, {"text": "发愁", "is_correct": false, "explanation": "搭配：“积极”一般不修饰“发愁”这类消极状态。"}], "explanations": {"发言": "发言：在课堂讨论中表达意见，符合句意。", "吃饭": "语义：“吃饭”与课堂讨论无关，句子不通。", "跳舞": "语义：“跳舞”与课堂讨论的语境不符。", "发愁": "搭配：“积极”一般不修饰“发愁”这类消极状态。"}, "sentence_index": 6, "correct_answer": "发言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里发言了很久。", "explanation": "这里应该用〈唠叨〉。发言指在会议或集体场合表达意见，家里的啰嗦要用唠叨。"}, {"text": "他在电话里跟朋友发言了很久。", "explanation": "这里应该用〈聊天〉。发言指在会议或集体场合表达意见，和朋友打电话闲谈要用聊天。"}, {"text": "妹妹在床上发言了一下午。", "explanation": "这里应该用〈打盹〉。发言指在会议或集体场合表达意见，躺在床上小睡要用打盹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天要在会上发过言。", "corrected_sentence": "我明天要在会上发言。", "error_description": "经历体“过”用错。“过”表示已经经历过的动作，与“明天”的将来意思矛盾，应去掉“过”，写作“发言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚才在会上了发言。", "corrected_sentence": "他刚才在会上发了言。", "error_description": "体标“了”位置错误。“了”应放在“发”和“言”之间，写作“发了言”，“了发言”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
