INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91979, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "嫌是觉得不好，不喜欢。", "primary_collocate": null, "pronunciation": "xián", "ipa": "ɕjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "他嫌这件衣服太贵。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈嫌我房间太乱。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我嫌这里太吵，想换个地方。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嫌路远，不想走过去。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子嫌饭太咸，不吃了。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫌这双鞋太小。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶嫌电视声音太大。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别嫌我说话太直。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板嫌他做事太慢。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嫌菜不好吃，只喝了汤。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "嫌：觉得某事物不好而不喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbb1089a-7f0e-4a1d-9b64-4094ab18e718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91979, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嫌", "is_correct": true, "explanation": "正确：嫌是觉得不好，不喜欢。"}, {"text": "现", "is_correct": false, "explanation": "xiàn（第四声）与 xián（第二声）只有声调不同，意思是现在。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xián（第二声）只有声调不同，意思是在前、最初。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 xián（第二声）只有声母不同，q 与 x 不同，意思是货币。"}], "explanations": {"嫌": "正确：嫌是觉得不好，不喜欢。", "现": "xiàn（第四声）与 xián（第二声）只有声调不同，意思是现在。", "先": "xiān（第一声）与 xián（第二声）只有声调不同，意思是在前、最初。", "钱": "qián（第二声）与 xián（第二声）只有声母不同，q 与 x 不同，意思是货币。"}, "sentence_index": null, "correct_answer": "嫌"}, "level_3": {"options": [{"text": "嫌", "is_correct": true, "explanation": "正确：“嫌这件衣服太贵”表示觉得衣服不好，不喜欢。"}, {"text": "赞", "is_correct": false, "explanation": "语义：“赞”是称赞，与“太贵”的不满相反。"}, {"text": "叹", "is_correct": false, "explanation": "语义：“叹”是叹气，不能带“这件衣服太贵”这样的评价作宾语，表示不满要用“嫌”。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”表示喜爱，与“太贵”的不满相反。"}], "explanations": {"嫌": "正确：“嫌这件衣服太贵”表示觉得衣服不好，不喜欢。", "赞": "语义：“赞”是称赞，与“太贵”的不满相反。", "叹": "语义：“叹”是叹气，不能带“这件衣服太贵”这样的评价作宾语，表示不满要用“嫌”。", "喜欢": "语义：“喜欢”表示喜爱，与“太贵”的不满相反。"}, "sentence_index": 0, "correct_answer": "嫌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈嫌我很懂事。", "explanation": "这里应该用〈夸〉。“嫌”表示不满意，不能用来称赞“懂事”这样的优点。"}, {"text": "老师嫌他的认真态度，每次都很感动。", "explanation": "这里应该用〈欣赏〉。“嫌”表示不喜欢，与“很感动”的赞许语气矛盾。"}, {"text": "他嫌这次难得的机会，兴奋得睡不着。", "explanation": "这里应该用〈珍惜〉。“嫌”表示不满，与“兴奋得睡不着”的情绪矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91979, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嫌", "is_correct": true, "explanation": "正确：嫌是觉得不好，不喜欢。"}, {"text": "线", "is_correct": false, "explanation": "xiàn（第四声）与 xián（第二声）只有声调不同，意思是细长的线条或线路。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xián（第二声）只有声调不同，意思是明显。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xián（第二声）只有声调不同，意思是新鲜。"}], "explanations": {"嫌": "正确：嫌是觉得不好，不喜欢。", "线": "xiàn（第四声）与 xián（第二声）只有声调不同，意思是细长的线条或线路。", "显": "xiǎn（第三声）与 xián（第二声）只有声调不同，意思是明显。", "鲜": "xiān（第一声）与 xián（第二声）只有声调不同，意思是新鲜。"}, "sentence_index": null, "correct_answer": "嫌"}, "level_3": {"options": [{"text": "嫌", "is_correct": true, "explanation": "正确：“嫌电视声音太大”表示不满，不喜欢。"}, {"text": "盼", "is_correct": false, "explanation": "语义：“盼”是期望，与“声音太大”的不满不合。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与“声音太大”的不满相反。"}, {"text": "摸", "is_correct": false, "explanation": "配价：“摸”要带可以触碰的宾语，不能直接接“声音太大”这样的评价。"}], "explanations": {"嫌": "正确：“嫌电视声音太大”表示不满，不喜欢。", "盼": "语义：“盼”是期望，与“声音太大”的不满不合。", "夸": "语义：“夸”是称赞，与“声音太大”的不满相反。", "摸": "配价：“摸”要带可以触碰的宾语，不能直接接“声音太大”这样的评价。"}, "sentence_index": 6, "correct_answer": "嫌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我嫌你的帮助，心里很感激。", "explanation": "这里应该用〈感谢〉。“嫌”表示不满，与“心里很感激”矛盾。"}, {"text": "他嫌这顿晚饭很美味。", "explanation": "这里应该用〈称赞〉。“嫌”表示不满，不能用来评价美味的晚饭。"}, {"text": "我嫌他的成绩很优秀。", "explanation": "这里应该用〈佩服〉。“嫌”表示不满，不能用来表达对别人优秀成绩的敬佩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
