INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91980, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "厌恶；不满意。", "primary_collocate": null, "pronunciation": "xián", "ipa": "ɕjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "她嫌弟弟太吵。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别嫌我家小，请进来坐吧。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嫌我笨，不愿跟我一起做。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嫌这个工作太累，工资又少。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人嫌他穿得太旧。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫌丈夫不爱干净。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，我嫌屋里闷。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嫌老师讲得太快，听不懂。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们嫌作业太多。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我嫌手机屏幕太小，换了一个大的。", "target_word": "嫌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "嫌：对人或事物厌恶、不满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbb1089a-7f0e-4a1d-9b64-4094ab18e718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91980, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嫌", "is_correct": true, "explanation": "正确：嫌是厌恶，不满意。"}, {"text": "现", "is_correct": false, "explanation": "xiàn（第四声）与 xián（第二声）只有声调不同，意思是现在。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xián（第二声）只有声调不同，意思是在前、最初。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 xián（第二声）只有声母不同，q 与 x 不同，意思是货币。"}], "explanations": {"嫌": "正确：嫌是厌恶，不满意。", "现": "xiàn（第四声）与 xián（第二声）只有声调不同，意思是现在。", "先": "xiān（第一声）与 xián（第二声）只有声调不同，意思是在前、最初。", "钱": "qián（第二声）与 xián（第二声）只有声母不同，q 与 x 不同，意思是货币。"}, "sentence_index": null, "correct_answer": "嫌"}, "level_3": {"options": [{"text": "嫌", "is_correct": true, "explanation": "正确：“嫌弟弟太吵”表示厌恶、不满意。"}, {"text": "赞", "is_correct": false, "explanation": "语义：“赞”是称赞，不能用来评价“太吵”。"}, {"text": "盼", "is_correct": false, "explanation": "语义：“盼”是期望，与“太吵”的不满不合。"}, {"text": "摸", "is_correct": false, "explanation": "配价：“摸”要带可以触碰的宾语，不能直接接“太吵”这样的评价。"}], "explanations": {"嫌": "正确：“嫌弟弟太吵”表示厌恶、不满意。", "赞": "语义：“赞”是称赞，不能用来评价“太吵”。", "盼": "语义：“盼”是期望，与“太吵”的不满不合。", "摸": "配价：“摸”要带可以触碰的宾语，不能直接接“太吵”这样的评价。"}, "sentence_index": 0, "correct_answer": "嫌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师嫌他的进步，又惊又喜。", "explanation": "这里应该用〈表扬〉。“嫌”表示不满，与“又惊又喜”的情绪矛盾。"}, {"text": "大家嫌这位医生的技术很高明。", "explanation": "这里应该用〈赞叹〉。“嫌”表示厌恶、不满意，不能用来赞叹高明的技术。"}, {"text": "她嫌老朋友的友情，心里很温暖。", "explanation": "这里应该用〈珍惜〉。“嫌”表示厌恶，与“心里很温暖”的感受矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91980, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嫌", "is_correct": true, "explanation": "正确：嫌是厌恶，不满意。"}, {"text": "线", "is_correct": false, "explanation": "xiàn（第四声）与 xián（第二声）只有声调不同，意思是细长的线条或线路。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xián（第二声）只有声调不同，意思是明显。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xián（第二声）只有声调不同，意思是新鲜。"}], "explanations": {"嫌": "正确：嫌是厌恶，不满意。", "线": "xiàn（第四声）与 xián（第二声）只有声调不同，意思是细长的线条或线路。", "显": "xiǎn（第三声）与 xián（第二声）只有声调不同，意思是明显。", "鲜": "xiān（第一声）与 xián（第二声）只有声调不同，意思是新鲜。"}, "sentence_index": null, "correct_answer": "嫌"}, "level_3": {"options": [{"text": "嫌", "is_correct": true, "explanation": "正确：“嫌屋里闷”表示不满意。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与“屋里闷”的不满不合。"}, {"text": "爱", "is_correct": false, "explanation": "语义：“爱”表示喜爱，与“屋里闷”的不满相反。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”表示喜爱，与“天气太热”之后的不满语境相反。"}], "explanations": {"嫌": "正确：“嫌屋里闷”表示不满意。", "夸": "语义：“夸”是称赞，与“屋里闷”的不满不合。", "爱": "语义：“爱”表示喜爱，与“屋里闷”的不满相反。", "喜欢": "语义：“喜欢”表示喜爱，与“天气太热”之后的不满语境相反。"}, "sentence_index": 6, "correct_answer": "嫌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我嫌大家的支持，眼眶都红了。", "explanation": "这里应该用〈感谢〉。“嫌”表示不满，与“眼眶都红了”的感动矛盾。"}, {"text": "我嫌这个假期很愉快。", "explanation": "这里应该用〈享受〉。“嫌”表示不满，不能用来形容愉快的假期。"}, {"text": "我嫌他的勇气，忍不住鼓掌。", "explanation": "这里应该用〈佩服〉。“嫌”表示不满，与“忍不住鼓掌”的赞赏矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈嫌这个房间暗太。", "corrected_sentence": "妈妈嫌这个房间太暗。", "error_description": "错误形式：“暗太”；正确形式：“太暗”；原因：程度副词“太”要放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "嫌别这个小店太旧，东西都很好。", "corrected_sentence": "别嫌这个小店太旧，东西都很好。", "error_description": "错误形式：“嫌别”；正确形式：“别嫌”；原因：否定副词“别”要放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
