INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91981, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "站在别人这一边，大声说我们支持你。", "primary_collocate": null, "pronunciation": "shēng yuán", "ipa": "ʂɤŋ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "同学们都来声援他。", "target_word": "声援", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人来到现场声援工人。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网友们在网上声援那位老师。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们到现场声援自己的球队。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他被别人误会的时候，很多网友都声援他。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师们也站出来声援这些学生。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去年声援过他们的活动。", "target_word": "声援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在街上举着牌子声援工人。", "target_word": "声援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要声援他，让他知道他不是一个人。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多歌手发信息声援这位朋友。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "声援了", "label": "体标"}, {"form": "声援过", "label": "体标"}, {"form": "声援着", "label": "体标"}], "register": "书面", "sense_fingerprint": "站在某人一边，大声表示支持他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声援", "is_correct": true, "explanation": "正确。声援是站在别人一边、表示支持。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是物品或机器，不能用于人。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：点燃针对火或可燃物，不能用于人，句意不通。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤是加热食物的动作，与“同学们都来”表达的支持无关。"}], "explanations": {"声援": "正确。声援是站在别人一边、表示支持。", "修理": "搭配：“修理”的对象是物品或机器，不能用于人。", "点燃": "语义：点燃针对火或可燃物，不能用于人，句意不通。", "烤": "语义：烤是加热食物的动作，与“同学们都来”表达的支持无关。"}, "sentence_index": 0, "correct_answer": "声援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他饿了，我们声援了他一碗饭。", "explanation": "这里应该用〈送〉。声援是表示支持的态度，不是给别人东西，不能带“一碗饭”这样的物品。"}, {"text": "我们声援这张桌子。", "explanation": "宾语错误：声援的对象应是人或群体，桌子不能被声援。"}, {"text": "我的手机坏了，同学帮我声援好了。", "explanation": "这里应该用〈修理〉。声援是表示支持，不是修东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声援", "is_correct": true, "explanation": "正确。声援表示公开支持，可以说“声援他们的活动”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或房间，不能说“打扫活动”。"}, {"text": "冷却", "is_correct": false, "explanation": "搭配：“冷却”用于温度或热的东西，不能用于活动。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：吞下是把东西咽下去的动作，不能用于活动。"}], "explanations": {"声援": "正确。声援表示公开支持，可以说“声援他们的活动”。", "打扫": "搭配：“打扫”的对象是场地或房间，不能说“打扫活动”。", "冷却": "搭配：“冷却”用于温度或热的东西，不能用于活动。", "吞下": "语义：吞下是把东西咽下去的动作，不能用于活动。"}, "sentence_index": 6, "correct_answer": "声援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子声援了那位朋友。", "explanation": "主语错误：声援的主语须是人或群体，椅子不能声援。"}, {"text": "这位朋友声援了一杯咖啡，慢慢喝完了。", "explanation": "这里应该用〈点〉或〈买〉。声援是表示支持，不能用于饮料。"}, {"text": "很多歌手声援了这位朋友的生日蛋糕。", "explanation": "宾语错误：声援的对象应是人或群体，蛋糕不能被声援。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在比赛现场声援了过自己的球队。", "corrected_sentence": "我们在比赛现场声援过自己的球队。", "error_description": "助词叠用错误：“了”与经历体“过”不能同时用在同一动词上，应只保留“过”，说“声援过自己的球队”，不能说“声援了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她曾经在网上声援了过那两位被误解的老师。", "corrected_sentence": "她曾经在网上声援过那两位被误解的老师。", "error_description": "助词叠用错误：“了”与经历体“过”不能同时用在同一动词上，应只保留“过”，说“曾经声援过那两位被误解的老师”，不能说“声援了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
