INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91982, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开发表言论或采取行动，表示支持。", "primary_collocate": null, "pronunciation": "shēng yuán", "ipa": "ʂɤŋ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "很多国家发表声明，声援这次行动。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学者们公开发表文章声援他们。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们写了一封公开信声援他。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "许多市民上街游行，声援受伤的工人。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明星们在网上发文章声援这位作家。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们在校门口举着牌子声援老师。", "target_word": "声援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾公开声援过这个活动。", "target_word": "声援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人在网上签名，声援他的决定。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各国代表发言，声援这个国家的人民。", "target_word": "声援", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球迷们唱着歌声援自己的球队。", "target_word": "声援", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "声援了", "label": "体标"}, {"form": "声援过", "label": "体标"}, {"form": "声援着", "label": "体标"}], "register": "书面", "sense_fingerprint": "通过声明、文章、游行等公开方式表示支持", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声援", "is_correct": true, "explanation": "正确。声援表示通过公开声明表示支持，与“发表声明”搭配自然。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物或幼儿，不能用于“行动”。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁是用火毁掉东西，不能用于“这次行动”，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是文字或语言，不能用于“这次行动”。"}], "explanations": {"声援": "正确。声援表示通过公开声明表示支持，与“发表声明”搭配自然。", "喂养": "搭配：“喂养”的对象是动物或幼儿，不能用于“行动”。", "烧毁": "语义：烧毁是用火毁掉东西，不能用于“这次行动”，句意不通。", "翻译": "搭配：“翻译”的对象是文字或语言，不能用于“这次行动”。"}, "sentence_index": 0, "correct_answer": "声援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "许多市民上街游行，声援了一大袋水果。", "explanation": "宾语错误：声援的对象应是人、群体或他们的行动，水果不能被声援。"}, {"text": "工人受伤了，医生马上给他声援了伤口。", "explanation": "这里应该用〈包扎〉。声援是公开表示支持，不是处理伤口的动作。"}, {"text": "下雨了，市民们打开伞声援自己。", "explanation": "这里应该用〈保护〉或〈挡雨〉。声援是公开表示支持别人，不是遮挡风雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声援", "is_correct": true, "explanation": "正确。“公开声援”表示公开地表示支持。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修是改善建筑或房间的工作，不能用于“活动”的支持。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割是收获农作物的动作，与活动无关。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象是建筑或设施，不能说“拆除这个活动”。"}], "explanations": {"声援": "正确。“公开声援”表示公开地表示支持。", "装修": "语义：装修是改善建筑或房间的工作，不能用于“活动”的支持。", "收割": "语义：收割是收获农作物的动作，与活动无关。", "拆除": "搭配：“拆除”的对象是建筑或设施，不能说“拆除这个活动”。"}, "sentence_index": 6, "correct_answer": "声援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子声援了受伤的工人。", "explanation": "主语错误：声援的主语须是人或群体，桌子不能声援。"}, {"text": "球迷们饿了，就去餐厅声援了一顿饭。", "explanation": "这里应该用〈吃〉。声援是公开表示支持，不能用于吃饭。"}, {"text": "球迷们声援了球场上的草坪。", "explanation": "宾语错误：声援的对象应是人或群体，草坪不能被声援。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学者们发表文章，声援了过这次行动。", "corrected_sentence": "学者们发表文章，声援了这次行动。", "error_description": "助词叠用错误：“声援了”已带动态助词“了”，不能再加经历体“过”，应说“声援了这次行动”，不能说“声援了过这次行动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经公开声援了过那次游行。", "corrected_sentence": "他曾经公开声援过那次游行。", "error_description": "助词叠用错误：“了”与经历体“过”不能同时用在同一动词上，应只保留“过”，说“曾经公开声援过那次游行”，不能说“声援了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "满", "is_correct": true, "explanation": "反义：“满”指装得很多，与“空”指里面什么也没有相对。"}, {"text": "硬", "is_correct": false, "explanation": "无关：“硬”指不软，与“空”没有反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”指形状，与“空”没有反义关系。"}, {"text": "大", "is_correct": false, "explanation": "无关：“大”指体积或面积多，与“空”没有反义关系。"}], "correct_answer": "满", "explanations": {"满": "反义：“满”指装得很多，与“空”指里面什么也没有相对。", "硬": "无关：“硬”指不软，与“空”没有反义关系。", "圆": "无关：“圆”指形状，与“空”没有反义关系。", "大": "无关：“大”指体积或面积多，与“空”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "满", "is_correct": true, "explanation": "反义：“满”指装得很多，与“空”指里面什么也没有相对。"}, {"text": "慢", "is_correct": false, "explanation": "无关：“慢”指速度低，与“空”没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "无关：“深”指从表面到底部的距离大，与“空”没有反义关系。"}, {"text": "薄", "is_correct": false, "explanation": "无关：“薄”指厚度小，与“空”没有反义关系。"}], "correct_answer": "满", "explanations": {"满": "反义：“满”指装得很多，与“空”指里面什么也没有相对。", "慢": "无关：“慢”指速度低，与“空”没有反义关系。", "深": "无关：“深”指从表面到底部的距离大，与“空”没有反义关系。", "薄": "无关：“薄”指厚度小，与“空”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "空是里面什么也没有。", "primary_collocate": null, "pronunciation": "kōng", "ipa": "kʰʊŋ˥", "syllable_count": 1, "sentences": [{"text": "这个杯子空了，快倒点水吧。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他回到家，发现屋子里是空的。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的冰箱几乎是空的。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只篮子是空的，没有苹果。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个纸箱是空的，我正好用来装书。", "target_word": "空", "complexity_tier": "T3", "furigana": "nà ge zhǐ xiāng shì kōng de, wǒ zhèng hǎo yòng lái zhuāng shū.", "sentence_source": "generated"}, {"text": "饮料喝完了，罐子空了。", "target_word": "空", "complexity_tier": "T3", "furigana": "yǐn liào hē wán le, guàn zi kōng le.", "sentence_source": "generated"}, {"text": "你的碗空了，我再给你盛一点。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包是空的，他没带书。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "抽屉打开后，里面是空的。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "东西拿走后，箱子就空了。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "空空", "label": "重叠"}, {"form": "空了", "label": "体标"}, {"form": "空着", "label": "体标"}], "register": "中性", "sense_fingerprint": "空-形容词-里面什么也没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2d808-5f98-4557-8046-f4e5641b51ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "空", "is_correct": true, "explanation": "正确：空（kōng，第一声）表示里面什么也没有。"}, {"text": "控", "is_correct": false, "explanation": "kòng（第四声）与 kōng（第一声）声调不同，意思是控制。"}, {"text": "孔", "is_correct": false, "explanation": "kǒng（第三声）与 kōng（第一声）声调不同，意思是小洞。"}, {"text": "恐", "is_correct": false, "explanation": "kǒng（第三声）与 kōng（第一声）声调不同，意思是害怕。"}], "explanations": {"空": "正确：空（kōng，第一声）表示里面什么也没有。", "控": "kòng（第四声）与 kōng（第一声）声调不同，意思是控制。", "孔": "kǒng（第三声）与 kōng（第一声）声调不同，意思是小洞。", "恐": "kǒng（第三声）与 kōng（第一声）声调不同，意思是害怕。"}, "sentence_index": null, "correct_answer": "空"}, "level_3": {"options": [{"text": "空", "is_correct": true, "explanation": "正确：空了表示杯中已没有水，所以需要再倒水。"}, {"text": "满", "is_correct": false, "explanation": "语义：“满了”说明杯子已装满，与“快倒点水吧”矛盾。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：“瘦”形容人或动物的体形，不能用来形容杯子。"}, {"text": "破", "is_correct": false, "explanation": "语义：“破了”说明杯子已经坏了、无法盛水，与“倒点水”矛盾。"}], "explanations": {"空": "正确：空了表示杯中已没有水，所以需要再倒水。", "满": "语义：“满了”说明杯子已装满，与“快倒点水吧”矛盾。", "瘦": "搭配：“瘦”形容人或动物的体形，不能用来形容杯子。", "破": "语义：“破了”说明杯子已经坏了、无法盛水，与“倒点水”矛盾。"}, "sentence_index": 0, "correct_answer": "空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个仓库的空很大，能堆很多货。", "explanation": "这里应该用〈空间〉，表示地方的大小；“空”单用不指空间。"}, {"text": "他对着空挥了挥手，像是在告别。", "explanation": "这里的“空”指天空、空中，是另一个义项（如“领空”“对空”），与“里面没有东西”无关。"}, {"text": "他空跑了一趟，什么也没办成。", "explanation": "这里的“空”是副词，表示白白地、徒劳地，是另一个义项，与“里面没有东西”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "空", "is_correct": true, "explanation": "正确：空（kōng，第一声）表示里面什么也没有。"}, {"text": "公", "is_correct": false, "explanation": "gōng 与 kōng 只差送气（g/k），意思是公共、公家。"}, {"text": "坑", "is_correct": false, "explanation": "kēng 与 kōng 韵母不同，意思是地上的洼洞。"}, {"text": "拱", "is_correct": false, "explanation": "gǒng（第三声）与 kōng 声母送气和声调都不同，意思是弯成弧形。"}], "explanations": {"空": "正确：空（kōng，第一声）表示里面什么也没有。", "公": "gōng 与 kōng 只差送气（g/k），意思是公共、公家。", "坑": "kēng 与 kōng 韵母不同，意思是地上的洼洞。", "拱": "gǒng（第三声）与 kōng 声母送气和声调都不同，意思是弯成弧形。"}, "sentence_index": null, "correct_answer": "空"}, "level_3": {"options": [{"text": "空", "is_correct": true, "explanation": "正确：空了表示碗里已没有饭，所以需要再盛。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“饱”用于人或动物吃饱，不能用来形容碗。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不能用来形容碗。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重了”说明碗里已装得沉，与“再给你盛一点”矛盾。"}], "explanations": {"空": "正确：空了表示碗里已没有饭，所以需要再盛。", "饱": "搭配：“饱”用于人或动物吃饱，不能用来形容碗。", "胖": "体貌：“胖”形容人或动物的体形，不能用来形容碗。", "重": "语义：“重了”说明碗里已装得沉，与“再给你盛一点”矛盾。"}, "sentence_index": 6, "correct_answer": "空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的建议空得很，句句都说到点子上。", "explanation": "这里的“空”表示没有内容，与“句句都说到点子上”矛盾；应用〈实〉表示有内容。"}, {"text": "这份报告他空改了一下午，最后还是白忙一场。", "explanation": "这里的“空”是副词，表示白白地、徒劳地（如“空跑”“空忙”），是另一个义项，与“里面没有东西”无关。"}, {"text": "他对空讲了好久，没有一个人听。", "explanation": "这里的“对空”指朝着空中、空气，是另一个义项，与“里面没有东西”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把冰箱空了，正好可以放新的。", "corrected_sentence": "妈妈把冰箱清空了，正好可以放新的。", "error_description": "错误：“把冰箱空了”缺少动词。“空”是形容词，在“把”字句中要和动词连用，应说“清空了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个纸箱是空，你可以拿去用。", "corrected_sentence": "那个纸箱是空的，你可以拿去用。", "error_description": "错误：“是空”缺少“的”。“是”后面作谓语的形容词要带“的”，应说“是空的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
