INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91985, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "字体是字写出来的样子。", "primary_collocate": null, "pronunciation": "zì tǐ", "ipa": "tsɨ˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的字体很工整，大家都很喜欢。", "target_word": "字体", "complexity_tier": "T3", "furigana": "tā de zì tǐ hěn gōng zhěng, dà jiā dōu hěn xǐ huan.", "sentence_source": "generated"}, {"text": "老师说写作业时字体要端正。", "target_word": "字体", "complexity_tier": "T3", "furigana": "lǎo shī shuō xiě zuò yè shí zì tǐ yào duān zhèng.", "sentence_source": "generated"}, {"text": "我的字体比以前整齐多了。", "target_word": "字体", "complexity_tier": "T3", "furigana": "wǒ de zì tǐ bǐ yǐ qián zhěng qí duō le.", "sentence_source": "generated"}, {"text": "他的字体又圆又可爱。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的字体很大，我一眼就能看清。", "target_word": "字体", "complexity_tier": "T3", "furigana": "nǎi nai de zì tǐ hěn dà, wǒ yì yǎn jiù néng kàn qīng.", "sentence_source": "generated"}, {"text": "这封信的字体有点潦草，我看不太清。", "target_word": "字体", "complexity_tier": "T3", "furigana": "zhè fēng xìn de zì tǐ yǒu diǎn liáo cǎo, wǒ kàn bú tài qīng.", "sentence_source": "generated"}, {"text": "他的字体写得越来越有力。", "target_word": "字体", "complexity_tier": "T3", "furigana": "tā de zì tǐ xiě de yuè lái yuè yǒu lì.", "sentence_source": "generated"}, {"text": "你的字体为什么这么漂亮？", "target_word": "字体", "complexity_tier": "T3", "furigana": "nǐ de zì tǐ wèi shén me zhè me piào liang?", "sentence_source": "generated"}, {"text": "他写的字体很特别，大家一看就认得。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐用钢笔写的字体很漂亮，连老师都夸她。", "target_word": "字体", "complexity_tier": "T3", "furigana": "jiě jie yòng gāng bǐ xiě de zì tǐ hěn piào liang, lián lǎo shī dōu kuā tā.", "sentence_source": "generated"}], "morphological_forms": [{"form": "字體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "字写出来的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5a5e0a7-1931-406f-8fa8-4b6b6a09a7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "搭配：“工整”说的是字迹、摆设等整齐，不能用来形容心情。"}, {"text": "字体", "is_correct": true, "explanation": "“字体”指字的写法样式，“工整”形容字写得整齐，这里搭配正确。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有“工整”的状态，“工整”说的是书写或摆放的整齐。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“工整”指书写或摆放整齐，不用来说人的脾气。"}], "explanations": {"心情": "搭配：“工整”说的是字迹、摆设等整齐，不能用来形容心情。", "字体": "“字体”指字的写法样式，“工整”形容字写得整齐，这里搭配正确。", "天气": "语义：天气没有“工整”的状态，“工整”说的是书写或摆放的整齐。", "脾气": "语义：“工整”指书写或摆放整齐，不用来说人的脾气。"}, "sentence_index": 0, "correct_answer": "字体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把字体放进了书包。", "explanation": "这里应该用〈作业本〉。作业本是东西，可以放进书包；字体指字写出来的样子，不能放进书包。"}, {"text": "纸上的字体已经干了。", "explanation": "这里应该用〈墨迹〉。墨迹是写在纸上的墨的痕迹，会干；字体指字的样式，不会干，不能说“干了”。"}, {"text": "他在信上留下了字体。", "explanation": "这里应该用〈笔迹〉。笔迹指一个人写字时留下的独特痕迹，可以用来辨认作者；字体指字的样式，不能被留下，也不能用来辨认人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "语义：“写得”要求写出来的字或文字作主语，“身材”不能被写。"}, {"text": "字体", "is_correct": true, "explanation": "“字体”是写出来的字的样子，“写得越来越有力”正是说字的笔力，搭配正确。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“写得”不能接“眼睛”，眼睛不是写出来的东西。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是用耳朵听的，不能被写出来，也谈不上写得有力。"}], "explanations": {"身材": "语义：“写得”要求写出来的字或文字作主语，“身材”不能被写。", "字体": "“字体”是写出来的字的样子，“写得越来越有力”正是说字的笔力，搭配正确。", "眼睛": "搭配：“写得”不能接“眼睛”，眼睛不是写出来的东西。", "声音": "语义：声音是用耳朵听的，不能被写出来，也谈不上写得有力。"}, "sentence_index": 6, "correct_answer": "字体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上留着字体。", "explanation": "这里应该用〈痕迹〉。痕迹是物体留下的印记，可以留在墙上；字体指字的样式，不是印记，不能留在墙上。"}, {"text": "他把字体倒进了砚台。", "explanation": "这里应该用〈墨汁〉。墨汁是可以倒的液体；字体指字的样式，不是液体，不能倒进砚台。"}, {"text": "他把字体装进了信封。", "explanation": "这里应该用〈信〉。字体是字的样式，不是东西，不能装进信封；装进信封的是信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥的字体比我的很工整。", "corrected_sentence": "我哥哥的字体比我的更工整。", "error_description": "比较句错误：“比”字句里形容词前不能用“很”，要用“更”或“还”，说“比我的更工整”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹的字体写很工整。", "corrected_sentence": "妹妹的字体写得很工整。", "error_description": "缺少“得”：评价字体写得怎么样，动词“写”后要加“得”，说“写得很工整”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
