INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文字的书写或印刷形体。", "primary_collocate": null, "pronunciation": "zì tǐ", "ipa": "tsɨ˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "宋体是常见的印刷字体。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上的字体一般比较小。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书法里有楷书、行书等不同的字体。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开文件后，我先把字体改成宋体。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社的书都用同样的字体。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师给这个网站选了新字体。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的字体和现在的很不一样。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种字体适合用在正式的信里。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学习了几种字体。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里有很多免费的字体可以下载。", "target_word": "字体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "字體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "文字的书写或印刷形体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5a5e0a7-1931-406f-8fa8-4b6b6a09a7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“宋体”是字的样式，不是颜色，“常见的印刷颜色”与句子主语不符。"}, {"text": "字体", "is_correct": true, "explanation": "“字体”指印刷的字形样式，宋体正是一种印刷字体。"}, {"text": "印刷机", "is_correct": false, "explanation": "语义：宋体是字的样式，不能是印刷机这样的机器。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“常见的印刷”后不能接“字数”这样的计数词，宋体也不是字数。"}], "explanations": {"颜色": "语义：“宋体”是字的样式，不是颜色，“常见的印刷颜色”与句子主语不符。", "字体": "“字体”指印刷的字形样式，宋体正是一种印刷字体。", "印刷机": "语义：宋体是字的样式，不能是印刷机这样的机器。", "字数": "搭配：“常见的印刷”后不能接“字数”这样的计数词，宋体也不是字数。"}, "sentence_index": 0, "correct_answer": "字体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的字体有三个段落。", "explanation": "这里应该用〈结构〉。字体是字的样式，不能说有几个段落；段落属于文章的结构。"}, {"text": "这篇作文规定的字体是八百字。", "explanation": "这里应该用〈字数〉。“八百字”是计算字数的说法；字体指字的形式，不能用字数来计量。"}, {"text": "他把字体涂在了纸上。", "explanation": "这里应该用〈颜料〉。颜料可以涂在纸上；字体指字的形式，不能涂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：古代没有电脑，“古代的电脑”不能与现在比较。"}, {"text": "字体", "is_correct": true, "explanation": "“字体”指文字的书写或印刷形体，古代与现在的字体确实不一样。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古代没有手机，无法拿“古代的手机”和现在的比较。"}, {"text": "高铁", "is_correct": false, "explanation": "搭配：“古代的”不能修饰“高铁”，这个组合在时代上说不通。"}], "explanations": {"电脑": "语义：古代没有电脑，“古代的电脑”不能与现在比较。", "字体": "“字体”指文字的书写或印刷形体，古代与现在的字体确实不一样。", "手机": "语义：古代没有手机，无法拿“古代的手机”和现在的比较。", "高铁": "搭配：“古代的”不能修饰“高铁”，这个组合在时代上说不通。"}, "sentence_index": 6, "correct_answer": "字体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画是他的得意字体。", "explanation": "这里应该用〈作品〉。字体指字的书写或印刷形式，不能指一幅画；“得意作品”才指他完成的作品。"}, {"text": "这支笔的字体用完了。", "explanation": "这里应该用〈墨水〉。墨水是可以用完的液体；字体指字的样式，不能用完。"}, {"text": "纸上留着字体。", "explanation": "这里应该用〈印迹〉。印迹是按压或印上去留下的痕迹；字体是字的样式，不能留在纸上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下载了一座字体。", "corrected_sentence": "我下载了一套字体。", "error_description": "量词用错：成套的“字体”应该用量词“套”，说“一套字体”；“座”用于山、桥、房屋等大型物体，不能用来数字体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚把电脑里的字体换了好。", "corrected_sentence": "我刚把电脑里的字体换好了。", "error_description": "补语位置用错：结果补语“好”应紧跟动词，说“换好了”，不能说“换了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
