INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对一件事的看法。", "primary_collocate": null, "pronunciation": "jiàn jiě", "ipa": "tɕjɛn˥˩ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "对这件事，你有什么见解？", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听听大家的见解。", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个问题提出了自己的见解。", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的见解都不一样。", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于搬家，我和妈妈的见解不同。", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请同学们说说对这个故事的见解。", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的见解让我想了很久。", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说一说对这个计划的见解。", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人对这件事有不同的见解。", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太同意你的见解。", "target_word": "见解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种见解", "label": "量词"}, {"form": "見解", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，对某件具体事情的看法，如“对这件事的见解”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91987, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见解", "is_correct": true, "explanation": "正确。这是听到的词，jiàn jiě，指对某件事的看法。"}, {"text": "间接", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是间接。"}, {"text": "讲解", "is_correct": false, "explanation": "jiǎng（第三声，韵母 -ang）与 jiàn（第四声，韵母 -an）韵母和声调都不同，意思是讲解。"}, {"text": "简介", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）、jiè（第四声）与 jiě（第三声）声调不同，意思是简介。"}, {"text": "建交", "is_correct": false, "explanation": "jiāo（第一声，韵母 -ao）与 jiě（第三声，韵母 -ie）韵母和声调都不同，意思是建立外交关系。"}], "explanations": {"见解": "正确。这是听到的词，jiàn jiě，指对某件事的看法。", "间接": "jiē（第一声）与 jiě（第三声）声调不同，意思是间接。", "讲解": "jiǎng（第三声，韵母 -ang）与 jiàn（第四声，韵母 -an）韵母和声调都不同，意思是讲解。", "简介": "jiǎn（第三声）与 jiàn（第四声）、jiè（第四声）与 jiě（第三声）声调不同，意思是简介。", "建交": "jiāo（第一声，韵母 -ao）与 jiě（第三声，韵母 -ie）韵母和声调都不同，意思是建立外交关系。"}, "sentence_index": null, "correct_answer": "见解"}, "level_3": {"options": [{"text": "见解", "is_correct": true, "explanation": "正确。见解指对事情的看法，“对这件事”与“你有什么见解”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指物体呈现的色彩，不能作对这件事的看法，句意不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用于对事情的看法。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址指住所或位置，与“对这件事”的问法无关。"}], "explanations": {"见解": "正确。见解指对事情的看法，“对这件事”与“你有什么见解”相合。", "颜色": "语义：颜色指物体呈现的色彩，不能作对这件事的看法，句意不通。", "身材": "体貌：身材指人的体形，不能用于对事情的看法。", "地址": "语义：地址指住所或位置，与“对这件事”的问法无关。"}, "sentence_index": 0, "correct_answer": "见解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这一行有十年的见解。", "explanation": "这里应该用〈经验〉。见解指对事物的看法，说在某一行积累的阅历要用“经验”。"}, {"text": "他提出了一把见解。", "explanation": "这里量词不对。见解是抽象名词，量词用“个”或“种”，“把”用于有柄的器物。"}, {"text": "他在会上做了一个见解。", "explanation": "这里应该用〈提出〉。见解要说“提出”或“有”，“做”不能和见解搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见解", "is_correct": true, "explanation": "正确。“见解”是人对事情的看法，能够“让我想了很久”。"}, {"text": "电量", "is_correct": false, "explanation": "语义：电量指电池储存的电能，与“让我想了很久”的思考义不合，句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，与“让我想了很久”的思考义不合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不能让人思考，句意不通。"}], "explanations": {"见解": "正确。“见解”是人对事情的看法，能够“让我想了很久”。", "电量": "语义：电量指电池储存的电能，与“让我想了很久”的思考义不合，句意不通。", "钥匙": "语义：钥匙是开锁的工具，与“让我想了很久”的思考义不合。", "书包": "语义：书包是装东西的袋子，不能让人思考，句意不通。"}, "sentence_index": 6, "correct_answer": "见解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个见解昨天下午三点发生了。", "explanation": "这里应该用〈事情〉。见解指对事物的看法，发生的事件要说“事情”，不能用“见解”。"}, {"text": "这碗面的见解很好吃。", "explanation": "这里是在形容食物的味道。见解指人对事情的看法，不能用来形容食物。"}, {"text": "他把这个见解打开了。", "explanation": "这里应该用〈提出〉。“打开”不能和见解搭配，应说“提出”或“有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对这个问题有一位新的见解。", "corrected_sentence": "她对这个问题有一个新的见解。", "error_description": "“见解”是抽象名词，不能用表示人的量词“位”，应说“一个新的见解”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把见解很有道理。", "corrected_sentence": "这个见解很有道理。", "error_description": "“把”用于有柄的器物，不能修饰抽象名词“见解”；应说“这个见解”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91991, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91991, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91991, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "安心是心里不怕，也不担心。", "primary_collocate": null, "pronunciation": "ān xīn", "ipa": "an˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "听到孩子到家了，妈妈才安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有你在身边，我很安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有警察，晚上睡觉很安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说没事，我就安心了。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把钱放在银行里，大家都觉得安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在家里，我出门也很安心。", "target_word": "安心", "complexity_tier": "T3", "furigana": "hái zi men zài jiā lǐ ， wǒ chū mén yě hěn ān xīn 。", "sentence_source": "generated"}, {"text": "手机有电，出门我才安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区有保安，住着安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话让我感到很安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们睡着了，她才安心地坐下来。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安安心心", "label": "重叠"}], "register": "中性", "sense_fingerprint": "心里不害怕、不担心，觉得踏实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担心", "is_correct": false, "explanation": "语义：“才担心”与“听到孩子到家了”后的放心情绪矛盾"}, {"text": "安心", "is_correct": true, "explanation": "正确：安心表示心里不担心、踏实，正合孩子到家后妈妈的心情"}, {"text": "紧张", "is_correct": false, "explanation": "语义：紧张表示心里不踏实，与孩子到家后的放心相反"}, {"text": "安全", "is_correct": false, "explanation": "搭配：安全多用于物或环境，不说“妈妈才安全”"}], "explanations": {"担心": "语义：“才担心”与“听到孩子到家了”后的放心情绪矛盾", "安心": "正确：安心表示心里不担心、踏实，正合孩子到家后妈妈的心情", "紧张": "语义：紧张表示心里不踏实，与孩子到家后的放心相反", "安全": "搭配：安全多用于物或环境，不说“妈妈才安全”"}, "sentence_index": 0, "correct_answer": "安心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过马路时要安心，看好红绿灯。", "explanation": "这里应该用〈小心〉。安心指心里不担心、踏实，提醒别人留神路况要用小心"}, {"text": "他一直很安心，不知道孩子会不会出事。", "explanation": "这里应该用〈担心〉。安心表示不担心，而这句话说的是为孩子的安危发愁，要用担心"}, {"text": "他走路很安心，一路上提心吊胆。", "explanation": "这里应该用〈紧张〉。安心表示心里不担心，与“提心吊胆”的忧惧矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焦虑", "is_correct": false, "explanation": "语义：焦虑是忧心不安，与“手机有电、出门才安心”的语境相反"}, {"text": "生气", "is_correct": false, "explanation": "语义：生气是恼怒，与此句表示的踏实心情不合"}, {"text": "寂寞", "is_correct": false, "explanation": "搭配：寂寞说的是孤单的感受，与“出门我才……”连用不通顺"}, {"text": "安心", "is_correct": true, "explanation": "正确：安心表示心里踏实，手机有电让出门的人不再担心，正合此处"}], "explanations": {"焦虑": "语义：焦虑是忧心不安，与“手机有电、出门才安心”的语境相反", "生气": "语义：生气是恼怒，与此句表示的踏实心情不合", "寂寞": "搭配：寂寞说的是孤单的感受，与“出门我才……”连用不通顺", "安心": "正确：安心表示心里踏实，手机有电让出门的人不再担心，正合此处"}, "sentence_index": 6, "correct_answer": "安心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他安心地跑出门，大声喊救命。", "explanation": "〈安心〉被误用为“镇定、从容”，但后半句“大声喊救命”是慌乱求助，与之矛盾。安心只表示心里不慌不怕，不能描写慌乱的举动"}, {"text": "他安心地在屋里转来转去，急得直跺脚。", "explanation": "〈安心〉表示心里不担心，而“急得直跺脚”是焦急的状态，二者矛盾"}, {"text": "他坐在考场里，安心得直发抖。", "explanation": "这里把〈安心〉理解成了“镇定、沉着”，但“直发抖”写的是极度紧张，与之矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她安心了地坐在沙发上。", "corrected_sentence": "她安心地坐在沙发上。", "error_description": "错误形式：“了”夹在“安心”和“地”之间。正确形式：“安心地坐在沙发上”，“了”不能放在状语“安心”之后", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他安心心地睡了一觉。", "corrected_sentence": "他安安心心地睡了一觉。", "error_description": "错误形式：“安心”的重叠形式错误，写成了“安心心”。正确形式：“安安心心”，重叠时要整体重叠为“安安心心”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91992, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
