INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91992, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心情安定，没有忧虑。", "primary_collocate": null, "pronunciation": "ān xīn", "ipa": "an˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "工作找到了，一家人都很安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在老家，每天过得很安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到账单都付完了，我才安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子装好了，我们安心地住了下来。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的情绪好了，睡得很安心。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每个月有退休金，晚年很安心。", "target_word": "安心", "complexity_tier": "T3", "furigana": "lǎo rén měi gè yuè yǒu tuì xiū jīn ， wǎn nián hěn ān xīn 。", "sentence_source": "generated"}, {"text": "她看到孩子已经回家，睡得特别安心。", "target_word": "安心", "complexity_tier": "T3", "furigana": "tā kàn dào hái zi yǐ jīng huí jiā ， shuì de tè bié ān xīn 。", "sentence_source": "generated"}, {"text": "事情说清楚了，你就安心吧。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了稳定的工作，他安心多了。", "target_word": "安心", "complexity_tier": "T3", "furigana": "yǒu le wěn dìng de gōng zuò ， tā ān xīn duō le 。", "sentence_source": "generated"}, {"text": "大雨过后，河水不再涨，大家安心了。", "target_word": "安心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安安心心", "label": "重叠"}], "register": "中性", "sense_fingerprint": "心情安定、没有忧虑，事情有着落后的踏实感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担心", "is_correct": false, "explanation": "语义：工作找到了，一家人应当放心，“都很担心”与此语境矛盾"}, {"text": "安心", "is_correct": true, "explanation": "正确：安心表示事情有着落后心里踏实，正合工作找到后的家人心情"}, {"text": "焦急", "is_correct": false, "explanation": "语义：焦急是着急等待，与工作已经找到的结果不符"}, {"text": "坚强", "is_correct": false, "explanation": "搭配：坚强形容意志，不用来说一家人的心情"}], "explanations": {"担心": "语义：工作找到了，一家人应当放心，“都很担心”与此语境矛盾", "安心": "正确：安心表示事情有着落后心里踏实，正合工作找到后的家人心情", "焦急": "语义：焦急是着急等待，与工作已经找到的结果不符", "坚强": "搭配：坚强形容意志，不用来说一家人的心情"}, "sentence_index": 0, "correct_answer": "安心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里走山路要安心，多带手电。", "explanation": "这里应该用〈小心〉。安心表示心情安定、没有忧虑，提醒别人留神路况要用小心"}, {"text": "她很安心，整夜都在为孩子的考试发愁。", "explanation": "这里应该用〈担忧〉。安心表示心情安定、没有忧虑，与整夜发愁的状态矛盾；为事情忧虑要用担忧"}, {"text": "他安心地一夜没合眼，满脑子都是账单。", "explanation": "这里应该用〈不安〉。安心表示没有忧虑，与“一夜没合眼、满脑子都是账单”的忧虑状态矛盾；心里忧虑、坐立不安要用不安"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警觉", "is_correct": false, "explanation": "语义：警觉表示提高戒备，与孩子已回家、睡得放心的语境不合"}, {"text": "惊慌", "is_correct": false, "explanation": "语义：惊慌是害怕慌乱，与“睡得特别……”的踏实语境相反"}, {"text": "暴躁", "is_correct": false, "explanation": "搭配：暴躁形容脾气，不说“睡得暴躁”"}, {"text": "安心", "is_correct": true, "explanation": "正确：安心表示没有忧虑，孩子已回家，正合她睡得踏实的情形"}], "explanations": {"警觉": "语义：警觉表示提高戒备，与孩子已回家、睡得放心的语境不合", "惊慌": "语义：惊慌是害怕慌乱，与“睡得特别……”的踏实语境相反", "暴躁": "搭配：暴躁形容脾气，不说“睡得暴躁”", "安心": "正确：安心表示没有忧虑，孩子已回家，正合她睡得踏实的情形"}, "sentence_index": 6, "correct_answer": "安心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他安心地拿起刀，心里却怕得要命。", "explanation": "〈安心〉被误用为“镇定、不慌”，但后半句说心里害怕，二者矛盾。安心表示心情安定、没有忧虑，不能与恐惧并存"}, {"text": "他安心地对着镜子发了一顿脾气。", "explanation": "这里把〈安心〉理解成了“平静、从容”，但安心表示心情安定、没有忧虑，与发脾气时的烦躁情绪不相容"}, {"text": "她在手术台上安心得直打哆嗦。", "explanation": "这里把〈安心〉理解成了“镇定、沉着”，但“直打哆嗦”是极度害怕的样子，与之矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一家人搬进新房子后，大家都很安心地。", "corrected_sentence": "一家人搬进新房子后，大家都很安心。", "error_description": "错误形式：句末多出“地”。“地”要连接状语与其后的动词，这里句子在“地”后就结束了。正确形式：“一家人搬进新房子后，大家都很安心。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家安心了地走出家门。", "corrected_sentence": "大家安心地走出家门。", "error_description": "错误形式：“了”夹在“安心”和“地”之间。正确形式：“安心地走出家门”，“了”不能放在状语“安心”之后", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
