INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91995, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听来是你听了以后，觉得像是这样。", "primary_collocate": null, "pronunciation": "tīng lái", "ipa": "tʰiŋ˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "这个主意听来不错。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话听来很有道理。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事听来有点儿奇怪。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌听来很熟悉，我好像听过。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的声音听来很累。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息听来令人振奋。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的故事听来十分感人。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的办法听来简单，做起来很难。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处的声音听来像是有人在唱歌。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划听来很好，可是没人相信。", "target_word": "听来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "听了之后觉得像是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02255d63-88e7-4cee-a6d4-c25bafea51c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91995, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听来", "is_correct": true, "explanation": "“听来”表示听后觉得像是这样。此句说听了这个主意的内容，觉得不错，符合句意。"}, {"text": "尝来", "is_correct": false, "explanation": "语义：“尝”指品尝味道，主意不能被品尝，与句中对主意的评价不相合。"}, {"text": "摸来", "is_correct": false, "explanation": "语义：“摸”指用手触摸，主意不能被触摸，句子无法成立。"}, {"text": "数来", "is_correct": false, "explanation": "搭配：“数”指计算数量，不用来评价主意好不好，与“不错”的评价搭配不当。"}], "explanations": {"听来": "“听来”表示听后觉得像是这样。此句说听了这个主意的内容，觉得不错，符合句意。", "尝来": "语义：“尝”指品尝味道，主意不能被品尝，与句中对主意的评价不相合。", "摸来": "语义：“摸”指用手触摸，主意不能被触摸，句子无法成立。", "数来": "搭配：“数”指计算数量，不用来评价主意好不好，与“不错”的评价搭配不当。"}, "sentence_index": 0, "correct_answer": "听来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在门外听来一阵敲门声。", "explanation": "这里应该用〈听见〉。听来表示听后的感受或判断，不用于直接听到声音。"}, {"text": "我们应该听来老师的安排。", "explanation": "这里应该用〈听从〉。听来表示听后的感受或判断；表示服从、照办应该用“听从”。"}, {"text": "从这些迹象听来，他明天会来。", "explanation": "这里应该用〈看来〉。判断的依据是迹象，属于看到的情况；听来要求判断的依据是听到的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91995, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听来", "is_correct": true, "explanation": "“听来”表示听后觉得像是这样。此句说听了老人的故事，觉得十分感人，符合句意。"}, {"text": "嗅来", "is_correct": false, "explanation": "语义：“嗅”指用鼻子闻，故事不能被闻到，与句意不相合。"}, {"text": "量来", "is_correct": false, "explanation": "搭配：“量”指测量，不用来说故事感人的程度，与“十分感人”搭配不当。"}, {"text": "触来", "is_correct": false, "explanation": "语义：“触”指接触、碰到，故事不能被触碰，句子无法成立。"}], "explanations": {"听来": "“听来”表示听后觉得像是这样。此句说听了老人的故事，觉得十分感人，符合句意。", "嗅来": "语义：“嗅”指用鼻子闻，故事不能被闻到，与句意不相合。", "量来": "搭配：“量”指测量，不用来说故事感人的程度，与“十分感人”搭配不当。", "触来": "语义：“触”指接触、碰到，故事不能被触碰，句子无法成立。"}, "sentence_index": 6, "correct_answer": "听来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我听来他下周要结婚。", "explanation": "这里应该用〈听说〉。听来用于对所听内容作出感受或判断，不用于转述消息。"}, {"text": "我们要认真听来大家的意见。", "explanation": "这里应该用〈听取〉。听来不表示征求并接受意见。"}, {"text": "他没听来我的声音。", "explanation": "这里应该用〈听到〉。听来表示听后的判断，不表示直接听见声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案听来了很合理，值得一试。", "corrected_sentence": "这个方案听来很合理，值得一试。", "error_description": "错误：“听来”后不能加“了”，破坏了这个词的结构。正确：“听来很合理”，不说“听来了很合理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法听来的不错，我们试试吧。", "corrected_sentence": "这个办法听来不错，我们试试吧。", "error_description": "错误：“听来”作谓语、后接形容词时，形容词前不能加“的”。正确：“听来不错”，不说“听来的不错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
