INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91997, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "官兵是军队里的官和兵。", "primary_collocate": null, "pronunciation": "guān bīng", "ipa": "kwan˥ pɪŋ˥", "syllable_count": 2, "sentences": [{"text": "部队的官兵正在操场上训练。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全体官兵都参加了这次活动。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，官兵们也想念家人。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支队伍有两百多名官兵。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官兵们吃过饭就出发了。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民给官兵送去了水果。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官兵们在雨中站了一个小时。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和官兵一起住在山上。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些官兵来自不同的地方。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导看望了边防官兵。", "target_word": "官兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "官兵：军队里的军官和士兵这些人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a326b33e-2943-4e82-b30a-8c790c137e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91997, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游客", "is_correct": false, "explanation": "语义：游客是外出旅游的人，不属于部队，与“部队的”句意相矛盾。"}, {"text": "官兵", "is_correct": true, "explanation": "官兵指军队里的军官和士兵，“部队的官兵正在操场上训练”符合句意。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“训练”的主体应是受训的人员，“乘客”不能与“训练”搭配。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民是从事农业生产的人，不在部队之中，与“部队的”不符。"}], "explanations": {"游客": "语义：游客是外出旅游的人，不属于部队，与“部队的”句意相矛盾。", "官兵": "官兵指军队里的军官和士兵，“部队的官兵正在操场上训练”符合句意。", "乘客": "搭配：“训练”的主体应是受训的人员，“乘客”不能与“训练”搭配。", "农民": "语义：农民是从事农业生产的人，不在部队之中，与“部队的”不符。"}, "sentence_index": 0, "correct_answer": "官兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂里有五百名官兵。", "explanation": "这里应该用〈工人〉。官兵指军队中的军官和士兵，工厂里的生产人员应说“工人”。"}, {"text": "这个市场里的官兵都在讨价还价。", "explanation": "这里应该用〈顾客〉。官兵指军人，不指在市场里买东西的人，应说“顾客”。"}, {"text": "这家超市有三百多名官兵。", "explanation": "这里应该用〈售货员〉。官兵指军队中的人员，超市里负责卖货的人应说“售货员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91997, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "官兵", "is_correct": true, "explanation": "“官兵们在雨中站了一个小时”中，“官兵”指军人，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“们”只用于指人，“桌子”不能加“们”，也不能站在雨中。"}, {"text": "空气", "is_correct": false, "explanation": "语法：“空气”是物质名词，不能加“们”，也不能站在雨中。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“们”只用于指人，“书包”是物品，不能加“们”，也不能站在雨中。"}], "explanations": {"官兵": "“官兵们在雨中站了一个小时”中，“官兵”指军人，符合句意。", "桌子": "搭配：“们”只用于指人，“桌子”不能加“们”，也不能站在雨中。", "空气": "语法：“空气”是物质名词，不能加“们”，也不能站在雨中。", "书包": "搭配：“们”只用于指人，“书包”是物品，不能加“们”，也不能站在雨中。"}, "sentence_index": 6, "correct_answer": "官兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "幼儿园里的官兵都在唱歌。", "explanation": "这里应该用〈小朋友〉。官兵指军队中的军官和士兵，幼儿园里的孩子应说“小朋友”。"}, {"text": "这家电影院有三百多名官兵。", "explanation": "这里应该用〈观众〉。官兵指军人，电影院里看电影的人应说“观众”。"}, {"text": "这家饭店里的官兵很热情。", "explanation": "这里应该用〈服务员〉。官兵指军队中的人员，饭店里招待客人的人应说“服务员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们连有三只官兵。", "corrected_sentence": "我们连有三名官兵。", "error_description": "错误在量词：“只”用于动物或小件物品，指人应用“名”。正确说法是“三名官兵”，不能说“三只官兵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个营有两百台官兵。", "corrected_sentence": "这个营有两百名官兵。", "error_description": "错误在量词：“台”用于机器等物品，指人应用“名”，应说“两百名官兵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
