INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91999, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个词放在一起用。", "primary_collocate": null, "pronunciation": "lián yòng", "ipa": "ljɛn˧˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这两个词可以连用。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“的”和“地”一般不能连用。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个“很”连用，意思更重。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这两个量词不能连用。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“太”和“了”常常连用。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个字连用时，读音会变。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语里，“又”和“再”能不能连用？", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说，这两个副词可以连用。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词连用，听起来很怪。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看看哪些助词可以连用。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连用了", "label": "体标"}], "register": "中性", "sense_fingerprint": "连用：语法上两个词或字紧挨着一起使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dde39b2-d898-475e-ae86-85b21cca451a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连用", "is_correct": true, "explanation": "正确：“连用”表示两个词紧挨着一起用，与“可以”搭配。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”的主体是人，不能说“词”唱歌。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”指身体运动，与词语的使用无关。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”指休息，与词语的使用无关。"}], "explanations": {"连用": "正确：“连用”表示两个词紧挨着一起用，与“可以”搭配。", "唱歌": "搭配：“唱歌”的主体是人，不能说“词”唱歌。", "跑步": "语义：“跑步”指身体运动，与词语的使用无关。", "睡觉": "语义：“睡觉”指休息，与词语的使用无关。"}, "sentence_index": 0, "correct_answer": "连用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑连用了一整天，屏幕都发烫了。", "explanation": "这里的“连用”取“连续使用”义，与本词“两个词放在一起用”不同。"}, {"text": "这种药不能连用三天以上。", "explanation": "这里的“连用”指连续使用，是另一个义项，与本词“两个词放在一起用”不同。"}, {"text": "这台空调连用了一个星期。", "explanation": "这里的“连用”指连续使用，是另一个义项，与本词“两个词放在一起用”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连用", "is_correct": true, "explanation": "正确：“连用”是词语紧挨着使用，与“能不能”搭配。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”指舞蹈动作，与副词的语法用法无关。"}, {"text": "开门", "is_correct": false, "explanation": "搭配：“开门”的宾语应是门，不能说“又”和“再”开门。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物生长，与副词的用法无关。"}], "explanations": {"连用": "正确：“连用”是词语紧挨着使用，与“能不能”搭配。", "跳舞": "语义：“跳舞”指舞蹈动作，与副词的语法用法无关。", "开门": "搭配：“开门”的宾语应是门，不能说“又”和“再”开门。", "发芽": "语义：“发芽”指植物生长，与副词的用法无关。"}, "sentence_index": 6, "correct_answer": "连用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个药最多连用五天。", "explanation": "这里的“连用”指连续使用，是另一个义项，与本词“两个词放在一起用”不同。"}, {"text": "这盏灯连用了整个晚上。", "explanation": "这里的“连用”取“连续使用”义，与本词“两个词放在一起用”不同。"}, {"text": "这支笔他连用了三年。", "explanation": "这里的“连用”指连续使用，是另一个义项，与本词“两个词放在一起用”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“就”和“才”一般不能的连用。", "corrected_sentence": "“就”和“才”一般不能连用。", "error_description": "错误形式：“不能的连用”。正确形式：“不能连用”。原因：“的”不能插在助动词“不能”和动词“连用”之间，多出的“的”使动词短语变成名词性结构，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个字能不能把连用？", "corrected_sentence": "这两个字能不能连用？", "error_description": "错误形式：“能不能把连用”。正确形式：“能不能连用”。原因：“连用”是不及物的词语搭配，不能用“把”字引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
