INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92001, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "在两件事之间，表示不选前一件而选后一件，常与“不如”呼应。", "primary_collocate": null, "pronunciation": "yǔ qí", "ipa": "y˨˩˦ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "与其坐车，不如走路去。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其在家看电视，不如出去玩。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其等他，不如自己去。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其睡懒觉，不如早起跑步。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其买新的，不如修旧的。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其一个人去，不如跟朋友一起去。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其说他聪明，不如说他努力。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其抱怨天气，不如带把伞。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其吃快餐，不如自己做饭。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其今天做，不如明天再做。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "与其说", "label": "复合"}], "register": "中性", "sense_fingerprint": "在两件事中不愿选前一件，常接不如", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e0a565-ff65-4751-a7de-98805f80eb54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92001, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "与其", "is_correct": true, "explanation": "正确答案。与其 yǔ qí（第三声、第二声）是本词，意思是在两件事中舍弃前者、选取后者。"}, {"text": "语气", "is_correct": false, "explanation": "语气 yǔ qì：第二音节 qí（第二声）与 qì（第四声）声调不同，意思是说话的口气。"}, {"text": "预期", "is_correct": false, "explanation": "预期 yù qī：两个音节的声调都与“与其”不同（yù 第四声，qī 第一声），意思是事先的期望。"}, {"text": "玉器", "is_correct": false, "explanation": "玉器 yù qì：两个音节的声调都与“与其”不同，意思是玉制的器物。"}, {"text": "雨期", "is_correct": false, "explanation": "雨期 yǔ qī：第二音节 qí（第二声）与 qī（第一声）声调不同，意思是下雨的时期。"}], "explanations": {"与其": "正确答案。与其 yǔ qí（第三声、第二声）是本词，意思是在两件事中舍弃前者、选取后者。", "语气": "语气 yǔ qì：第二音节 qí（第二声）与 qì（第四声）声调不同，意思是说话的口气。", "预期": "预期 yù qī：两个音节的声调都与“与其”不同（yù 第四声，qī 第一声），意思是事先的期望。", "玉器": "玉器 yù qì：两个音节的声调都与“与其”不同，意思是玉制的器物。", "雨期": "雨期 yǔ qī：第二音节 qí（第二声）与 qī（第一声）声调不同，意思是下雨的时期。"}, "sentence_index": null, "correct_answer": "与其"}, "level_3": {"options": [{"text": "与其", "is_correct": true, "explanation": "正确。“与其……不如……”表示舍弃前者、选取后者，与句中的“不如”呼应。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”表示递进，要接同方向的补充，不能与“不如”的取舍配合。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后相继，句中并无先后动作，不能与“不如”的取舍比较呼应。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，前面没有原因，整句读不通。"}], "explanations": {"与其": "正确。“与其……不如……”表示舍弃前者、选取后者，与句中的“不如”呼应。", "而且": "搭配：“而且”表示递进，要接同方向的补充，不能与“不如”的取舍配合。", "然后": "语义：“然后”表示先后相继，句中并无先后动作，不能与“不如”的取舍比较呼应。", "所以": "语义：“所以”表示结果，前面没有原因，整句读不通。"}, "sentence_index": 0, "correct_answer": "与其"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你想喝茶与其喝咖啡？", "explanation": "这里应该用〈还是〉。询问二选一要用“还是”；“与其”要与“不如”呼应，表示舍前取后，不能用于问句。"}, {"text": "他不是老师，与其是医生。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示否定后的更正；“与其”要与“不如”呼应，不能这样用。"}, {"text": "与其明天下雨，我们就不去了。", "explanation": "这里应该用〈如果〉。表示假设条件要用“如果……就……”；“与其”表示取舍，需与“不如”呼应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "与其", "is_correct": true, "explanation": "正确。“与其说……不如说……”是固定格式，表示舍弃前者、选取后者，与句中的“不如说”呼应。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”表示并列递进，不与“不如说”的取舍呼应。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”引出条件，与后面的比较不构成取舍。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”要与“也”呼应，这里没有“也”，句子不通。"}], "explanations": {"与其": "正确。“与其说……不如说……”是固定格式，表示舍弃前者、选取后者，与句中的“不如说”呼应。", "并且": "搭配：“并且”表示并列递进，不与“不如说”的取舍呼应。", "只要": "语义：“只要”引出条件，与后面的比较不构成取舍。", "即使": "搭配：“即使”要与“也”呼应，这里没有“也”，句子不通。"}, "sentence_index": 6, "correct_answer": "与其"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅环境好，与其菜也好吃。", "explanation": "这里应该用〈而且〉。表示递进补充要用“而且”；“与其”表示取舍，需与“不如”呼应。"}, {"text": "与其天气很冷，大家还是很高兴。", "explanation": "这里应该用〈虽然〉。表示让步要用“虽然……还是……”；“与其”表示取舍，不能这样用。"}, {"text": "与其下雨了，比赛取消了。", "explanation": "这里应该用〈因为〉。表示原因要用“因为”；“与其”表示取舍，需与“不如”呼应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "与其在家等，而是去超市买。", "corrected_sentence": "与其在家等，不如去超市买。", "error_description": "错误：“与其”后面应与“不如”呼应，这里误用了“而是”。正确：“与其在家等，不如去超市买。”“而是”表示否定后的转折，不能与“与其”搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "与其在网上买，去店里看看。", "corrected_sentence": "与其在网上买，不如去店里看看。", "error_description": "错误：“与其”要与“不如”呼应，这里漏掉了“不如”，应补上。正确：“与其在网上买，不如去店里看看。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
