INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92002, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，用于比较两种做法，表示舍弃前者而选取后者，常与“不如”“宁可”搭配。", "primary_collocate": null, "pronunciation": "yǔ qí", "ipa": "y˨˩˦ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "与其浪费时间，宁可早点睡觉。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其花钱买贵的，宁可买便宜的。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其相信他，我宁可相信自己。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其住在城里，不如住在海边。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其玩手机，不如多读几本书。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其迟到，宁可坐出租车去。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其让孩子哭，不如先抱抱他。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其说话不算数，不如不答应。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其做得不好，不如不做。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其看着别人忙，不如过去帮忙。", "target_word": "与其", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "与其说", "label": "复合"}], "register": "中性", "sense_fingerprint": "比较两种做法，舍前者取后者，与不如、宁可呼应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e0a565-ff65-4751-a7de-98805f80eb54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "与其", "is_correct": true, "explanation": "正确答案。与其 yǔ qí（第三声、第二声）是本词，意思是在两种做法中舍弃前者、选取后者。"}, {"text": "语气", "is_correct": false, "explanation": "语气 yǔ qì：第二音节 qí（第二声）与 qì（第四声）声调不同，意思是说话的口气。"}, {"text": "预期", "is_correct": false, "explanation": "预期 yù qī：两个音节的声调都与“与其”不同（yù 第四声，qī 第一声），意思是事先的期望。"}, {"text": "玉器", "is_correct": false, "explanation": "玉器 yù qì：两个音节的声调都与“与其”不同，意思是玉制的器物。"}, {"text": "雨期", "is_correct": false, "explanation": "雨期 yǔ qī：第二音节 qí（第二声）与 qī（第一声）声调不同，意思是下雨的时期。"}], "explanations": {"与其": "正确答案。与其 yǔ qí（第三声、第二声）是本词，意思是在两种做法中舍弃前者、选取后者。", "语气": "语气 yǔ qì：第二音节 qí（第二声）与 qì（第四声）声调不同，意思是说话的口气。", "预期": "预期 yù qī：两个音节的声调都与“与其”不同（yù 第四声，qī 第一声），意思是事先的期望。", "玉器": "玉器 yù qì：两个音节的声调都与“与其”不同，意思是玉制的器物。", "雨期": "雨期 yǔ qī：第二音节 qí（第二声）与 qī（第一声）声调不同，意思是下雨的时期。"}, "sentence_index": null, "correct_answer": "与其"}, "level_3": {"options": [{"text": "与其", "is_correct": true, "explanation": "正确。“与其……宁可……”表示舍前取后，与句中的“宁可”呼应。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”表示递进，不能与“宁可”的取舍呼应。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前后句之间并没有相互对立的两种做法。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，前面没有原因，整句读不通。"}], "explanations": {"与其": "正确。“与其……宁可……”表示舍前取后，与句中的“宁可”呼应。", "而且": "搭配：“而且”表示递进，不能与“宁可”的取舍呼应。", "但是": "语义：“但是”表示转折，前后句之间并没有相互对立的两种做法。", "所以": "语义：“所以”表示结果，前面没有原因，整句读不通。"}, "sentence_index": 0, "correct_answer": "与其"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你去北京与其去上海？", "explanation": "这里应该用〈还是〉。询问二选一要用“还是”；“与其”表示舍前取后，需与“不如”“宁可”呼应。"}, {"text": "他不是学生，与其是老师。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示否定后的更正；“与其”不能这样用。"}, {"text": "与其明天不下雨，我们就去爬山。", "explanation": "这里应该用〈如果〉。表示假设条件要用“如果……就……”；“与其”表示取舍，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "与其", "is_correct": true, "explanation": "正确。“与其……不如……”表示舍前取后，与句中的“不如”呼应。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后相继，句中并无先后动作，不能与“不如”的取舍比较呼应。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”引出条件，与后面的取舍比较不相干。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”表示并列，不与“不如”的取舍呼应。"}], "explanations": {"与其": "正确。“与其……不如……”表示舍前取后，与句中的“不如”呼应。", "然后": "语义：“然后”表示先后相继，句中并无先后动作，不能与“不如”的取舍比较呼应。", "只要": "语义：“只要”引出条件，与后面的取舍比较不相干。", "并且": "搭配：“并且”表示并列，不与“不如”的取舍呼应。"}, "sentence_index": 6, "correct_answer": "与其"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的菜很好吃，与其很便宜。", "explanation": "这里应该用〈而且〉。表示递进补充要用“而且”；“与其”表示取舍，需与“不如”呼应。"}, {"text": "与其他很累，却还在坚持。", "explanation": "这里应该用〈虽然〉。表示让步要用“虽然”；“与其”表示取舍，不能这样用。"}, {"text": "与其路上堵车，他迟到了。", "explanation": "这里应该用〈因为〉。表示原因要用“因为”；“与其”表示取舍，需与“不如”呼应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "与其在家休息，而是去公园散步。", "corrected_sentence": "与其在家休息，不如去公园散步。", "error_description": "错误：“与其”后面应与“不如”呼应，这里误用了“而是”。正确：“不如”。“而是”表示否定后的转折，不能与“与其”搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "与其整天玩游戏，多去运动。", "corrected_sentence": "与其整天玩游戏，不如多去运动。", "error_description": "错误：“与其”与“不如”要成对呼应，这里漏掉了“不如”。正确：“与其整天玩游戏，不如多去运动。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
