INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92003, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "客户端是你手机上用来上网做事的软件。", "primary_collocate": null, "pronunciation": "kè hù duān", "ipa": "kʰɤ⁵¹ xu⁵¹ twan⁵⁵", "syllable_count": 3, "sentences": [{"text": "我手机里有一个购物客户端。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先下载这个客户端，再注册。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个客户端可以用来看新闻。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没有空间了，装不下新客户端。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用聊天客户端和我视频。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天都用客户端看电影。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把客户端更新到最新版本。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个客户端太卡了，我想删掉它。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打车客户端上可以看到司机的位置。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用银行客户端给朋友转了钱。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个客户端", "label": "量词"}, {"form": "手机客户端", "label": "复合"}], "register": "口语", "sense_fingerprint": "手机上用来上网办事的软件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客户端", "is_correct": true, "explanation": "正确：购物客户端是手机上用来购物的应用软件，句子说的正是这个意思。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是手机里的应用，手机里也装不下一个花园。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以在手机上使用的软件，句子说的是手机应用。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能装在手机里，也不是应用软件。"}], "explanations": {"客户端": "正确：购物客户端是手机上用来购物的应用软件，句子说的正是这个意思。", "花园": "语义：花园不是手机里的应用，手机里也装不下一个花园。", "冰箱": "语义：冰箱不是可以在手机上使用的软件，句子说的是手机应用。", "沙发": "语义：沙发是家具，不能装在手机里，也不是应用软件。"}, "sentence_index": 0, "correct_answer": "客户端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市今天来了很多客户端。", "explanation": "这里应该用〈顾客〉。客户端指软件，不指进店的人。"}, {"text": "我每天晚上在客户端上洗澡。", "explanation": "这里应该用〈浴室〉。客户端是手机上的软件，不是可以洗澡的地方。"}, {"text": "我的爸爸是一位很好的客户端。", "explanation": "这里应该用〈客户〉。客户端指手机上的软件，不指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客户端", "is_correct": true, "explanation": "正确：句子要的是一个能用来更新的应用软件，客户端就是手机上用来上网办事的软件。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有版本，不能更新到最新版本。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是软件，没有版本可以更新。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“更新到最新版本”只能用于软件或系统，不搭配“早餐”。"}], "explanations": {"客户端": "正确：句子要的是一个能用来更新的应用软件，客户端就是手机上用来上网办事的软件。", "石头": "语义：石头没有版本，不能更新到最新版本。", "窗帘": "语义：窗帘不是软件，没有版本可以更新。", "早餐": "搭配：“更新到最新版本”只能用于软件或系统，不搭配“早餐”。"}, "sentence_index": 6, "correct_answer": "客户端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个景区每天有很多客户端。", "explanation": "这里应该用〈游客〉。客户端指软件，不指游览的人。"}, {"text": "这个客户端写了很多书。", "explanation": "这里应该用〈作家〉。客户端是软件，不能写书，写书的是作家。"}, {"text": "医院里有很多客户端。", "explanation": "这里应该用〈病人〉。客户端指软件，不指看病的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天下载了一只购物客户端。", "corrected_sentence": "我昨天下载了一个购物客户端。", "error_description": "量词错误：“购物客户端”是应用软件，应该用量词“个”，“只”一般用于动物，不能用于软件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把客户端更新新版本。", "corrected_sentence": "请把客户端更新到新版本。", "error_description": "漏掉“到”：“更新”后要用“到”引出更新的结果，应说“更新到新版本”，不能说“更新新版本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
