INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "计算机网络中与服务器相对、直接面向用户的程序或设备。", "primary_collocate": null, "pronunciation": "kè hù duān", "ipa": "kʰɤ⁵¹ xu⁵¹ twan⁵⁵", "syllable_count": 3, "sentences": [{"text": "客户端向服务器发送了一个请求。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务器收到客户端的请求后，马上回复。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户端和服务器之间要先连接网络。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个客户端不能连接到服务器。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户在客户端输入密码，再点登录。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的客户端需要每个月更新一次。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务器出了问题，客户端打不开网页。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序员正在修改客户端的界面。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户端把数据传给服务器保存起来。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务器很稳定，但客户端经常出错。", "target_word": "客户端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "客户端软件", "label": "复合"}], "register": "书面", "sense_fingerprint": "网络中与服务器相对、面向用户的程序或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客户端", "is_correct": true, "explanation": "正确：客户端是发出请求的一方，与服务器相对，所以它能向服务器发送请求。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是网络中的程序或设备，不能发送请求。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是能发送请求的程序或设备，句子说的是网络中的程序或设备。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是网络中的程序或设备，不能发送请求。"}], "explanations": {"客户端": "正确：客户端是发出请求的一方，与服务器相对，所以它能向服务器发送请求。", "石头": "语义：石头不是网络中的程序或设备，不能发送请求。", "书包": "语义：书包不是能发送请求的程序或设备，句子说的是网络中的程序或设备。", "花园": "语义：花园不是网络中的程序或设备，不能发送请求。"}, "sentence_index": 0, "correct_answer": "客户端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店每天有很多客户端来买东西。", "explanation": "这里应该用〈客户〉。客户端指软件或设备，不指消费的人，表示顾客要用“客户”。"}, {"text": "这个景区每天有很多客户端。", "explanation": "这里应该用〈游客〉。客户端指软件或设备，不指游览的人。"}, {"text": "我的爸爸是一位很好的客户端。", "explanation": "客户端指软件或设备，不指人。这里把它用来指人，是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客户端", "is_correct": true, "explanation": "正确：客户端负责打开网页，服务器出问题时它才打不开网页。"}, {"text": "键盘", "is_correct": false, "explanation": "语义：键盘不能打开网页，句子说的是能上网的程序或设备。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能打开网页，这里的主语应是能上网的程序或设备。"}, {"text": "页面", "is_correct": false, "explanation": "搭配：“页面”本身就是网页内容，不能作为打开网页的主体，不搭配。"}], "explanations": {"客户端": "正确：客户端负责打开网页，服务器出问题时它才打不开网页。", "键盘": "语义：键盘不能打开网页，句子说的是能上网的程序或设备。", "冰箱": "语义：冰箱不能打开网页，这里的主语应是能上网的程序或设备。", "页面": "搭配：“页面”本身就是网页内容，不能作为打开网页的主体，不搭配。"}, "sentence_index": 6, "correct_answer": "客户端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆公交车上坐满了客户端。", "explanation": "这里应该用〈乘客〉。客户端指软件或设备，不指乘车的人。"}, {"text": "这个客户端每天要浇很多花。", "explanation": "这里应该用〈园丁〉。客户端指软件或设备，不是浇花的人。"}, {"text": "医院里来了很多客户端。", "explanation": "这里应该用〈病人〉。客户端指软件或设备，不指来医院看病的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天下载了一只客户端。", "corrected_sentence": "我今天下载了一个客户端。", "error_description": "量词错误：“客户端”是软件，应该用量词“个”，“只”一般用于动物，不能用于软件。正确说法是“下载了一个客户端”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我手机里装了三本客户端。", "corrected_sentence": "我手机里装了三个客户端。", "error_description": "量词错误：“客户端”是软件，量词用“个”；“本”用于书、本子等，不能用来数“客户端”。应说“三个客户端”，不能说“三本客户端”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
