INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92005, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92005, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "舞蹈是跟着音乐，用身体做出好看的动作。", "primary_collocate": null, "pronunciation": "wǔ dǎo", "ipa": "u²¹⁴ tɑʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "音乐一响，她开始了舞蹈。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的舞蹈很好看。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起学了一个新舞蹈。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个舞蹈的音乐很快。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了一场很美的舞蹈。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩在台上跳了一段舞蹈。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个舞蹈很简单，你也能学会。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年晚会上有两个舞蹈。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的舞蹈动作又轻又美。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶也想学广场上的舞蹈。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段舞蹈", "label": "量词（段）"}, {"form": "舞蹈家", "label": "复合词"}, {"form": "舞蹈演员", "label": "复合词"}], "register": "中性", "sense_fingerprint": "跟着音乐跳的一支具体的舞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92005, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "舞蹈", "is_correct": true, "explanation": "wǔ dǎo 是正确答案，指跟着音乐做的一支具体的舞。"}, {"text": "武打", "is_correct": false, "explanation": "dǎ（第三声）与 dǎo（第三声）韵母不同，dǎ 没有 -o，意思是武打场面。"}, {"text": "武道", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，意思是武术之道。"}, {"text": "舞刀", "is_correct": false, "explanation": "dāo（第一声）与 dǎo（第三声）声调不同，意思是挥舞刀具。"}, {"text": "辅导", "is_correct": false, "explanation": "fǔ 与 wǔ 声母不同（f 与 w），意思是辅导、指导。"}], "explanations": {"舞蹈": "wǔ dǎo 是正确答案，指跟着音乐做的一支具体的舞。", "武打": "dǎ（第三声）与 dǎo（第三声）韵母不同，dǎ 没有 -o，意思是武打场面。", "武道": "dào（第四声）与 dǎo（第三声）声调不同，意思是武术之道。", "舞刀": "dāo（第一声）与 dǎo（第三声）声调不同，意思是挥舞刀具。", "辅导": "fǔ 与 wǔ 声母不同（f 与 w），意思是辅导、指导。"}, "sentence_index": null, "correct_answer": "舞蹈"}, "level_3": {"options": [{"text": "舞蹈", "is_correct": true, "explanation": "舞蹈是“开始了”的对象，与“音乐一响”的情境吻合。"}, {"text": "手术", "is_correct": false, "explanation": "语义：听到音乐不会开始手术，与前文情境冲突。"}, {"text": "辩论", "is_correct": false, "explanation": "语义：音乐一响不会引出辩论，与前文情境矛盾。"}, {"text": "病毒", "is_correct": false, "explanation": "搭配：“开始了”后面接的应是活动，病毒不能被“开始”。"}], "explanations": {"舞蹈": "舞蹈是“开始了”的对象，与“音乐一响”的情境吻合。", "手术": "语义：听到音乐不会开始手术，与前文情境冲突。", "辩论": "语义：音乐一响不会引出辩论，与前文情境矛盾。", "病毒": "搭配：“开始了”后面接的应是活动，病毒不能被“开始”。"}, "sentence_index": 0, "correct_answer": "舞蹈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她跳了一座舞蹈，大家都很喜欢。", "explanation": "这里应该用〈段〉。座用于建筑、山等大型固定物，一段舞蹈应说“段”。"}, {"text": "她唱了一段舞蹈，老师很满意。", "explanation": "这里应该用〈歌〉。唱的宾语是歌曲，舞蹈要与“跳”搭配。"}, {"text": "这段舞蹈很好听，我很喜欢。", "explanation": "这里应该用〈音乐〉。“好听”形容声音，音乐才能说好听；舞蹈是用来看的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舞蹈", "is_correct": true, "explanation": "舞蹈可以学会，符合“很简单，你也能学会”的语境。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是可以学会的东西，句意不通。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：宇宙无法被学会，与“你也能学会”矛盾。"}, {"text": "垃圾", "is_correct": false, "explanation": "搭配：“学会”的对象是技能或动作，垃圾不能被学会。"}], "explanations": {"舞蹈": "舞蹈可以学会，符合“很简单，你也能学会”的语境。", "大海": "语义：大海不是可以学会的东西，句意不通。", "宇宙": "语义：宇宙无法被学会，与“你也能学会”矛盾。", "垃圾": "搭配：“学会”的对象是技能或动作，垃圾不能被学会。"}, "sentence_index": 6, "correct_answer": "舞蹈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶每天都打舞蹈。", "explanation": "这里应该用〈太极〉。打用于拳术、球类，舞蹈是跟着音乐做的动作，应说“练舞蹈”。"}, {"text": "奶奶站在舞蹈上，等着表演。", "explanation": "这里应该用〈舞台〉。舞蹈是表演活动，不能作场所，“站在……上”要用地点词。"}, {"text": "奶奶是一个很棒的舞蹈，大家都喜欢她。", "explanation": "这里应该用〈舞蹈家〉。舞蹈是跳的舞本身，不能指跳舞的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她跳了一只舞蹈，大家都很喜欢。", "corrected_sentence": "她跳了一段舞蹈，大家都很喜欢。", "error_description": "量词错误：“只”用于动物及单个小物件，一段舞蹈应用量词“段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她小时候学了过舞蹈。", "corrected_sentence": "她小时候学过舞蹈。", "error_description": "体标错误：“了”与“过”不能同时使用。“过”已表示曾经的经历，应删去“了”，应说“学过舞蹈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
