INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以有节奏的身体动作为主要手段，表现情感和生活的艺术形式。", "primary_collocate": null, "pronunciation": "wǔ dǎo", "ipa": "u²¹⁴ tɑʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "她从小就喜欢舞蹈。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的民族舞蹈很有名。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种舞蹈表现了春天的快乐。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学习现代舞蹈。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈是一种用身体表达感情的艺术。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每周都去学舞蹈。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得舞蹈能表达很多感情。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对舞蹈很感兴趣。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种舞蹈要很多人一起跳。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂舞蹈，却看得很高兴。", "target_word": "舞蹈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种舞蹈", "label": "量词（种）"}, {"form": "舞蹈家", "label": "复合词"}, {"form": "舞蹈演员", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用身体动作表现情感的艺术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "舞蹈", "is_correct": true, "explanation": "wǔ dǎo 是正确答案，指以有节奏的身体动作表现情感的艺术。"}, {"text": "武打", "is_correct": false, "explanation": "dǎ（第三声）与 dǎo（第三声）韵母不同，dǎ 没有 -o，意思是武术式的打斗动作或场面。"}, {"text": "武道", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，意思是武术之道。"}, {"text": "舞刀", "is_correct": false, "explanation": "dāo（第一声）与 dǎo（第三声）声调不同，意思是挥舞刀具。"}, {"text": "辅导", "is_correct": false, "explanation": "fǔ 与 wǔ 声母不同（f 与 w），意思是辅导、指导学习。"}], "explanations": {"舞蹈": "wǔ dǎo 是正确答案，指以有节奏的身体动作表现情感的艺术。", "武打": "dǎ（第三声）与 dǎo（第三声）韵母不同，dǎ 没有 -o，意思是武术式的打斗动作或场面。", "武道": "dào（第四声）与 dǎo（第三声）声调不同，意思是武术之道。", "舞刀": "dāo（第一声）与 dǎo（第三声）声调不同，意思是挥舞刀具。", "辅导": "fǔ 与 wǔ 声母不同（f 与 w），意思是辅导、指导学习。"}, "sentence_index": null, "correct_answer": "舞蹈"}, "level_3": {"options": [{"text": "舞蹈", "is_correct": true, "explanation": "舞蹈是喜欢的对象，与“从小就”搭配，句意通顺。"}, {"text": "车祸", "is_correct": false, "explanation": "语义：没有人会“喜欢”车祸，句意荒谬。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是令人喜爱的对象，与“喜欢”明显冲突。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“喜欢”不能接“感冒”这类疾病名词，搭配不当。"}], "explanations": {"舞蹈": "舞蹈是喜欢的对象，与“从小就”搭配，句意通顺。", "车祸": "语义：没有人会“喜欢”车祸，句意荒谬。", "垃圾": "语义：垃圾不是令人喜爱的对象，与“喜欢”明显冲突。", "感冒": "搭配：“喜欢”不能接“感冒”这类疾病名词，搭配不当。"}, "sentence_index": 0, "correct_answer": "舞蹈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位很有名的舞蹈。", "explanation": "这里应该用〈舞蹈家〉。舞蹈指艺术形式，不能指人，指人要说舞蹈家或舞蹈演员。"}, {"text": "这段舞蹈很好听，大家都很喜欢。", "explanation": "这里应该用〈音乐〉。“好听”形容声音，舞蹈是用来看的，应说“好看”。"}, {"text": "他每天早上都听舞蹈。", "explanation": "这里应该用〈音乐〉。听的是音乐，舞蹈是用眼睛看的，应说“看舞蹈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舞蹈", "is_correct": true, "explanation": "舞蹈是用身体表达感情的艺术，与“能表达很多感情”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，不能表达感情。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭是燃料，不能表达感情。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙用来开锁，不能表达感情。"}], "explanations": {"舞蹈": "舞蹈是用身体表达感情的艺术，与“能表达很多感情”相符。", "冰箱": "语义：冰箱是电器，不能表达感情。", "煤炭": "语义：煤炭是燃料，不能表达感情。", "钥匙": "语义：钥匙用来开锁，不能表达感情。"}, "sentence_index": 6, "correct_answer": "舞蹈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我学会了一座舞蹈。", "explanation": "这里应该用〈种〉。座用于山、桥、建筑等大型固定物，舞蹈是一种艺术形式，应说“一种舞蹈”。"}, {"text": "他站在舞蹈上，等着观众。", "explanation": "这里应该用〈舞台〉。舞蹈是表演活动，不能作场所，“站在……上”要用表示地点的词。"}, {"text": "他在台上跳了一篇舞蹈，观众很喜欢。", "explanation": "这里应该用〈段〉。篇用于文章，舞蹈要用“段”，应说“跳了一段舞蹈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只舞蹈的动作很优美。", "corrected_sentence": "这种舞蹈的动作很优美。", "error_description": "量词错误：“只”用于动物及单个小物件，不能修饰舞蹈。舞蹈指艺术形式，应用量词“种”，应说“这种舞蹈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张舞蹈很有特色。", "corrected_sentence": "这种舞蹈很有特色。", "error_description": "量词错误：舞蹈指一种艺术形式，应用量词“种”，“张”用于平面的东西，不能修饰舞蹈。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
