INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92007, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专科是高等教育中学制较短、偏重专业的学历层次；也指医院里专治某类病的科室。", "primary_collocate": null, "pronunciation": "zhuān kē", "ipa": "ʈʂwan˥ kʰɤ˥", "syllable_count": 2, "sentences": [{"text": "我弟弟想读专科，然后早点工作。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的儿童专科很有名。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的病比较复杂，得去看专科。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先读了专科，后来又读了本科。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的专科很多，病人不用去别处。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我的病要去专科检查。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专科的学习时间比本科短一年。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她高中毕业后读了三年专科。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小医院没有专科，病人只好去大医院。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所专科学校的学生毕业后很容易找到工作。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "專科", "label": "繁体"}, {"form": "专科学校", "label": "复合"}, {"form": "专科医生", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：只学一个方面的学校，或医院里专治一类病的科室", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552319c8-d678-4547-b1ce-dbccda73abfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专科", "is_correct": true, "explanation": "正确：“读专科”指就读学制较短的学历层次，与前文“想读”搭配。"}, {"text": "驾照", "is_correct": false, "explanation": "搭配：“读”搭配学业，驾照要说“考”或“考取”，不能说“读驾照”。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不是可以就读的地方，句意不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的地方，“读医院”不是学业阶段，句意不通。"}], "explanations": {"专科": "正确：“读专科”指就读学制较短的学历层次，与前文“想读”搭配。", "驾照": "搭配：“读”搭配学业，驾照要说“考”或“考取”，不能说“读驾照”。", "工厂": "语义：工厂是生产场所，不是可以就读的地方，句意不通。", "医院": "语义：医院是治病的地方，“读医院”不是学业阶段，句意不通。"}, "sentence_index": 0, "correct_answer": "专科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张专科很大，放得下电脑。", "explanation": "这里应该用〈桌子〉。专科指学校或医院科室，不指家具；放电脑的家具要用桌子。"}, {"text": "这位专科很有经验。", "explanation": "这里应该用〈专家〉。专科指学校或医院科室，不指人；说“有经验”的人要用专家。"}, {"text": "他想继续提高专科。", "explanation": "这里应该用〈学历〉。“提高”搭配学历、水平，专科是一种学历层次，不能说提高专科。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专科", "is_correct": true, "explanation": "正确：“专科的学习时间”指专科学制的学习时长，与“比本科短一年”相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，没有学习时间，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是学习的对象或阶段，不能有学习时间。"}, {"text": "农场", "is_correct": false, "explanation": "搭配：“学习时间”需要学习的主体或学业阶段，农场不搭配。"}], "explanations": {"专科": "正确：“专科的学习时间”指专科学制的学习时长，与“比本科短一年”相符。", "厨房": "语义：厨房是做饭的地方，没有学习时间，句意不通。", "歌曲": "语义：歌曲不是学习的对象或阶段，不能有学习时间。", "农场": "搭配：“学习时间”需要学习的主体或学业阶段，农场不搭配。"}, "sentence_index": 6, "correct_answer": "专科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个专科很甜，孩子们都爱吃。", "explanation": "这里应该用〈水果〉。专科指学校或医院科室，不指食物；说很甜、孩子爱吃的东西要用水果。"}, {"text": "这份报纸每天都有一个财经专科，讲股票行情。", "explanation": "这里应该用〈专栏〉。专科指学校或科室，不指报纸上的固定版块；报刊的固定栏目要用专栏。"}, {"text": "这家商场一楼有很多化妆品专科。", "explanation": "这里应该用〈专柜〉。专科指学校或医院科室，不指商场里卖某类商品的柜台；商场里的柜台要用专柜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院有一只专科很有名。", "corrected_sentence": "这家医院有一个专科很有名。", "error_description": "量词错误：“专科”的量词应为“个”，不能用“只”（“只”多用于动物或小件物品）。错误形式是“一只专科”，正确形式是“一个专科”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她专科了毕业后，直接进了一家公司。", "corrected_sentence": "她专科毕业后，直接进了一家公司。", "error_description": "助词错误：“了”不能紧接在名词“专科”后面，“专科”后应直接接“毕业”。错误形式是“专科了毕业”，正确形式是“专科毕业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
