INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专门学科；高等教育中学制较短、偏重专业的学历层次，或医院中专治某类病的科室。", "primary_collocate": null, "pronunciation": "zhuān kē", "ipa": "ʈʂwan˥ kʰɤ˥", "syllable_count": 2, "sentences": [{"text": "他的学历是专科，不是本科。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专科毕业以后，她在银行上班。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先读专科，再考本科。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的皮肤专科每天都有很多人。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读专科只要三年，比本科少一年。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要求大学专科以上的学历。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的专科要提前预约。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他专科毕业后，自己开了一家小店。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读专科的时候，每天都去图书馆。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病很少见，要去大医院的专科看。", "target_word": "专科", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "專科", "label": "繁体"}, {"form": "专科生", "label": "复合"}, {"form": "专科门诊", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：学制较短、偏重专业的学历层次，或医院专治某类病的科室", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552319c8-d678-4547-b1ce-dbccda73abfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专科", "is_correct": true, "explanation": "正确：“学历是专科”指学制较短的高等教育学历，与“不是本科”形成对比。"}, {"text": "眼科", "is_correct": false, "explanation": "语义：眼科是医院科室，不是学历层次，句意不通。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是金融机构，不能用来说明学历。"}, {"text": "驾照", "is_correct": false, "explanation": "搭配：驾照是证件，不能用“是”来说明受教育程度，与“学历”不搭配。"}], "explanations": {"专科": "正确：“学历是专科”指学制较短的高等教育学历，与“不是本科”形成对比。", "眼科": "语义：眼科是医院科室，不是学历层次，句意不通。", "银行": "语义：银行是金融机构，不能用来说明学历。", "驾照": "搭配：驾照是证件，不能用“是”来说明受教育程度，与“学历”不搭配。"}, "sentence_index": 0, "correct_answer": "专科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的主治专科是个很负责的人。", "explanation": "这里应该用〈医生〉。专科指学历或科室，不指人；说“是个负责的人”要用医生。"}, {"text": "她一直想提高专科。", "explanation": "这里应该用〈学历〉。“提高”搭配学历、水平，专科是一种学历层次，不能说提高专科。"}, {"text": "那位专科很有名。", "explanation": "这里应该用〈专家〉。专科不指人，说“有名”的人要用专家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专科", "is_correct": true, "explanation": "正确：“医院的专科”指医院里专治某类病的科室，要提前预约。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯不需要预约，这句话说不通。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所不需要提前预约，句意不通。"}, {"text": "药房", "is_correct": false, "explanation": "搭配：“预约”搭配门诊、号、床位，药房不搭配。"}], "explanations": {"专科": "正确：“医院的专科”指医院里专治某类病的科室，要提前预约。", "电梯": "语义：电梯不需要预约，这句话说不通。", "厕所": "语义：厕所不需要提前预约，句意不通。", "药房": "搭配：“预约”搭配门诊、号、床位，药房不搭配。"}, "sentence_index": 6, "correct_answer": "专科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报纸的第三版每天都有一个专科，讲财经新闻。", "explanation": "这里应该用〈专栏〉。专科指学制或医院科室，不指报纸上固定的版块；报刊的固定栏目要用专栏。"}, {"text": "这家超市的酒类专科在二楼。", "explanation": "这里应该用〈专柜〉。专科指学校或科室，不指超市里卖某类商品的柜台；超市里的柜台要用专柜。"}, {"text": "这条街上开了一家鞋子专科。", "explanation": "这里应该用〈专卖店〉。专科不指销售某类商品的店铺；卖鞋的店要用专卖店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所医院有一条专科很有名。", "corrected_sentence": "这所医院有一个专科很有名。", "error_description": "量词错误：“专科”应搭配“个”，不能用“条”（“条”用于河流、裤子等细长的东西）。错误形式是“一条专科”，正确形式是“一个专科”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他专科了毕业以后，去了一家医院工作。", "corrected_sentence": "他专科毕业以后，去了一家医院工作。", "error_description": "助词错误：“了”不能紧接在名词“专科”后面，“专科”后应直接接“毕业”。错误形式是“专科了毕业”，正确形式是“专科毕业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92009, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "获释", "is_correct": true, "explanation": "正确：“获释”指被释放，与“被捕”（被抓获）相反。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”指去工作，与“被捕”没有对立关系。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”指在水中活动，与“被捕”没有对立关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”指休息入睡，与“被捕”没有对立关系。"}], "correct_answer": "获释", "explanations": {"获释": "正确：“获释”指被释放，与“被捕”（被抓获）相反。", "上班": "语义：“上班”指去工作，与“被捕”没有对立关系。", "游泳": "语义：“游泳”指在水中活动，与“被捕”没有对立关系。", "睡觉": "语义：“睡觉”指休息入睡，与“被捕”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92009, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "获释", "is_correct": true, "explanation": "正确：“获释”指被释放，与“被捕”（被抓获）相反。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“写字”指用笔书写，与“被捕”没有对立关系。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”指天气现象，与“被捕”没有对立关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”指进食，与“被捕”没有对立关系。"}], "correct_answer": "获释", "explanations": {"获释": "正确：“获释”指被释放，与“被捕”（被抓获）相反。", "写字": "语义：“写字”指用笔书写，与“被捕”没有对立关系。", "下雨": "语义：“下雨”指天气现象，与“被捕”没有对立关系。", "吃饭": "语义：“吃饭”指进食，与“被捕”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92009, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被捕是坏人被警察抓住了。", "primary_collocate": null, "pronunciation": "bèi bǔ", "ipa": "pei˥˩ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "坏人昨天晚上被捕了。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小偷在商店门口被捕。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了坏事，最后还是被捕了。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抢钱的人跑了一天，今天被捕了。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，那个坏人已经被捕。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏人被捕的消息，大家都很高兴。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有被捕过。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏人被捕时，手里还拿着刀。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷在路上跑了很久，还是被捕了。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个骗子终于被捕了，老人们都放心了。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "被捕了", "label": "体标"}, {"form": "被捕过", "label": "体标"}, {"form": "被捕入狱", "label": "复合"}, {"form": "被捕者", "label": "复合"}], "register": "中性", "sense_fingerprint": "坏人做了坏事后被警察抓住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92009, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被捕", "is_correct": true, "explanation": "正确：“被捕”指坏人被警察抓住，与“坏人”和“昨天晚上”的语境相符。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，与“坏人”的语境不符，句意不通。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指结束工作，与“坏人昨天晚上”的语境矛盾。"}, {"text": "长高", "is_correct": false, "explanation": "语义：“长高”指身高增长，与“坏人昨天晚上”的语境不符，句意不通。"}], "explanations": {"被捕": "正确：“被捕”指坏人被警察抓住，与“坏人”和“昨天晚上”的语境相符。", "毕业": "语义：“毕业”指完成学业，与“坏人”的语境不符，句意不通。", "退休": "语义：“退休”指结束工作，与“坏人昨天晚上”的语境矛盾。", "长高": "语义：“长高”指身高增长，与“坏人昨天晚上”的语境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "被捕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "抢钱的人跑了一天，今天被捕了十年。", "explanation": "这里应该用〈被判〉。被捕指被抓的那一刻，不能表示刑期的长短，刑期应用〈被判〉。"}, {"text": "他因为迟到被捕了。", "explanation": "这里应该用〈批评〉。被捕是因犯罪被警察抓获，迟到只会被批评，不能说被捕。"}, {"text": "那个老人在街上摔倒后，马上被捕进了医院。", "explanation": "这里应该用〈送〉。被捕指因犯罪被警察抓获，摔倒的老人是被送去医院，不能说被捕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被捕", "is_correct": true, "explanation": "正确：“被捕过”表示有过被警察抓获的经历，与“从来没有”的语境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”只会发生一次，不能用“从来没有……过”来表示经历，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能作“他从来没有……过”的主语，句意不通。"}, {"text": "灭亡", "is_correct": false, "explanation": "语域：“灭亡”多用于国家、文明，用来指人语体不合，句子不自然。"}], "explanations": {"被捕": "正确：“被捕过”表示有过被警察抓获的经历，与“从来没有”的语境相符。", "出生": "语义：“出生”只会发生一次，不能用“从来没有……过”来表示经历，句意不通。", "下雨": "语义：“下雨”是天气现象，不能作“他从来没有……过”的主语，句意不通。", "灭亡": "语域：“灭亡”多用于国家、文明，用来指人语体不合，句子不自然。"}, "sentence_index": 6, "correct_answer": "被捕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个老人在路上走丢了，第二天终于被捕了。", "explanation": "这里应该用〈找到〉。被捕指因犯罪被警察抓获，走丢的老人是被找到，不能说被捕。"}, {"text": "那个被骗的老人终于被捕了，大家都放心了。", "explanation": "被捕指嫌疑人被警察抓获。被骗的老人是受害者，不会被捕；抓住的应该是骗子。"}, {"text": "那个掉进河里的孩子，幸好被捕了。", "explanation": "这里应该用〈获救〉。被捕指被警察抓住，落水的孩子得救应说获救。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个坏人昨天晚上被捕过，大家都松了一口气。", "corrected_sentence": "那个坏人昨天晚上被捕了，大家都松了一口气。", "error_description": "错误：“被捕过”。正确：“被捕了”。“过”表示经历，不能和“昨天晚上”这类具体时间连用，应用“了”表示已经发生。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的邻居是个好人，从来没有被捕了。", "corrected_sentence": "我的邻居是个好人，从来没有被捕过。", "error_description": "错误：“没有被捕了”。正确：“没有被捕过”。“从来没有……”表示没有这种经历，要用“过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
