INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92010, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被警察或有关机关依法逮捕。", "primary_collocate": null, "pronunciation": "bèi bǔ", "ipa": "pei˥˩ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他因为偷东西被捕了。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷昨天晚上在车站被捕。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人被捕后，警察问了他很多问题。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个公司的老板因为骗钱被捕。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被捕的消息今天上了新闻。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的哥哥三年前被捕入狱。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，他被捕时没有说话。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被捕以后，家人都很难过。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你的邻居昨天被捕了，是真的吗？", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车撞人后想跑，当场被捕。", "target_word": "被捕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "被捕了", "label": "体标"}, {"form": "被捕过", "label": "体标"}, {"form": "被捕入狱", "label": "复合"}, {"form": "被捕者", "label": "复合"}], "register": "中性", "sense_fingerprint": "犯罪嫌疑人被警察或司法机关依法逮捕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被捕", "is_correct": true, "explanation": "正确：“被捕”指被警察依法抓获，与“因为偷东西”的原因相符，句子通顺。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，与“偷东西”这个原因毫无关系，句意不通。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指结束工作，不能由“偷东西”引起，句意矛盾。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”通常说“和某人结婚”，偷东西也不会导致结婚，此处搭配不当。"}], "explanations": {"被捕": "正确：“被捕”指被警察依法抓获，与“因为偷东西”的原因相符，句子通顺。", "毕业": "语义：“毕业”指完成学业，与“偷东西”这个原因毫无关系，句意不通。", "退休": "语义：“退休”指结束工作，不能由“偷东西”引起，句意矛盾。", "结婚": "搭配：“结婚”通常说“和某人结婚”，偷东西也不会导致结婚，此处搭配不当。"}, "sentence_index": 0, "correct_answer": "被捕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个公司的老板因为骗钱被捕了三年。", "explanation": "这里应该用〈被关〉。被捕指被警察抓获的那一刻，不能用来表示被拘押的时间长度。"}, {"text": "他因为乱停车被捕了。", "explanation": "这里应该用〈罚款〉。被捕指因犯罪被警察抓获，乱停车只会被罚款，不能说被捕。"}, {"text": "他在路上晕倒后，很快就被捕进了医院。", "explanation": "这里应该用〈送〉。被捕指因犯罪被警察抓获，晕倒的人是被送去医院，不能说被捕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被捕", "is_correct": true, "explanation": "正确：“被捕时”指被警察抓住的时候，与“警察说”的语境相符。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：“演讲”需要开口讲话，与“没有说话”矛盾。"}, {"text": "讲课", "is_correct": false, "explanation": "语义：“讲课”需要开口讲话，与“没有说话”矛盾。"}, {"text": "辩解", "is_correct": false, "explanation": "语义：“辩解”需要开口为自己说话，与“没有说话”矛盾，句意不通。"}], "explanations": {"被捕": "正确：“被捕时”指被警察抓住的时候，与“警察说”的语境相符。", "演讲": "语义：“演讲”需要开口讲话，与“没有说话”矛盾。", "讲课": "语义：“讲课”需要开口讲话，与“没有说话”矛盾。", "辩解": "语义：“辩解”需要开口为自己说话，与“没有说话”矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "被捕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个孩子在学校表现很好，老师却说他被捕了。", "explanation": "这里应该用〈表扬〉。被捕指因犯罪被警察抓获，表现好的孩子应被表扬，不能说被捕。"}, {"text": "那个孩子掉进河里后，幸好被捕了。", "explanation": "这里应该用〈获救〉。被捕指被警察抓住，孩子落水后得救应说获救。"}, {"text": "那个被抢劫的老人当场被捕了。", "explanation": "被捕指嫌疑人被警察抓获。被抢劫的老人是受害者，不会被捕；应该被捕的是抢劫的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人去年被被捕入狱了。", "corrected_sentence": "那个人去年被捕入狱了。", "error_description": "错误：“被被捕”，多写了一个“被”。“被”已表示被动，“被捕”不能重复。正确：“被捕入狱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有被捕了。", "corrected_sentence": "他从来没有被捕过。", "error_description": "错误：“没有被捕了”。正确：“没有被捕过”。“从来没有……”表示没有这种经历，要用“过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
