INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92011, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对照是把两样东西放在一起比一比。", "primary_collocate": null, "pronunciation": "duì zhào", "ipa": "tweɪ˥˩ ʈʂau̯˥˩", "syllable_count": 2, "sentences": [{"text": "请你把两张照片对照一下。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把中文和英文对照着看。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们对照课本检查作业。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对照地图找到了那家店。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对照着答案改作业。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把新旧两本书对照一下，就能看出不同。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请对照表格填写名字。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿着照片对照了很久。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以对照原文看翻译。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把药名和说明书对照着读。", "target_word": "对照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对照着", "label": "体标"}, {"form": "对照了", "label": "体标"}, {"form": "对照过", "label": "体标"}, {"form": "对照对照", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把两样东西放在一起，看看哪里相同、哪里不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91424016-136b-4dbb-8616-3939a22b04a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92011, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对照", "is_correct": true, "explanation": "正确。对照指把两样东西放在一起比较，看异同，符合“把两张照片……一下”的语境。"}, {"text": "朗读", "is_correct": false, "explanation": "搭配：“朗读”的对象是文字，不能用于照片。"}, {"text": "演唱", "is_correct": false, "explanation": "语义：“演唱”指唱歌，与“两张照片”无关。"}, {"text": "吟诵", "is_correct": false, "explanation": "搭配：“吟诵”的对象是诗文，不能用于照片。"}], "explanations": {"对照": "正确。对照指把两样东西放在一起比较，看异同，符合“把两张照片……一下”的语境。", "朗读": "搭配：“朗读”的对象是文字，不能用于照片。", "演唱": "语义：“演唱”指唱歌，与“两张照片”无关。", "吟诵": "搭配：“吟诵”的对象是诗文，不能用于照片。"}, "sentence_index": 0, "correct_answer": "对照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她对照着一张照片哭了。", "explanation": "这里应该用〈看着〉。对照指把两样东西放在一起比较，只有一张照片时不能用对照。"}, {"text": "妈妈对照着我去学校。", "explanation": "这里应该用〈陪着〉。对照指比较，不能用来表示陪伴。"}, {"text": "他对照了那位客人。", "explanation": "这里应该用〈迎接〉。对照指比较，不能用来表示迎接客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对照", "is_correct": true, "explanation": "正确。对照指把两样东西放在一起比较，符合“请……填写名字”的语境。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”的对象是人，不能用于表格。"}, {"text": "跳跃", "is_correct": false, "explanation": "语义：“跳跃”是身体动作，与“表格”无关。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”指把食物嚼碎，不能用于表格。"}], "explanations": {"对照": "正确。对照指把两样东西放在一起比较，符合“请……填写名字”的语境。", "拥抱": "搭配：“拥抱”的对象是人，不能用于表格。", "跳跃": "语义：“跳跃”是身体动作，与“表格”无关。", "咀嚼": "语义：“咀嚼”指把食物嚼碎，不能用于表格。"}, "sentence_index": 6, "correct_answer": "对照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对照着书包去上学。", "explanation": "这里应该用〈背着〉。对照指把两样东西放在一起比较，不能用来表示背东西。"}, {"text": "老师对照着我们唱歌。", "explanation": "这里应该用〈教〉。对照指比较，不能用来表示教唱歌。"}, {"text": "他把礼物对照着送给了妈妈。", "explanation": "这里不应该用对照。对照指把两样东西放在一起比较，送礼物不需要比较，应说“他把礼物送给了妈妈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你把这两份合同对照着一下，看看哪里不一样。", "corrected_sentence": "请你把这两份合同对照一下，看看哪里不一样。", "error_description": "“一下”表示动作短暂、轻松，不能与“着”同用；“对照”后应直接接“一下”，去掉“着”，应为“对照一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对照着了说明书组装了书架。", "corrected_sentence": "我对照着说明书组装了书架。", "error_description": "动词“对照”后的“着”与“了”不能同时使用，多余的“了”应去掉，应为“对照着说明书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自愿", "is_correct": true, "explanation": "自愿与被迫意思相反：自愿指出于本意，被迫指不得不做。"}, {"text": "努力", "is_correct": false, "explanation": "努力与被迫没有反义关系：努力指尽力去做，与被迫不构成相对。"}, {"text": "研究", "is_correct": false, "explanation": "研究与被迫没有反义关系：研究指深入探讨，与被迫不构成相对。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫与被迫没有反义关系：打扫指清除脏物，与被迫不构成相对。"}], "correct_answer": "自愿", "explanations": {"自愿": "自愿与被迫意思相反：自愿指出于本意，被迫指不得不做。", "努力": "努力与被迫没有反义关系：努力指尽力去做，与被迫不构成相对。", "研究": "研究与被迫没有反义关系：研究指深入探讨，与被迫不构成相对。", "打扫": "打扫与被迫没有反义关系：打扫指清除脏物，与被迫不构成相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自愿", "is_correct": true, "explanation": "自愿与被迫意思相反：自愿指出于本意，被迫指不得不做。"}, {"text": "尝试", "is_correct": false, "explanation": "尝试与被迫没有反义关系：尝试指试着去做，与被迫不构成相对。"}, {"text": "整理", "is_correct": false, "explanation": "整理与被迫没有反义关系：整理指使事物有条理，与被迫不构成相对。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论与被迫没有反义关系：讨论指交换意见，与被迫不构成相对。"}], "correct_answer": "自愿", "explanations": {"自愿": "自愿与被迫意思相反：自愿指出于本意，被迫指不得不做。", "尝试": "尝试与被迫没有反义关系：尝试指试着去做，与被迫不构成相对。", "整理": "整理与被迫没有反义关系：整理指使事物有条理，与被迫不构成相对。", "讨论": "讨论与被迫没有反义关系：讨论指交换意见，与被迫不构成相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被迫是你不想做，可是别人让你一定要做。", "primary_collocate": null, "pronunciation": "bèi pò", "ipa": "pei˥˩ pʰo˥˩", "syllable_count": 2, "sentences": [{"text": "我不想去，可是妈妈让我去，我被迫去了。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不喜欢唱歌，今天被迫唱了一首。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板要我加班，我被迫留了下来。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟不爱吃菜，妈妈说一定要吃，他被迫吃了几口。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢跑步，老师让我跑，我被迫跑了。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想结婚，家里人一直说，她被迫同意了。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想道歉，可是大家都看着他，他被迫说了对不起。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想借钱给他，他一直问，我被迫答应了。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不想学琴，爸爸一定要他练，他被迫坐到钢琴前。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们不想打扫，老师说必须做，大家被迫动手。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "自己不想做，但别人要求一定要做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62980f86-a355-48b6-b578-ee1687d5ac53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "被迫", "is_correct": true, "explanation": "被迫（bèi pò）：自己不想做，却被别人要求一定要做。"}, {"text": "北坡", "is_correct": false, "explanation": "北坡（běi pō）与被迫（bèi pò）两个音节声调都不同（第三声与第四声、第一声与第四声），意思是山的北面。"}, {"text": "被派", "is_correct": false, "explanation": "被派（bèi pài）与被迫（bèi pò）第二个音节韵母不同（ai 与 o），意思是被派遣。"}, {"text": "被骗", "is_correct": false, "explanation": "被骗（bèi piàn）与被迫（bèi pò）第二个音节韵母不同（ian 与 o），意思是受了欺骗。"}], "explanations": {"被迫": "被迫（bèi pò）：自己不想做，却被别人要求一定要做。", "北坡": "北坡（běi pō）与被迫（bèi pò）两个音节声调都不同（第三声与第四声、第一声与第四声），意思是山的北面。", "被派": "被派（bèi pài）与被迫（bèi pò）第二个音节韵母不同（ai 与 o），意思是被派遣。", "被骗": "被骗（bèi piàn）与被迫（bèi pò）第二个音节韵母不同（ian 与 o），意思是受了欺骗。"}, "sentence_index": null, "correct_answer": "被迫"}, "level_3": {"options": [{"text": "被迫", "is_correct": true, "explanation": "被迫：我不想去，但妈妈要求去，符合“不愿意却不得不做”的意思。"}, {"text": "乐意", "is_correct": false, "explanation": "语义：“乐意”表示愿意，与“我不想去”矛盾。"}, {"text": "自愿", "is_correct": false, "explanation": "语义：“自愿”表示出于本意，与“我不想去”矛盾。"}, {"text": "允许", "is_correct": false, "explanation": "配价：“允许”需要允许者，“我”不能允许自己去。"}], "explanations": {"被迫": "被迫：我不想去，但妈妈要求去，符合“不愿意却不得不做”的意思。", "乐意": "语义：“乐意”表示愿意，与“我不想去”矛盾。", "自愿": "语义：“自愿”表示出于本意，与“我不想去”矛盾。", "允许": "配价：“允许”需要允许者，“我”不能允许自己去。"}, "sentence_index": 0, "correct_answer": "被迫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟不爱吃菜，妈妈说一定要吃，他被迫自愿吃了几口。", "explanation": "这里〈被迫〉用错了：被迫表示不得不做、并非本愿，与出于本愿、情愿去做的意思相反，不能用来修饰同一个动作。"}, {"text": "弟弟不爱吃菜，妈妈说一定要吃，他被迫主动吃了几口。", "explanation": "这里〈被迫〉用错了：被迫表示吃是不得已，与自发、积极去做的态度相反，不能用来修饰同一个动作。"}, {"text": "弟弟不爱吃菜，妈妈说一定要吃，他被迫吃了几口，这是他自己的主意。", "explanation": "这里〈被迫〉用错了：被迫表示勉强、并非出于本意，与“这是他自己的主意”相反，不能用来修饰同一个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被迫", "is_correct": true, "explanation": "被迫：大家都看着他，他不得不说对不起，符合句意。"}, {"text": "乐于", "is_correct": false, "explanation": "语义：“乐于”表示乐意，与“他不想道歉”矛盾。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：“愿意”表示乐意，与“他不想道歉”矛盾。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“习惯”表示平日惯常如此，与“他不想道歉”“被迫”的情境矛盾。"}], "explanations": {"被迫": "被迫：大家都看着他，他不得不说对不起，符合句意。", "乐于": "语义：“乐于”表示乐意，与“他不想道歉”矛盾。", "愿意": "语义：“愿意”表示乐意，与“他不想道歉”矛盾。", "习惯": "语义：“习惯”表示平日惯常如此，与“他不想道歉”“被迫”的情境矛盾。"}, "sentence_index": 6, "correct_answer": "被迫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们不想打扫，大家被迫都抢着动手。", "explanation": "这里〈被迫〉用错了：被迫表示不情愿、受压而做，却接着描述争先恐后的积极态度，两者意思相反。"}, {"text": "同学们不想打扫，大家被迫很喜欢动手。", "explanation": "这里〈被迫〉用错了：被迫表示勉强、不情愿，与发自内心的喜爱相反，不能说被迫却同时表示喜爱。"}, {"text": "同学们不想打扫，大家被迫积极主动地动手。", "explanation": "这里〈被迫〉用错了：被迫表示出于无奈、并非本意，却接着描述出于自身热情、自发去做的态度，前后意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家不想去，却被迫了排队。", "corrected_sentence": "大家不想去，却被迫排了队。", "error_description": "错误：“了”放在“被迫”后面，变成“被迫了排队”。正确应为“被迫排了队”，“了”放在动词后表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不愿意搬家，可是房东一直催，他被被迫搬走了。", "corrected_sentence": "他不愿意搬家，可是房东一直催，他被迫搬走了。", "error_description": "错误：多写了一个“被”。被迫本身已含被动意思，前面不能再加“被”。正确应为“他被迫搬走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
