INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92015, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小青年是年纪不大的年轻人。", "primary_collocate": null, "pronunciation": "xiǎo qīng nián", "ipa": "ɕjɑʊ̯˨˩ tɕʰiŋ˥ njɛn˧˥", "syllable_count": 3, "sentences": [{"text": "公园里有几个小青年在打篮球。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小青年很有礼貌，见到老人就让座。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那几个小青年一起去海边玩了。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还是个小青年，没有什么工作经验。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "店里新来了一个小青年，帮客人拿东西。", "target_word": "小青年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁上，小青年主动给奶奶让了座。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几个小青年围着桌子，正在讨论比赛。", "target_word": "小青年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他是个小青年，做事一点儿也不马虎。", "target_word": "小青年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的小青年大多去城里打工了。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上广场上有很多小青年在跳舞。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "群", "label": "量词"}], "register": "口语", "sense_fingerprint": "年纪不大的年轻人，口语称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbb1089a-7f0e-4a1d-9b64-4094ab18e718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小青年", "is_correct": true, "explanation": "正确：“小青年”指年纪不大的年轻人，可以在公园里打篮球。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不会打篮球，句子说的是人。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是器材，本身不能“打篮球”，要说打球的人。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不会打篮球，句子说的是能打球的人。"}], "explanations": {"小青年": "正确：“小青年”指年纪不大的年轻人，可以在公园里打篮球。", "小猫": "语义：小猫是动物，不会打篮球，句子说的是人。", "篮球": "语义：篮球是器材，本身不能“打篮球”，要说打球的人。", "水果": "语义：水果不会打篮球，句子说的是能打球的人。"}, "sentence_index": 0, "correct_answer": "小青年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位小青年是退休多年的老校长，桃李满天下。", "explanation": "这里应该用〈老人〉或〈前辈〉。小青年只指年纪不大的年轻人，不能用于退休多年、桃李满天下的老校长。"}, {"text": "这个小青年刚满八岁，已经会自己做饭了。", "explanation": "这里应该用〈小孩〉。小青年指年轻人，不能用来称呼八岁的孩子。"}, {"text": "那个小青年五十岁了，还在码头干活。", "explanation": "这里应该用〈大叔〉。小青年指年纪不大的年轻人，五十岁的人不能称为小青年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小青年", "is_correct": true, "explanation": "正确：“小青年”是人，可以围着桌子讨论比赛。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能围着桌子讨论比赛。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机没有思考能力，不能讨论比赛。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“比赛”可以是讨论的对象，但不能作“围着桌子”的主语。"}], "explanations": {"小青年": "正确：“小青年”是人，可以围着桌子讨论比赛。", "椅子": "语义：椅子是家具，不能围着桌子讨论比赛。", "手机": "语义：手机没有思考能力，不能讨论比赛。", "比赛": "搭配：“比赛”可以是讨论的对象，但不能作“围着桌子”的主语。"}, "sentence_index": 6, "correct_answer": "小青年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下午幼儿园的操场上有很多小青年在做游戏。", "explanation": "这里应该用〈儿童〉。小青年指年纪不大的年轻人，不能用来指幼儿园里的小朋友。"}, {"text": "早上公园里，几个小青年白发苍苍，正在下棋。", "explanation": "这里应该用〈老人〉。小青年指年纪不大的年轻人，白发苍苍的人不能称为小青年。"}, {"text": "这位小青年在工地上干了四十年，是老师傅了。", "explanation": "这里应该用〈老师傅〉。小青年指年纪不大的年轻人，干了四十年的人不能称为小青年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "操场边上有两个小青年们在聊天。", "corrected_sentence": "操场边上有两个小青年在聊天。", "error_description": "错误：“两个小青年们”。正确：“两个小青年”。“们”不能用在数词和量词之后，直接说“两个小青年”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区的活动中心里有几只小青年在下棋。", "corrected_sentence": "社区的活动中心里有几个小青年在下棋。", "error_description": "错误：“几只小青年”。正确：“几个小青年”。“只”多用于动物，指人要用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
