INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年纪较轻的青年人。", "primary_collocate": null, "pronunciation": "xiǎo qīng nián", "ipa": "ɕjɑʊ̯˨˩ tɕʰiŋ˥ njɛn˧˥", "syllable_count": 3, "sentences": [{"text": "酒吧门口站着几个小青年。", "target_word": "小青年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司最近招了不少小青年。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师傅带着两个小青年学手艺。", "target_word": "小青年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小青年刚来的时候，什么都不会做。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说，现在的小青年很有想法。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们这些小青年，别总是玩手机。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看起来像个小青年，其实已经三十岁了。", "target_word": "小青年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站旁边有几个小青年在等朋友。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小青年为了比赛，每天都练习到很晚。", "target_word": "小青年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小青年要多听听老人的建议。", "target_word": "小青年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "群", "label": "量词"}], "register": "口语", "sense_fingerprint": "年纪较轻的青年人，常带随意或长辈口吻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbb1089a-7f0e-4a1d-9b64-4094ab18e718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小青年", "is_correct": true, "explanation": "正确：“小青年”是人，可以站在酒吧门口。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不会站在酒吧门口，句子说的是人。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不会“站着”，也不会在门口等人。"}, {"text": "黑板", "is_correct": false, "explanation": "量词：黑板应说“块”，与句中的“几个”不搭配。"}], "explanations": {"小青年": "正确：“小青年”是人，可以站在酒吧门口。", "冰箱": "语义：冰箱是家电，不会站在酒吧门口，句子说的是人。", "电脑": "语义：电脑是机器，不会“站着”，也不会在门口等人。", "黑板": "量词：黑板应说“块”，与句中的“几个”不搭配。"}, "sentence_index": 0, "correct_answer": "小青年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个小青年已经六十多岁了，头发都白了。", "explanation": "这里应该用〈老人〉。小青年指年纪较轻的青年人，六十多岁、头发都白了的人不能称为小青年。"}, {"text": "这个小青年刚学会走路。", "explanation": "这里应该用〈小孩〉。小青年指青年人，不能用来说刚学会走路的孩子。"}, {"text": "这位小青年在这家公司干了三十年了。", "explanation": "这里应该用〈老员工〉。小青年指年纪较轻的青年人，不能用于在公司干了三十年的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小青年", "is_correct": true, "explanation": "正确：“小青年”可指年纪较轻的人，与“其实已经三十岁”形成对比。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，没有年龄可言，与“其实已经三十岁了”无法对照。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”与人的年龄外貌无关，句中“其实已经三十岁”的对照无法成立。"}, {"text": "大树", "is_correct": false, "explanation": "语义与量词：“大树”不能描述人的外表，且应说“棵”，不能说“个大树”。"}], "explanations": {"小青年": "正确：“小青年”可指年纪较轻的人，与“其实已经三十岁”形成对比。", "桌子": "语义：“桌子”是家具，没有年龄可言，与“其实已经三十岁了”无法对照。", "石头": "语义：“石头”与人的年龄外貌无关，句中“其实已经三十岁”的对照无法成立。", "大树": "语义与量词：“大树”不能描述人的外表，且应说“棵”，不能说“个大树”。"}, "sentence_index": 6, "correct_answer": "小青年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下午幼儿园的门口有很多小青年在等家长。", "explanation": "这里应该用〈儿童〉。小青年指年纪较轻的青年人，不能用来指幼儿园里等家长的孩子。"}, {"text": "早上公园里，几个小青年满脸皱纹，正在下棋。", "explanation": "这里应该用〈老人〉。小青年指年纪较轻的青年人，满脸皱纹的人不能称为小青年。"}, {"text": "我爷爷是个小青年，今年八十岁了。", "explanation": "这里应该用〈老年人〉。小青年指年纪较轻的青年人，不能用来称呼八十岁的爷爷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市场门口有两个小青年们在卖水果。", "corrected_sentence": "市场门口有两个小青年在卖水果。", "error_description": "错误：“两个小青年们”。正确：“两个小青年”。“们”不能用在数词和量词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆里有几本小青年在自习。", "corrected_sentence": "图书馆里有几个小青年在自习。", "error_description": "错误：“几本小青年”。正确：“几个小青年”。“本”用于书籍，指人要用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
