INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92017, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请看是请你用眼睛看一看。", "primary_collocate": null, "pronunciation": "qǐng kàn", "ipa": "tɕʰiŋ˨˩ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "请看黑板，老师要写字了。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看这只小猫，它在睡觉。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看窗外，下雪了。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看我的手，手里有什么？", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看那边，有一只鸟在树上。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看这张照片，这是我家。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看左边，那里有一家书店。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看天上，月亮多圆啊。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看这里，我给你们照相。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看箱子里，有一只小狗。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "请看看", "label": "重叠"}, {"form": "請看", "label": "繁体"}], "register": "中性", "sense_fingerprint": "请对方用眼睛看某个具体的人或东西，多用于口语里的当面提示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：黑板不能吃，“吃”的对象只能是食物。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”的对象是声音，不说听黑板。"}, {"text": "请看", "is_correct": true, "explanation": "正确。“请看”请对方看向黑板，与后文“老师要写字了”的语境相符。"}, {"text": "关", "is_correct": false, "explanation": "搭配：“关”用于门、窗、灯等，不说关黑板。"}], "explanations": {"吃": "语义：黑板不能吃，“吃”的对象只能是食物。", "听": "搭配：“听”的对象是声音，不说听黑板。", "请看": "正确。“请看”请对方看向黑板，与后文“老师要写字了”的语境相符。", "关": "搭配：“关”用于门、窗、灯等，不说关黑板。"}, "sentence_index": 0, "correct_answer": "请看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请看这首歌，很好听。", "explanation": "这里应该用〈请听〉。欣赏歌曲、评价“好听”要用“听”，“请看”只指用眼睛看。"}, {"text": "请看这杯咖啡，味道很香。", "explanation": "这里应该用〈请闻〉。香味要靠鼻子感知，说气味应用“闻”，不能用“看”。"}, {"text": "请看这块布，很柔软。", "explanation": "这里应该用〈请摸〉。柔软要靠手的触感来判断，“请看”只用眼睛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能唱方位，与“那里有一家书店”无关。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不说穿左边。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”用鼻子感知气味，左边不是可以闻的对象。"}, {"text": "请看", "is_correct": true, "explanation": "正确。“请看左边”引导对方注意左侧，后文说明那里有一家书店。"}], "explanations": {"唱": "语义：“唱”的对象是歌曲，不能唱方位，与“那里有一家书店”无关。", "穿": "搭配：“穿”用于衣服、鞋袜，不说穿左边。", "闻": "语义：“闻”用鼻子感知气味，左边不是可以闻的对象。", "请看": "正确。“请看左边”引导对方注意左侧，后文说明那里有一家书店。"}, "sentence_index": 6, "correct_answer": "请看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请看一看这碗汤，味道很鲜。", "explanation": "这里应该用〈请尝〉。品尝味道要用“尝”，“请看”只用于眼睛看。"}, {"text": "请看这段录音，声音很清楚。", "explanation": "这里应该用〈请听〉。录音是声音，要用“听”；“请看”是请对方用眼睛看。"}, {"text": "请看一下这束花，香味很浓。", "explanation": "这里应该用〈请闻〉。香味要靠鼻子感知，说气味应用“闻”，“请看”只表示用眼睛看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请看了窗户，外面在下雨。", "corrected_sentence": "请看窗户，外面在下雨。", "error_description": "错误形式：“请看了”；正确形式：“请看”。“了”表示动作完成，不能加在请对方看的祈使用语上，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请看过前面，有一个超市。", "corrected_sentence": "请看前面，有一个超市。", "error_description": "体标错误：祈使用语“请看”后不能接表示经历的“过”，应删去“过”，应说“请看前面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
