INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请对方观看或注意某处、某内容的客气说法。", "primary_collocate": null, "pronunciation": "qǐng kàn", "ipa": "tɕʰiŋ˨˩ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "请看第三页的图表。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看下面的例子。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看通知，明天不上课。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看说明书，上面写得很清楚。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看这份合同，有问题请告诉我。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看屏幕上的数字。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看我们的新产品介绍。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看最后一行，这里有错。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看今天的新闻，里面有天气信息。", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看菜单，您想吃什么？", "target_word": "请看", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "请看看", "label": "重叠"}, {"form": "請看", "label": "繁体"}], "register": "书面", "sense_fingerprint": "客气地请对方留意文字、图表、说明等内容，常见于书面和公共场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：图表不能喝，“喝”的对象是饮料。"}, {"text": "唱", "is_correct": false, "explanation": "语义：图表不能唱，“唱”用于歌曲。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣物，不说穿图表。"}, {"text": "请看", "is_correct": true, "explanation": "正确。“请看”客气地请对方留意第三页的图表，符合书面语境。"}], "explanations": {"喝": "语义：图表不能喝，“喝”的对象是饮料。", "唱": "语义：图表不能唱，“唱”用于歌曲。", "穿": "搭配：“穿”用于衣物，不说穿图表。", "请看": "正确。“请看”客气地请对方留意第三页的图表，符合书面语境。"}, "sentence_index": 0, "correct_answer": "请看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请看这块饼干，味道很甜。", "explanation": "这里应该用〈请尝〉。品尝味道要用“尝”，“请看”只表示请对方看文字、图表等内容，不能用来说明味道。"}, {"text": "请看这段音乐，声音很欢快。", "explanation": "这里应该用〈请听〉。音乐要用“听”，“请看”用于文字、图表等内容，不能用来形容声音。"}, {"text": "请看这瓶香水，香味很浓。", "explanation": "这里应该用〈请闻〉。香味要用鼻子闻，“请看”只表示请对方看，不能用来说明气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吞", "is_correct": false, "explanation": "语义：产品介绍是文字内容，不能吞。"}, {"text": "请看", "is_correct": true, "explanation": "正确。“请看”客气地请对方留意产品介绍，符合书面和公告语境。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是人或动物，不说喂介绍。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是避开，与请对方留意产品介绍的意思相反。"}], "explanations": {"吞": "语义：产品介绍是文字内容，不能吞。", "请看": "正确。“请看”客气地请对方留意产品介绍，符合书面和公告语境。", "喂": "搭配：“喂”的对象是人或动物，不说喂介绍。", "躲": "语义：“躲”是避开，与请对方留意产品介绍的意思相反。"}, "sentence_index": 6, "correct_answer": "请看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请看这段鼓声，节奏很快。", "explanation": "这里应该用〈请听〉。鼓声是声音，要用“听”；“请看”只用于文字、图表等可见的内容。"}, {"text": "请看一下这碗汤，味道很鲜。", "explanation": "这里应该用〈请尝〉。品尝味道要用“尝”，“请看”只表示请对方看，不能用来说明味道。"}, {"text": "请看这块丝绸，摸起来很光滑。", "explanation": "这里应该用〈请摸〉。摸起来的质感要用手感受，“请看”只用于眼睛看，不能用来说明触感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请看见附件，有疑问请联系我们。", "corrected_sentence": "请看附件，有疑问请联系我们。", "error_description": "错误形式：“请看见附件”；正确形式：“请看附件”。“看见”强调视觉结果，请对方留意附件应用“看”，多出的“见”会改变句意。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请看了数据表，有问题请告诉我。", "corrected_sentence": "请看一下数据表，有问题请告诉我。", "error_description": "错误形式：“请看了”；正确形式：“请看一下”。请对方查看时不能在“看”后加“了”，应用“请看一下”表示客气的请求。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
