INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92019, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "届时是到了那个时候。", "primary_collocate": null, "pronunciation": "jiè shí", "ipa": "tɕjɛ˥˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "会议下周三开始，届时请准时到。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新店下个月开业，届时欢迎大家来玩。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛在五月举行，届时会有很多人来看。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明年结婚，届时一定请你来。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机九月上市，届时价格会低一些。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说周五考试，届时请带好笔。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校六月开放参观，届时家长可以进来。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司下月搬家，届时会发通知。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路年底修好，届时去机场会快很多。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览十号开幕，届时市长也会来。", "target_word": "届时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "届时：到了(前面说的)那个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf3d60e-a1e3-44ad-8ec7-68f909d098f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92019, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "届时", "is_correct": true, "explanation": "正确。届时（jiè shí）指到了前面说的那个时候。"}, {"text": "结识", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是“认识”，不是“到了那个时候”。"}, {"text": "解释", "is_correct": false, "explanation": "jiě（第三声）与 jiè（第四声）、shì（第四声）与 shí（第二声）声调都不同，意思是“说明”。"}, {"text": "几时", "is_correct": false, "explanation": "jǐ（第三声）与 jiè（第四声）声调不同，意思是“什么时候”，用于疑问。"}], "explanations": {"届时": "正确。届时（jiè shí）指到了前面说的那个时候。", "结识": "jié（第二声）与 jiè（第四声）声调不同，意思是“认识”，不是“到了那个时候”。", "解释": "jiě（第三声）与 jiè（第四声）、shì（第四声）与 shí（第二声）声调都不同，意思是“说明”。", "几时": "jǐ（第三声）与 jiè（第四声）声调不同，意思是“什么时候”，用于疑问。"}, "sentence_index": null, "correct_answer": "届时"}, "level_3": {"options": [{"text": "届时", "is_correct": true, "explanation": "正确。届时指到了前面说的下周三开会的那个时候，与句意相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指立即发生，与“下周三开始”的将来时间冲突。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，不能用于尚未到来的下周三。"}, {"text": "常常", "is_correct": false, "explanation": "体貌：“常常”表示反复发生的习惯，不能用来说一次性的会议。"}], "explanations": {"届时": "正确。届时指到了前面说的下周三开会的那个时候，与句意相符。", "马上": "语义：“马上”指立即发生，与“下周三开始”的将来时间冲突。", "已经": "语义：“已经”表示动作已经完成，不能用于尚未到来的下周三。", "常常": "体貌：“常常”表示反复发生的习惯，不能用来说一次性的会议。"}, "sentence_index": 0, "correct_answer": "届时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他上高中的时候很喜欢打篮球，届时他每天放学都去球场。", "explanation": "这里应该用〈当时〉。届时指到了将来的某个时间，不能用来说过去的情况；讲过去的事要用当时。"}, {"text": "我先吃了饭，届时去了图书馆。", "explanation": "这里应该用〈然后〉。届时强调到了预先说定或前面提到的时间，不能表示先后相接的两个动作。"}, {"text": "警察先进了大楼，届时消防员也赶到了。", "explanation": "这里应该用〈随后〉。届时指到了所说的时间，不表示前一件事之后紧接着发生另一件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92019, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "届时", "is_correct": true, "explanation": "正确。届时（jiè shí）指到了前面说的那个时候。"}, {"text": "节食", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是“控制饮食”。"}, {"text": "街市", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）、shì（第四声）与 shí（第二声）声调都不同，意思是“街上的市场”。"}, {"text": "结实", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）声调不同，第二个音节 shi 读轻声，意思是“牢固”。"}], "explanations": {"届时": "正确。届时（jiè shí）指到了前面说的那个时候。", "节食": "jié（第二声）与 jiè（第四声）声调不同，意思是“控制饮食”。", "街市": "jiē（第一声）与 jiè（第四声）、shì（第四声）与 shí（第二声）声调都不同，意思是“街上的市场”。", "结实": "jiē（第一声）与 jiè（第四声）声调不同，第二个音节 shi 读轻声，意思是“牢固”。"}, "sentence_index": null, "correct_answer": "届时"}, "level_3": {"options": [{"text": "届时", "is_correct": true, "explanation": "正确。届时指到了前面说的六月开放参观的那个时候，家长届时可以进来。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从过去到现在一向如此，不能指将来“六月开放参观”的那个时候。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去有过的经历，与“六月开放”的将来时间冲突。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带做某事，不指到了约定的时间，句意不通。"}], "explanations": {"届时": "正确。届时指到了前面说的六月开放参观的那个时候，家长届时可以进来。", "从来": "语义：“从来”表示从过去到现在一向如此，不能指将来“六月开放参观”的那个时候。", "曾经": "语义：“曾经”指过去有过的经历，与“六月开放”的将来时间冲突。", "顺便": "语义：“顺便”表示附带做某事，不指到了约定的时间，句意不通。"}, "sentence_index": 6, "correct_answer": "届时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我小时候一直住在农村，届时每天都要走很远的路去上学。", "explanation": "这里应该用〈那时〉。届时指到了某个将来的时间，不能用来说过去一直持续的情况；讲过去的事要用那时。"}, {"text": "他先说了很多理由，届时同意了我们的方案。", "explanation": "这里应该用〈最后〉。届时指到了前面说定的时间，不能表示经过一番过程之后得出的结果。"}, {"text": "我们先去了公园，届时去了超市。", "explanation": "这里应该用〈后来〉。届时表示到了某个预定的时间，不表示先后发生的两件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考试在下周一进行，届时了请大家带好准考证。", "corrected_sentence": "考试在下周一进行，届时请大家带好准考证。", "error_description": "错误形式：“届时了”，正确形式：“届时”。“届时”本身表示将来的时间，不能再加助词“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆周三闭馆，届时的时候请大家提前还书。", "corrected_sentence": "图书馆周三闭馆，届时请大家提前还书。", "error_description": "错误形式：“届时的时候”，正确形式：“届时”。“届时”本身已包含“到了那个时候”的意思，后面不能再加“的时候”，否则意思重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
