INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92021, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "走你是大家一起出发时喊的话。", "primary_collocate": null, "pronunciation": "zǒu nǐ", "ipa": "tsou˧˥ ni˨˩", "syllable_count": 2, "sentences": [{"text": "老师一挥手：“同学们，走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家站在门口，一起喊：“走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队上场前，队长大声喊了一句“走你”。", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人都上车了，爸爸笑着说：“走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮了，我们背上包，走你！", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们到了山脚下，小张喊：“走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一喊“走你”，朋友们就跟着他出门了。", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开了，大家都笑着说：“走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们排好队，班长说：“走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到那声“走你”，孩子们都跑了出去。", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "大家一起出发时喊的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2bbdfe-45ed-43d8-ab7a-6e76fe728753') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示疑惑，老师挥手招呼时并不是在提问。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：“哎哟”表示疼痛或惊讶，与招呼同学出发无关。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”表示唾弃或轻蔑，语气粗鲁，老师不会对同学这样说。"}, {"text": "走你", "is_correct": true, "explanation": "正确。老师挥手招呼同学一起出发，“走你”与情境相符。"}], "explanations": {"咦": "语义：“咦”表示疑惑，老师挥手招呼时并不是在提问。", "哎哟": "语义：“哎哟”表示疼痛或惊讶，与招呼同学出发无关。", "呸": "语域：“呸”表示唾弃或轻蔑，语气粗鲁，老师不会对同学这样说。", "走你": "正确。老师挥手招呼同学一起出发，“走你”与情境相符。"}, "sentence_index": 0, "correct_answer": "走你"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "收到礼物，我说：走你！", "explanation": "这里应该用〈谢谢〉。“走你”是招呼大家一起出发，不用于道谢。"}, {"text": "不小心踩到你的脚，我连忙说：走你。", "explanation": "这里应该用〈对不起〉。“走你”是招呼一起出发的话，不用于道歉。"}, {"text": "走你，桌子上怎么多了一本书？", "explanation": "这里应该用〈咦〉。“走你”表示招呼出发，不表示疑惑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”是示意安静，喊它不会让朋友们跟着出门。"}, {"text": "呃", "is_correct": false, "explanation": "语义：“呃”表示迟疑或打嗝，不是召集大家出门的话。"}, {"text": "哈哈", "is_correct": false, "explanation": "语域：“哈哈”是笑声拟声词，不能用作召集朋友出门的话。"}, {"text": "走你", "is_correct": true, "explanation": "正确。“走你”是召集大家一起出发的叹词，与“朋友们就跟着他出门了”相符。"}], "explanations": {"嘘": "语义：“嘘”是示意安静，喊它不会让朋友们跟着出门。", "呃": "语义：“呃”表示迟疑或打嗝，不是召集大家出门的话。", "哈哈": "语域：“哈哈”是笑声拟声词，不能用作召集朋友出门的话。", "走你": "正确。“走你”是召集大家一起出发的叹词，与“朋友们就跟着他出门了”相符。"}, "sentence_index": 6, "correct_answer": "走你"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚上睡前，妈妈说：走你，做个好梦。", "explanation": "这里应该用〈晚安〉。“走你”是招呼一起出发，不用于睡前道别。"}, {"text": "他考上了大学，大家说：走你，你真棒！", "explanation": "这里应该用〈恭喜〉。“走你”是招呼一起出发，不用于祝贺。"}, {"text": "老师问我答案，我摇摇头说：走你。", "explanation": "这里应该用〈不知道〉。“走你”是招呼一起出发的话，不能用来表示不清楚答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车到了，要走你！", "corrected_sentence": "车到了，走你！", "error_description": "“走你”是叹词，前面不能加能愿动词“要”。应说“车到了，走你！”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚饭好了，大家笑着说：“走你吗？”", "corrected_sentence": "晚饭好了，大家笑着说：“走你！”", "error_description": "“走你”是叹词，不能带疑问语气词“吗”。应说“晚饭好了，大家笑着说：“走你！””。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
