INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92022, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "口语，表示催促或招呼对方一起出发、行动，带有轻松玩笑的语气。", "primary_collocate": null, "pronunciation": "zǒu nǐ", "ipa": "tsou˧˥ ni˨˩", "syllable_count": 2, "sentences": [{"text": "车来了，大家上车，走你！", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好了，朋友们，走你，去吃饭！", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起包笑着说：“走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影快开始了，我们快点儿，走你！", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "准备好了吗？好，走你！", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看大家都到齐了，小王大声说：“走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末去爬山，我喊了一声“走你”，大家就出发了。", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李都放好了，司机说：“好了，走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们笑着喊：“去玩吧，走你！”", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到他说“走你”，我们都拿起包往外走。", "target_word": "走你", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "轻松玩笑地催促招呼一起出发", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2bbdfe-45ed-43d8-ab7a-6e76fe728753') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哎哟", "is_correct": false, "explanation": "语义：“哎哟”表示疼痛或惊讶，不是招呼大家一起上车出发。"}, {"text": "走你", "is_correct": true, "explanation": "正确。叹词“走你”招呼大家一起出发，与“车来了，大家上车”的情境相符。"}, {"text": "嘿嘿", "is_correct": false, "explanation": "语域：“嘿嘿”是笑声拟声词，不能用作招呼大家行动的话。"}, {"text": "谢谢", "is_correct": false, "explanation": "语义：“谢谢”表示感谢，与催促大家上车无关。"}], "explanations": {"哎哟": "语义：“哎哟”表示疼痛或惊讶，不是招呼大家一起上车出发。", "走你": "正确。叹词“走你”招呼大家一起出发，与“车来了，大家上车”的情境相符。", "嘿嘿": "语域：“嘿嘿”是笑声拟声词，不能用作招呼大家行动的话。", "谢谢": "语义：“谢谢”表示感谢，与催促大家上车无关。"}, "sentence_index": 0, "correct_answer": "走你"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朋友进门，我笑着说：走你，快坐下。", "explanation": "这里应该用〈欢迎〉。“走你”是招呼大家一起出发，不用来迎接来客。"}, {"text": "朋友送我一本书，我笑着说：走你。", "explanation": "这里应该用〈谢谢〉。“走你”是招呼一起出发的话，不用于道谢。"}, {"text": "走你，我的脚好疼！", "explanation": "这里应该用〈哎哟〉。“走你”只表示催促出发，不表示疼痛或惊讶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对不起", "is_correct": false, "explanation": "语义：“对不起”是道歉，喊出来并不能让大家跟着出发。"}, {"text": "哈哈", "is_correct": false, "explanation": "语域：“哈哈”是笑声，不是招呼大家出发的话。"}, {"text": "唉", "is_correct": false, "explanation": "语义：“唉”表示叹气或无奈，与招呼大家出发无关。"}, {"text": "走你", "is_correct": true, "explanation": "正确。“走你”是招呼大家一起出发的叹词，与“大家就出发了”相符。"}], "explanations": {"对不起": "语义：“对不起”是道歉，喊出来并不能让大家跟着出发。", "哈哈": "语域：“哈哈”是笑声，不是招呼大家出发的话。", "唉": "语义：“唉”表示叹气或无奈，与招呼大家出发无关。", "走你": "正确。“走你”是招呼大家一起出发的叹词，与“大家就出发了”相符。"}, "sentence_index": 6, "correct_answer": "走你"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我挂电话前说：走你。", "explanation": "这里应该用〈再见〉。“走你”是招呼一起出发的话，不用于告别。"}, {"text": "晚上睡前，妈妈说：走你，做个好梦。", "explanation": "这里应该用〈晚安〉。“走你”是招呼一起出发，不用于睡前道别。"}, {"text": "老师问我答案，我摇摇头说：走你。", "explanation": "这里应该用〈不知道〉。“走你”是招呼一起出发的话，不能用来表示不清楚答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "东西都收拾好了，走你了！", "corrected_sentence": "东西都收拾好了，走你！", "error_description": "“走你”是叹词，不能带动态助词“了”。应去掉“了”，说“东西都收拾好了，走你！”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作业写完了，走你的！", "corrected_sentence": "作业写完了，走你！", "error_description": "“走你”是叹词，后面不能加结构助词“的”。应说“作业写完了，走你！”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
