INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92023, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "展出是把东西摆出来让大家看。", "primary_collocate": null, "pronunciation": "zhǎn chū", "ipa": "ʈʂan˨˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "博物馆里展出了很多古代的画。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末，学校展出同学们的作品。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的照片将在市图书馆展出。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件宝贵的玉器第一次公开展出。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画展上展出的画都很漂亮。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们把自己做的手工放在教室里展出。", "target_word": "展出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些老照片展出了一个星期。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新车今天在车展上展出。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次展览展出过一百多件瓷器。", "target_word": "展出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美术馆正在展出一位老画家的作品。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "展出了", "label": "体标"}, {"form": "展出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把作品或物品摆出来给大家看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbb1089a-7f0e-4a1d-9b64-4094ab18e718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92023, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "展出", "is_correct": true, "explanation": "正确：“展出”指把画等物品公开陈列，与“博物馆里”和“古代的画”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：画不能被“吃”，句子说的是可以供人观看的物品。"}, {"text": "唱", "is_correct": false, "explanation": "语义：画不会“唱”，句中的对象是可以观看的画作。"}, {"text": "举行", "is_correct": false, "explanation": "搭配：“举行”搭配活动、仪式，不能用于“画”。"}], "explanations": {"展出": "正确：“展出”指把画等物品公开陈列，与“博物馆里”和“古代的画”搭配。", "吃": "语义：画不能被“吃”，句子说的是可以供人观看的物品。", "唱": "语义：画不会“唱”，句中的对象是可以观看的画作。", "举行": "搭配：“举行”搭配活动、仪式，不能用于“画”。"}, "sentence_index": 0, "correct_answer": "展出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中展出了自己的才华。", "explanation": "这里应该用〈展示〉。展出指把物品公开陈列，不能用于抽象的才华。"}, {"text": "他的论文去年在杂志上展出了。", "explanation": "这里应该用〈发表〉。论文要发表在杂志上，不能说“展出”。"}, {"text": "这部话剧下周在剧场展出。", "explanation": "这里应该用〈演出〉。话剧是表演，要说“演出”，不能说“展出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92023, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展出", "is_correct": true, "explanation": "正确：“展出”可指照片公开陈列一段时间，与“了”和“一个星期”搭配。"}, {"text": "生病", "is_correct": false, "explanation": "语义：照片不会生病，句子说的是陈列。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：照片不会睡觉，不能用于这样的句子。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”只用于人或动物，不能用于照片。"}], "explanations": {"展出": "正确：“展出”可指照片公开陈列一段时间，与“了”和“一个星期”搭配。", "生病": "语义：照片不会生病，句子说的是陈列。", "睡觉": "语义：照片不会睡觉，不能用于这样的句子。", "出生": "搭配：“出生”只用于人或动物，不能用于照片。"}, "sentence_index": 6, "correct_answer": "展出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视台每晚都在展出新闻节目。", "explanation": "这里应该用〈播放〉。电视节目是播放的，不能说“展出”。"}, {"text": "老师在课堂上展出课文。", "explanation": "这里应该用〈朗读〉。课文要朗读，不能说“展出”。"}, {"text": "这部电影下个月在影院展出。", "explanation": "这里应该用〈上映〉。电影在影院上映，不能说“展出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政厅的大厅里了展出一批老地图。", "corrected_sentence": "市政厅的大厅里展出一批老地图。", "error_description": "错误：“了”不能插在地点状语“市政厅的大厅里”与动词“展出”之间。正确：删去“了”，即“展出一批老地图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "美术馆明天展出了一位老画家的作品。", "corrected_sentence": "美术馆明天展出一位老画家的作品。", "error_description": "错误：“明天……展出了”。正确：“明天展出”。说将来的事不用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
