INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92024, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开陈列出来供人观看。", "primary_collocate": null, "pronunciation": "zhǎn chū", "ipa": "ʈʂan˨˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "商场大厅里正在展出最新的手机。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画明天开始在美术馆展出。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "展览会上展出了许多新产品。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的作品曾经在国外展出过。", "target_word": "展出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的博物馆经常展出文物。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画家把新画送到展厅里展出。", "target_word": "展出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些画从五月到七月都会展出。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的画要在一个大房子里展出。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次花展展出了三百多种花。", "target_word": "展出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生的画在走廊里展出，同学们都来看。", "target_word": "展出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "展出了", "label": "体标"}, {"form": "展出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "在展厅、展会等场所公开陈列供人参观", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbb1089a-7f0e-4a1d-9b64-4094ab18e718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92024, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "展出", "is_correct": true, "explanation": "正确：“展出”指在大厅里陈列物品供人观看，与“正在”和“最新的手机”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：手机不能被“吃”，句子说的是陈列。"}, {"text": "放牧", "is_correct": false, "explanation": "语义：放牧的对象是牲畜，手机不能被放牧。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”搭配文件、照片，不能用于“手机”。"}], "explanations": {"展出": "正确：“展出”指在大厅里陈列物品供人观看，与“正在”和“最新的手机”搭配。", "吃": "语义：手机不能被“吃”，句子说的是陈列。", "放牧": "语义：放牧的对象是牲畜，手机不能被放牧。", "打印": "搭配：“打印”搭配文件、照片，不能用于“手机”。"}, "sentence_index": 0, "correct_answer": "展出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在台上展出了一个漂亮的舞步。", "explanation": "这里应该用〈展示〉。展出用于陈列物品供人参观，舞步不能展出。"}, {"text": "这本小说去年展出了。", "explanation": "这里应该用〈出版〉。小说是文字作品，要说“出版”，不能说“展出”。"}, {"text": "这部电影去年在全国展出。", "explanation": "这里应该用〈上映〉。电影要上映，不能说“展出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展出", "is_correct": true, "explanation": "正确：“展出”指画作在一段时间内公开陈列，与“都会”和“从五月到七月”搭配。"}, {"text": "生长", "is_correct": false, "explanation": "语义：画不会生长，句子说的是陈列。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“这些画”不能作“下雨”的主语，句子说的是展示。"}, {"text": "播出", "is_correct": false, "explanation": "搭配：“播出”用于电视节目等，不能用于画。"}], "explanations": {"展出": "正确：“展出”指画作在一段时间内公开陈列，与“都会”和“从五月到七月”搭配。", "生长": "语义：画不会生长，句子说的是陈列。", "下雨": "语义：“这些画”不能作“下雨”的主语，句子说的是展示。", "播出": "搭配：“播出”用于电视节目等，不能用于画。"}, "sentence_index": 6, "correct_answer": "展出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "广播电台每天展出天气预报。", "explanation": "这里应该用〈播放〉。天气预报要播放，不能说“展出”。"}, {"text": "妈妈每天晚上给孩子展出一个故事。", "explanation": "这里应该用〈讲〉。故事是讲给人听的，不能说“展出”。"}, {"text": "剧团的新剧下周在剧场展出。", "explanation": "这里应该用〈演出〉。话剧是表演，要说“演出”，不能说“展出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "艺术中心的一楼正在展出了儿童画。", "corrected_sentence": "艺术中心的一楼正在展出儿童画。", "error_description": "错误：“正在……展出了”。正确：“正在展出”。“正在”表示进行，与“了”不能同时使用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
