INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92025, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为办理公务、工作、任职或学习等正事而前往某地。", "primary_collocate": null, "pronunciation": "fù", "ipa": "fu˥˩", "syllable_count": 1, "sentences": [{"text": "他明天赴北京出差。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我下个月要赴上海工作。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲昨天赴广州出差了。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师下周赴日本学习。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后赴英国读书。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理今晚赴成都开会。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李已经赴西安任职了。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下个月赴海南任教。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥去年赴德国工作。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张医生明天一早赴山区看病人。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "去某个地方做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92025, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赴", "is_correct": true, "explanation": "赴 fù（第四声）是“前往某个地方做事”，即本词的读音和意思。"}, {"text": "服", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是衣服、服从，不是赴。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫，不是赴。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是政府、府第，不是赴。"}], "explanations": {"赴": "赴 fù（第四声）是“前往某个地方做事”，即本词的读音和意思。", "服": "fú（第二声）与 fù（第四声）声调不同，意思是衣服、服从，不是赴。", "夫": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫，不是赴。", "府": "fǔ（第三声）与 fù（第四声）声调不同，意思是政府、府第，不是赴。"}, "sentence_index": null, "correct_answer": "赴"}, "level_3": {"options": [{"text": "赴", "is_correct": true, "explanation": "赴是“前往某地”，与“去北京出差”相符，是正确答案。"}, {"text": "迁往", "is_correct": false, "explanation": "语义：“迁往”指长久搬到某地，与“出差”的短期前往矛盾。"}, {"text": "定居", "is_correct": false, "explanation": "语义：“定居”指在某地长期住下来，与“出差”不符。"}, {"text": "驻守", "is_correct": false, "explanation": "搭配：“驻守”多指军队或人员长期守卫某地，不能用于出差。"}], "explanations": {"赴": "赴是“前往某地”，与“去北京出差”相符，是正确答案。", "迁往": "语义：“迁往”指长久搬到某地，与“出差”的短期前往矛盾。", "定居": "语义：“定居”指在某地长期住下来，与“出差”不符。", "驻守": "搭配：“驻守”多指军队或人员长期守卫某地，不能用于出差。"}, "sentence_index": 0, "correct_answer": "赴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我周末赴公园散步。", "explanation": "这里应该用〈去〉。赴偏书面，多指为正事前往；周末去公园散步属于闲逛，口语用〈去〉。"}, {"text": "我妈妈每天赴菜市场买菜。", "explanation": "这里应该用〈去〉。赴是书面语，买菜这类日常琐事用〈去〉更自然。"}, {"text": "同学们周末赴我家玩游戏。", "explanation": "这里应该用〈来〉。赴带有正式前往的色彩，同学到家里玩用〈来〉更自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92025, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赴", "is_correct": true, "explanation": "赴 fù（第四声）是“前往某个地方做事”，即本词的读音和意思。"}, {"text": "扶", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是搀扶，不是赴。"}, {"text": "符", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是符号、相符，不是赴。"}, {"text": "辅", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是辅助，不是赴。"}], "explanations": {"赴": "赴 fù（第四声）是“前往某个地方做事”，即本词的读音和意思。", "扶": "fú（第二声）与 fù（第四声）声调不同，意思是搀扶，不是赴。", "符": "fú（第二声）与 fù（第四声）声调不同，意思是符号、相符，不是赴。", "辅": "fǔ（第三声）与 fù（第四声）声调不同，意思是辅助，不是赴。"}, "sentence_index": null, "correct_answer": "赴"}, "level_3": {"options": [{"text": "赴", "is_correct": true, "explanation": "赴是“前往某地任职”，与“西安任职”相符，是正确答案。"}, {"text": "逃往", "is_correct": false, "explanation": "语义：“逃往”含有逃避之意，与正式的任职安排不符。"}, {"text": "流落", "is_correct": false, "explanation": "语义：“流落”指穷困漂泊，与“任职”的正式安排矛盾。"}, {"text": "滞留", "is_correct": false, "explanation": "语义：“滞留”指因故无法离开，与“已经任职”的结果相冲突。"}], "explanations": {"赴": "赴是“前往某地任职”，与“西安任职”相符，是正确答案。", "逃往": "语义：“逃往”含有逃避之意，与正式的任职安排不符。", "流落": "语义：“流落”指穷困漂泊，与“任职”的正式安排矛盾。", "滞留": "语义：“滞留”指因故无法离开，与“已经任职”的结果相冲突。"}, "sentence_index": 6, "correct_answer": "赴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天赴地铁上班，很方便。", "explanation": "这里应该用〈坐〉。赴只表示前往某处，乘坐交通工具要用〈坐〉或〈乘〉，不能说“赴地铁”。"}, {"text": "我赴了一封信给朋友。", "explanation": "这里应该用〈寄〉。赴表示前往，寄信要用〈寄〉，不能用“赴”来表示寄送。"}, {"text": "我中午赴了一碗面。", "explanation": "这里应该用〈吃〉。赴表示前往某处，不表示吃东西，吃面要用〈吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下周赴了成都参加会议。", "corrected_sentence": "我下周赴成都参加会议。", "error_description": "错误在“赴了”：“下周”是将来的时间，动词后不能加“了”。应说“下周赴成都”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天赴去南京开会。", "corrected_sentence": "我们明天赴南京开会。", "error_description": "“赴”本身就是“前往”的意思，后面不能再加“去”。应删去“去”，说“明天赴南京开会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
