INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92026, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "前往；到某处去。", "primary_collocate": null, "pronunciation": "fù", "ipa": "fu˥˩", "syllable_count": 1, "sentences": [{"text": "代表团今天赴北京参加会议。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长下周赴美国访问。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者连夜赴灾区采访。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援队接到电话，马上赴现场。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理今早赴深圳谈合作。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队明天赴杭州比赛。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们已赴前线救人。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外交部长今天赴韩国访问。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家组昨天赴当地检查。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长赴学校看望老师。", "target_word": "赴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "正式地前往某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92026, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赴", "is_correct": true, "explanation": "赴 fù（第四声）是“正式前往某处”，即本词的读音和意思。"}, {"text": "服", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是衣服、服从，不是赴。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫，不是赴。"}, {"text": "护", "is_correct": false, "explanation": "声母 h 与 f 不同，hù（第四声）意思是保护，不是赴。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是政府、府第，不是赴。"}], "explanations": {"赴": "赴 fù（第四声）是“正式前往某处”，即本词的读音和意思。", "服": "fú（第二声）与 fù（第四声）声调不同，意思是衣服、服从，不是赴。", "夫": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫，不是赴。", "护": "声母 h 与 f 不同，hù（第四声）意思是保护，不是赴。", "府": "fǔ（第三声）与 fù（第四声）声调不同，意思是政府、府第，不是赴。"}, "sentence_index": null, "correct_answer": "赴"}, "level_3": {"options": [{"text": "赴", "is_correct": true, "explanation": "赴是“正式前往某地”，与“北京参加会议”相符，是正确答案。"}, {"text": "迁往", "is_correct": false, "explanation": "语义：“迁往”指长久搬到某地，与“参加会议”的短期前往矛盾。"}, {"text": "驻守", "is_correct": false, "explanation": "搭配：“驻守”多指军队长期守卫某地，不能用于参加会议。"}, {"text": "撤离", "is_correct": false, "explanation": "语义：“撤离”是离开某地，与“前往北京参加会议”的方向相反。"}], "explanations": {"赴": "赴是“正式前往某地”，与“北京参加会议”相符，是正确答案。", "迁往": "语义：“迁往”指长久搬到某地，与“参加会议”的短期前往矛盾。", "驻守": "搭配：“驻守”多指军队长期守卫某地，不能用于参加会议。", "撤离": "语义：“撤离”是离开某地，与“前往北京参加会议”的方向相反。"}, "sentence_index": 0, "correct_answer": "赴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我赴朋友家玩。", "explanation": "这里应该用〈去〉。赴偏书面，指为正事前往；周末到朋友家玩用〈去〉。"}, {"text": "我下班后赴菜市场买菜。", "explanation": "这里应该用〈去〉。买菜属于日常琐事，口语用〈去〉更自然。"}, {"text": "我们明天赴公园野餐。", "explanation": "这里应该用〈去〉。赴带有正式或有任务的色彩，公园野餐用〈去〉更自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92026, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赴", "is_correct": true, "explanation": "赴 fù（第四声）是“正式前往某处”，即本词的读音和意思。"}, {"text": "扶", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是搀扶，不是赴。"}, {"text": "符", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是符号、相符，不是赴。"}, {"text": "辅", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是辅助，不是赴。"}, {"text": "互", "is_correct": false, "explanation": "声母 h 与 f 不同，hù（第四声）意思是相互，不是赴。"}], "explanations": {"赴": "赴 fù（第四声）是“正式前往某处”，即本词的读音和意思。", "扶": "fú（第二声）与 fù（第四声）声调不同，意思是搀扶，不是赴。", "符": "fú（第二声）与 fù（第四声）声调不同，意思是符号、相符，不是赴。", "辅": "fǔ（第三声）与 fù（第四声）声调不同，意思是辅助，不是赴。", "互": "声母 h 与 f 不同，hù（第四声）意思是相互，不是赴。"}, "sentence_index": null, "correct_answer": "赴"}, "level_3": {"options": [{"text": "赴", "is_correct": true, "explanation": "赴是“前往前线”，与“救人”的行动相符，是正确答案。"}, {"text": "逃往", "is_correct": false, "explanation": "语义：“逃往”含有逃避之意，与“前线救人”的行动矛盾。"}, {"text": "定居", "is_correct": false, "explanation": "语义：“定居”指长期住下，与“前线救人”的临时行动不符。"}, {"text": "流落", "is_correct": false, "explanation": "语义：“流落”指穷困漂泊，与“前线救人”的主动行动矛盾。"}], "explanations": {"赴": "赴是“前往前线”，与“救人”的行动相符，是正确答案。", "逃往": "语义：“逃往”含有逃避之意，与“前线救人”的行动矛盾。", "定居": "语义：“定居”指长期住下，与“前线救人”的临时行动不符。", "流落": "语义：“流落”指穷困漂泊，与“前线救人”的主动行动矛盾。"}, "sentence_index": 6, "correct_answer": "赴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她今天赴了一件红裙子。", "explanation": "这里应该用〈穿〉。赴表示前往，不表示穿衣服，穿裙子要用〈穿〉。"}, {"text": "他赴了一封信给老师。", "explanation": "这里应该用〈寄〉。赴表示前往，寄信要用〈寄〉，不能用“赴”来表示寄送。"}, {"text": "我昨天赴了一杯咖啡。", "explanation": "这里应该用〈喝〉。赴表示前往某处，不表示喝饮料，喝咖啡要用〈喝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长下个月赴了日本考察。", "corrected_sentence": "校长下个月赴日本考察。", "error_description": "错误在“赴了”：“下个月”指将来，动词后不能加“了”。应说“下个月赴日本”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "代表团下周赴了深圳考察。", "corrected_sentence": "代表团下周赴深圳考察。", "error_description": "错误在“赴了”：“下周”指将来，还没发生，动词“赴”后不能加“了”。去掉“了”，说“下周赴深圳考察”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
