INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92027, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "巨额是钱的数目特别大。", "primary_collocate": null, "pronunciation": "jù é", "ipa": "tɕy˥˩ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他中了彩票，得到了一笔巨额奖金。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有巨额债务，很难继续做下去。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他留给孩子们巨额财产。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行发现他的账户里有巨额存款。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司去年赚了巨额利润。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了买下这块地，老板花了巨额资金。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了给妈妈治病，借了巨额款项。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的修建需要巨额投资。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院让他交巨额罚款。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巨额的医药费让这个家庭的生活变得很困难。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巨額", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容词：钱的数目特别大，多修饰奖金、债务、财产等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552319c8-d678-4547-b1ce-dbccda73abfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巨额", "is_correct": true, "explanation": "正确：“巨额”形容钱的数目很大，与“一笔……奖金”搭配。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，不能修饰奖金的数目。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或体形，不能说“瘦奖金”。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄，不能修饰奖金。"}], "explanations": {"巨额": "正确：“巨额”形容钱的数目很大，与“一笔……奖金”搭配。", "热情": "语义：“热情”形容人的态度，不能修饰奖金的数目。", "瘦": "体貌：“瘦”形容人或体形，不能说“瘦奖金”。", "年轻": "语义：“年轻”说年龄，不能修饰奖金。"}, "sentence_index": 0, "correct_answer": "巨额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的巨额面积让人惊讶。", "explanation": "这里应该用〈巨大〉。巨额只修饰钱款数目，形容面积等空间的大要用巨大。"}, {"text": "这次活动吸引了巨额观众。", "explanation": "这里应该用〈大量〉。巨额只修饰钱款，观众等人数要用大量。"}, {"text": "他背着巨额的包，走得很慢。", "explanation": "这里应该用〈沉重〉。巨额只修饰钱款，形容包的分量要用沉重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巨额", "is_correct": true, "explanation": "正确：“巨额”形容款项数目很大，与“借了”搭配。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能形容款项。"}, {"text": "高挑", "is_correct": false, "explanation": "体貌：“高挑”形容人的身材，不能用于款项。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容山坡等地形，与“款项”不搭配。"}], "explanations": {"巨额": "正确：“巨额”形容款项数目很大，与“借了”搭配。", "清脆": "语义：“清脆”形容声音，不能形容款项。", "高挑": "体貌：“高挑”形容人的身材，不能用于款项。", "陡峭": "搭配：“陡峭”形容山坡等地形，与“款项”不搭配。"}, "sentence_index": 6, "correct_answer": "巨额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有巨额的经验，很快就解决了问题。", "explanation": "这里应该用〈丰富〉。巨额只用于钱款数目，说经验多要用丰富。"}, {"text": "他递给我一把巨额的刀。", "explanation": "这里应该用〈锋利〉。巨额只用于数额，形容刀的锋利要用锋利。"}, {"text": "他有一个巨额的理想，想改变世界。", "explanation": "这里应该用〈宏大〉。巨额只用于钱款，理想的规模要用宏大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去世后，家人继承了巨额地财产。", "corrected_sentence": "他去世后，家人继承了巨额的财产。", "error_description": "结构助词错误：“巨额”修饰名词“财产”时可加“的”（也可直接接名词），不能用“地”（“地”用于修饰动词）。错误形式是“巨额地财产”，正确形式是“巨额的财产”或“巨额财产”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把一笔巨额了资金捐给了学校。", "corrected_sentence": "她把一笔巨额资金捐给了学校。", "error_description": "助词错误：“巨额”是形容词，修饰“资金”时后面不能加“了”。错误形式是“一笔巨额了资金”，正确形式是“一笔巨额资金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
