INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92028, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "数额特别巨大的。", "primary_collocate": null, "pronunciation": "jù é", "ipa": "tɕy˥˩ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这家工厂每年要交巨额税款。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他欠了朋友一笔巨额债务，一直还不上。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家花了巨额军费。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给了这位明星巨额的酬金。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把巨额遗产送给了学校。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的巨额奖金吸引了很多人。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为拿了巨额回扣，受到了处罚。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子要借巨额贷款，很多年轻人不敢买。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司亏了巨额资金，老板很着急。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行借给他一笔巨额贷款。", "target_word": "巨额", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巨額", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容词：数额特别巨大的，多用于钱款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552319c8-d678-4547-b1ce-dbccda73abfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巨额", "is_correct": true, "explanation": "正确：“巨额”形容税款的数额特别大，与“交……税款”搭配。"}, {"text": "温和", "is_correct": false, "explanation": "语义：“温和”形容性情或气候，不能修饰税款。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃等，与“税款”不搭配。"}, {"text": "高挑", "is_correct": false, "explanation": "体貌：“高挑”形容人的身材，不能用于税款。"}], "explanations": {"巨额": "正确：“巨额”形容税款的数额特别大，与“交……税款”搭配。", "温和": "语义：“温和”形容性情或气候，不能修饰税款。", "锋利": "搭配：“锋利”形容刀刃等，与“税款”不搭配。", "高挑": "体貌：“高挑”形容人的身材，不能用于税款。"}, "sentence_index": 0, "correct_answer": "巨额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个王国有巨额的疆域。", "explanation": "这里应该用〈辽阔〉。巨额只用于数额，说疆域等空间范围要用辽阔。"}, {"text": "这所学校收到了巨额来信。", "explanation": "这里应该用〈大量〉。巨额只修饰钱款，来信的数量要用大量。"}, {"text": "这是一声巨额的鸟叫。", "explanation": "这里应该用〈清脆〉。巨额只用于数额，形容声音要用清脆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巨额", "is_correct": true, "explanation": "正确：“巨额”形容回扣的数额特别大，与“拿了……回扣”搭配。"}, {"text": "圆润", "is_correct": false, "explanation": "体貌：“圆润”形容声音或形状，不能用于回扣。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或颜色，不能修饰回扣。"}, {"text": "短暂", "is_correct": false, "explanation": "搭配：“短暂”说时间的长短，不能修饰回扣的数目。"}], "explanations": {"巨额": "正确：“巨额”形容回扣的数额特别大，与“拿了……回扣”搭配。", "圆润": "体貌：“圆润”形容声音或形状，不能用于回扣。", "明亮": "语义：“明亮”形容光线或颜色，不能修饰回扣。", "短暂": "搭配：“短暂”说时间的长短，不能修饰回扣的数目。"}, "sentence_index": 6, "correct_answer": "巨额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有巨额的头脑，很快就解决了问题。", "explanation": "这里应该用〈聪明〉。巨额只用于数额，形容头脑的敏捷要用聪明。"}, {"text": "他递给我一把巨额的刀。", "explanation": "这里应该用〈锋利〉。巨额只用于数额，形容刀的锋利要用锋利。"}, {"text": "他迈着巨额的步伐走进了房间。", "explanation": "这里应该用〈沉重〉。巨额只用于钱款，形容步伐的分量要用沉重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂每年都要缴纳巨额地税款。", "corrected_sentence": "这家工厂每年都要缴纳巨额的税款。", "error_description": "结构助词错误：“巨额”修饰名词“税款”时可加“的”（也可直接接名词），不能用“地”（“地”用于修饰动词）。错误形式是“巨额地税款”，正确形式是“巨额的税款”或“巨额税款”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向银行申请了一笔巨额了抵押贷款。", "corrected_sentence": "他向银行申请了一笔巨额抵押贷款。", "error_description": "助词错误：“巨额”是形容词，修饰“抵押贷款”时后面不能加“了”。错误形式是“巨额了抵押贷款”，正确形式是“巨额抵押贷款”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
