INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92029, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军人是在军队里保护国家的人。", "primary_collocate": null, "pronunciation": "jūn rén", "ipa": "tɕyn˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "军人要保护国家和人民。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷年轻时是一名军人。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位军人站得很直。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当军人。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人每天早上都要训练。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到军人，孩子们都向他们敬礼。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着军装，一看就是军人。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人的家人常常想念他。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，军人还在门口站岗。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家有困难的时候，军人会第一个去帮忙。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "退役军人", "label": "复合"}, {"form": "軍人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在军队里保护国家的人，日常口语和普通叙述中的“军人”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "军人", "is_correct": true, "explanation": "军人有保护国家和人民的职责，符合句意。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷不承担保护国家和人民的职责，与句意矛盾。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不会保护国家和人民，句意荒谬。"}, {"text": "玻璃", "is_correct": false, "explanation": "配价：“保护”需要有能动性的施事，玻璃不能充当主语。"}], "explanations": {"军人": "军人有保护国家和人民的职责，符合句意。", "小偷": "语义：小偷不承担保护国家和人民的职责，与句意矛盾。", "老鼠": "语义：老鼠不会保护国家和人民，句意荒谬。", "玻璃": "配价：“保护”需要有能动性的施事，玻璃不能充当主语。"}, "sentence_index": 0, "correct_answer": "军人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我认识一棵军人，他很厉害。", "explanation": "这里应该用〈名〉。棵用于树木，人要用“名”或“位”。"}, {"text": "我家的狗是一名军人。", "explanation": "这里应该用〈军犬〉。军人指人，不能用来称动物。"}, {"text": "他今年是一座军人，每天都在训练。", "explanation": "这里应该用〈名〉。座用于山、桥、建筑等大型固定物，指人要用“名”或“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军人", "is_correct": true, "explanation": "军人与“穿着军装”一致，句意通顺。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：穿着军装不会一看就是厨师，与前文矛盾。"}, {"text": "医生", "is_correct": false, "explanation": "体貌：医生的标志是白大褂，与“军装”不符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：穿军装的人不会一看就是农民，句意冲突。"}], "explanations": {"军人": "军人与“穿着军装”一致，句意通顺。", "厨师": "语义：穿着军装不会一看就是厨师，与前文矛盾。", "医生": "体貌：医生的标志是白大褂，与“军装”不符。", "农民": "语义：穿军装的人不会一看就是农民，句意冲突。"}, "sentence_index": 6, "correct_answer": "军人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在超市买了一个军人。", "explanation": "这里应该用〈商品〉。买的是商品，军人指人员，不能作买卖的对象。"}, {"text": "我们去了军人，玩了一整天。", "explanation": "这里应该用〈军营〉。军人指人员，不能作为去的地方。"}, {"text": "他今天穿着军人，看起来很神气。", "explanation": "这里应该用〈军装〉。穿的是衣服，军人指人员，不能作“穿”的对象，应说“穿着军装”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一位退役的军人们。", "corrected_sentence": "他是一位退役的军人。", "error_description": "复数标记错误：“们”不能与“一位”这样的数量词同时出现，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只年轻的军人站在门口。", "corrected_sentence": "一位年轻的军人站在门口。", "error_description": "量词错误：“只”用于动物及单个小物件，指人应用“位”或“名”，应说“一位年轻的军人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
