INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在军队中服役的人员。", "primary_collocate": null, "pronunciation": "jūn rén", "ipa": "tɕyn˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "现役军人可以免费乘坐这趟车。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人必须服从命令。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他服役十年，是一名优秀的军人。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为军人，他们必须遵守严格的纪律。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位军人退役后回到了家乡。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人的工资由国家发放。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的军人要先学习条例。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对军人家属有特别的照顾。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人在军营里过着规律的生活。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次招募军人，要先通过体检。", "target_word": "军人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "现役军人", "label": "复合"}, {"form": "軍人", "label": "繁体"}], "register": "书面", "sense_fingerprint": "在军队中服役的人员，强调服役身份与纪律，用于较正式的语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "军人", "is_correct": true, "explanation": "现役军人可以享受这一优待，符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不属于现役人员，与“现役”冲突。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人一般已退役或退休，不能称“现役”。"}, {"text": "病毒", "is_correct": false, "explanation": "搭配：“现役”修饰的应是人员，病毒不能与之搭配。"}], "explanations": {"军人": "现役军人可以享受这一优待，符合句意。", "学生": "语义：学生不属于现役人员，与“现役”冲突。", "老人": "语义：老人一般已退役或退休，不能称“现役”。", "病毒": "搭配：“现役”修饰的应是人员，病毒不能与之搭配。"}, "sentence_index": 0, "correct_answer": "军人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们连队来了一张军人。", "explanation": "这里应该用〈名〉。张用于平面的东西，人要用“名”或“位”。"}, {"text": "他们把伤员送到了军人，请医生治疗。", "explanation": "这里应该用〈医院〉。军人指在军队服役的人员，不能作为送伤员去的地方。"}, {"text": "他是一只军人，很勇敢。", "explanation": "这里应该用〈名〉。只用于动物和小件东西，指人要用“名”或“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军人", "is_correct": true, "explanation": "军人需要先学习条例，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“学习”要求有认知能力的施事，石头不能充当主语。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能学习条例，与句意冲突。"}, {"text": "树", "is_correct": false, "explanation": "配价：树木没有学习的能力，不能作“学习”的主语。"}], "explanations": {"军人": "军人需要先学习条例，符合句意。", "石头": "配价：“学习”要求有认知能力的施事，石头不能充当主语。", "小狗": "语义：小狗不能学习条例，与句意冲突。", "树": "配价：树木没有学习的能力，不能作“学习”的主语。"}, "sentence_index": 6, "correct_answer": "军人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新兵要先去军人训练。", "explanation": "这里应该用〈军营〉。军人指人员，不能作为训练的场所。"}, {"text": "他这次穿着军人，很神气。", "explanation": "这里应该用〈军装〉。穿的是衣服，军人指人员，不能作“穿”的对象，应说“穿着军装”。"}, {"text": "这次我在超市买了一个军人。", "explanation": "这里应该用〈商品〉。买的是商品，军人指人员，不能作买卖的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他当过一张军人，很了解部队。", "corrected_sentence": "他当过一名军人，很了解部队。", "error_description": "量词错误：“张”用于平面的东西，指人应用“名”，应说“当过一名军人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一名军人们在门口站岗。", "corrected_sentence": "一名军人在门口站岗。", "error_description": "复数标记错误：“们”不能与“一名”这样的数量词同时出现，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92033, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”指智力高，与“邪恶”不构成反义。"}, {"text": "美丽", "is_correct": false, "explanation": "无关：“美丽”形容外貌好看，与“邪恶”不构成反义。"}, {"text": "善良", "is_correct": true, "explanation": "反义：“善良”指心地好、不伤害他人，与“邪恶”意思相反。"}, {"text": "勤劳", "is_correct": false, "explanation": "无关：“勤劳”指肯干活，与“邪恶”不构成反义。"}], "correct_answer": "善良", "explanations": {"聪明": "无关：“聪明”指智力高，与“邪恶”不构成反义。", "美丽": "无关：“美丽”形容外貌好看，与“邪恶”不构成反义。", "善良": "反义：“善良”指心地好、不伤害他人，与“邪恶”意思相反。", "勤劳": "无关：“勤劳”指肯干活，与“邪恶”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92033, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”指光线充足，与“邪恶”不构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”指没有声响或心境平稳，与“邪恶”不构成反义。"}, {"text": "善良", "is_correct": true, "explanation": "反义：“善良”指心地好、不伤害他人，与“邪恶”意思相反。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”指愉快，与“邪恶”不构成反义。"}], "correct_answer": "善良", "explanations": {"明亮": "无关：“明亮”指光线充足，与“邪恶”不构成反义。", "安静": "无关：“安静”指没有声响或心境平稳，与“邪恶”不构成反义。", "善良": "反义：“善良”指心地好、不伤害他人，与“邪恶”意思相反。", "高兴": "无关：“高兴”指愉快，与“邪恶”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92033, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "邪恶是很坏很坏，想要伤害别人。", "primary_collocate": null, "pronunciation": "xié è", "ipa": "ɕjɛ˧˥ ɤ˥˩", "syllable_count": 2, "sentences": [{"text": "故事里的巫婆很邪恶，总想伤害小孩。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个邪恶的国王抓走了公主。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容看起来很邪恶。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的坏人邪恶极了，大家都很怕他。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邪恶的龙守着山洞，不让人进去。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了一个邪恶的办法来骗大家。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邪恶的大灰狼想吃掉小羊。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不喜欢邪恶的角色。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着那双邪恶的眼睛，吓得不敢动。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人帮助别人，邪恶的人却想伤害别人。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邪恶的", "label": "定语形式"}, {"form": "邪恶地", "label": "状语形式"}, {"form": "邪恶势力", "label": "复合"}, {"form": "邪惡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或角色很坏、想伤害别人，常见于故事、电影和日常描述", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92033, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”与后文“总想伤害小孩”的意思矛盾。"}, {"text": "邪恶", "is_correct": true, "explanation": "正确。“邪恶”说明巫婆存心伤害他人，与后文“总想伤害小孩”一致。"}, {"text": "甜蜜", "is_correct": false, "explanation": "搭配：“甜蜜”多形容爱情、生活，不用来形容巫婆的性格。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”与“总想伤害小孩”的意思矛盾。"}], "explanations": {"温柔": "语义：“温柔”与后文“总想伤害小孩”的意思矛盾。", "邪恶": "正确。“邪恶”说明巫婆存心伤害他人，与后文“总想伤害小孩”一致。", "甜蜜": "搭配：“甜蜜”多形容爱情、生活，不用来形容巫婆的性格。", "可爱": "语义：“可爱”与“总想伤害小孩”的意思矛盾。"}, "sentence_index": 0, "correct_answer": "邪恶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次的天气很邪恶，我们只好取消了旅行。", "explanation": "这里应该用〈恶劣〉。天气、环境、条件不好用“恶劣”，“邪恶”只指存心害人的人或行为。"}, {"text": "这个菜的味道很邪恶，我吃不下去。", "explanation": "这里应该用〈恶心〉。形容味道令人反胃用“恶心”，“邪恶”指存心害人，不能形容味道。"}, {"text": "那个孩子很邪恶，老是跟大人捣乱。", "explanation": "这里应该用〈调皮〉。小孩淘气、爱捣乱用“调皮”，“邪恶”指存心害人，用在孩子身上程度过重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92033, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慈祥", "is_correct": false, "explanation": "语义：“慈祥”指和蔼、疼爱，与“想吃掉小羊”的意思矛盾。"}, {"text": "清秀", "is_correct": false, "explanation": "体貌：“清秀”形容相貌，不用来说明狼的性格。"}, {"text": "邪恶", "is_correct": true, "explanation": "正确。“邪恶”说明大灰狼存心伤害他人，与“想吃掉小羊”一致。"}, {"text": "和善", "is_correct": false, "explanation": "语义：“和善”指态度友好，与“想吃掉小羊”的意思矛盾。"}], "explanations": {"慈祥": "语义：“慈祥”指和蔼、疼爱，与“想吃掉小羊”的意思矛盾。", "清秀": "体貌：“清秀”形容相貌，不用来说明狼的性格。", "邪恶": "正确。“邪恶”说明大灰狼存心伤害他人，与“想吃掉小羊”一致。", "和善": "语义：“和善”指态度友好，与“想吃掉小羊”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "邪恶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈很邪恶，经常忘记带钥匙。", "explanation": "这里应该用〈粗心〉。做事不细致、常忘事用“粗心”，“邪恶”指存心害人，与这种情况不符。"}, {"text": "这位老人很邪恶，一见陌生人就躲起来。", "explanation": "这里应该用〈害羞〉。怕生、不敢见人用“害羞”，“邪恶”指存心伤害他人，与这种情况不符。"}, {"text": "我的弟弟很邪恶，每天都睡到中午。", "explanation": "这里应该用〈懒惰〉。不愿做事用“懒惰”，“邪恶”指存心害人，不能用来形容贪睡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他露出了邪恶地笑容。", "corrected_sentence": "他露出了邪恶的笑容。", "error_description": "错误形式：“邪恶地笑容”；正确形式：“邪恶的笑容”。“地”修饰动词，修饰名词“笑容”时要用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个邪恶地人偷走了大家的钱。", "corrected_sentence": "那个邪恶的人偷走了大家的钱。", "error_description": "“地”是状语标记，不能用来修饰名词“人”，应改为“的”，即“邪恶的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92034, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": false, "explanation": "无关：“安静”指没有声响或心境平稳，与“邪恶”不构成反义。"}, {"text": "正义", "is_correct": true, "explanation": "反义：“正义”指合乎道义，与“邪恶”意思相反。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”指没有污物，与“邪恶”不构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”指智力高，与“邪恶”不构成反义。"}], "correct_answer": "正义", "explanations": {"安静": "无关：“安静”指没有声响或心境平稳，与“邪恶”不构成反义。", "正义": "反义：“正义”指合乎道义，与“邪恶”意思相反。", "干净": "无关：“干净”指没有污物，与“邪恶”不构成反义。", "聪明": "无关：“聪明”指智力高，与“邪恶”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92034, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”指愉快，与“邪恶”不构成反义。"}, {"text": "正义", "is_correct": true, "explanation": "反义：“正义”指合乎道义，与“邪恶”意思相反。"}, {"text": "勤劳", "is_correct": false, "explanation": "无关：“勤劳”指肯干活，与“邪恶”不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”指光线充足，与“邪恶”不构成反义。"}], "correct_answer": "正义", "explanations": {"高兴": "无关：“高兴”指愉快，与“邪恶”不构成反义。", "正义": "反义：“正义”指合乎道义，与“邪恶”意思相反。", "勤劳": "无关：“勤劳”指肯干活，与“邪恶”不构成反义。", "明亮": "无关：“明亮”指光线充足，与“邪恶”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92034, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "凶恶而不正当，存心做害人的坏事。", "primary_collocate": null, "pronunciation": "xié è", "ipa": "ɕjɛ˧˥ ɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他存心害人，心肠十分邪恶。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现了他邪恶的计划。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邪恶的势力最后一定会失败。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的反派人物邪恶而狡猾。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不相信这么邪恶的事是他做的。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他邪恶的目的是抢走别人的钱。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要勇敢地同邪恶的人作斗争。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人性格邪恶，常常做害人的坏事。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用邪恶的手段骗了老人的钱。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律最终会制裁邪恶的人。", "target_word": "邪恶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邪恶的", "label": "定语形式"}, {"form": "邪恶地", "label": "状语形式"}, {"form": "邪恶势力", "label": "复合"}, {"form": "邪惡", "label": "繁体"}], "register": "书面", "sense_fingerprint": "凶恶、不正当，存心做害人的坏事，多用于较正式的评价和叙述", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热心", "is_correct": false, "explanation": "语义：“热心”指乐于帮助人，与“存心害人”的意思矛盾。"}, {"text": "高尚", "is_correct": false, "explanation": "搭配：“高尚”多修饰品格、情操，一般不直接修饰心肠。"}, {"text": "仁慈", "is_correct": false, "explanation": "语义：“仁慈”指心地宽厚，与“存心害人”的意思矛盾。"}, {"text": "邪恶", "is_correct": true, "explanation": "正确。“邪恶”说明他存心害人、心肠狠毒，与前句的内容一致。"}], "explanations": {"热心": "语义：“热心”指乐于帮助人，与“存心害人”的意思矛盾。", "高尚": "搭配：“高尚”多修饰品格、情操，一般不直接修饰心肠。", "仁慈": "语义：“仁慈”指心地宽厚，与“存心害人”的意思矛盾。", "邪恶": "正确。“邪恶”说明他存心害人、心肠狠毒，与前句的内容一致。"}, "sentence_index": 0, "correct_answer": "邪恶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈很邪恶，总是轻声细语地哄孩子睡觉。", "explanation": "这里应该用〈温柔〉。待人和气、性情柔和用“温柔”，“邪恶”指存心作恶，与哄孩子睡觉的情景不符。"}, {"text": "老师讲课很邪恶，从来不开玩笑，但大家都很尊敬他。", "explanation": "这里应该用〈严肃〉。态度认真、不苟言笑用“严肃”，“邪恶”指存心作恶，与受人尊敬的老师不符。"}, {"text": "这个孩子很邪恶，喜欢唱歌跳舞。", "explanation": "这里应该用〈活泼〉。孩子性格开朗、爱动用“活泼”，“邪恶”指存心害人，与孩子的性格不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "善良", "is_correct": false, "explanation": "语义：善良的人不应成为斗争对象，与“作斗争”的句意矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”只形容身材，不能说明对方是否为斗争对象。"}, {"text": "邪恶", "is_correct": true, "explanation": "正确。“邪恶”指存心做坏事的人，是需要斗争的对象，与句意一致。"}, {"text": "友好", "is_correct": false, "explanation": "语义：友好的人不是斗争对象，与“作斗争”的句意矛盾。"}], "explanations": {"善良": "语义：善良的人不应成为斗争对象，与“作斗争”的句意矛盾。", "矮小": "体貌：“矮小”只形容身材，不能说明对方是否为斗争对象。", "邪恶": "正确。“邪恶”指存心做坏事的人，是需要斗争的对象，与句意一致。", "友好": "语义：友好的人不是斗争对象，与“作斗争”的句意矛盾。"}, "sentence_index": 6, "correct_answer": "邪恶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他看书很邪恶，每天都读到很晚。", "explanation": "这里应该用〈认真〉。专心踏实地做事用“认真”，“邪恶”指存心害人，不能形容看书的态度。"}, {"text": "今天的阳光很邪恶，晒得人很舒服。", "explanation": "这里应该用〈温暖〉。描写阳光让人舒服用“温暖”，“邪恶”指存心害人，不能形容阳光。"}, {"text": "这件衣服很邪恶，穿在身上很合适。", "explanation": "这里应该用〈合身〉。衣服尺寸合适用“合身”，“邪恶”指存心害人，不能形容衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他邪恶的咧嘴一笑。", "corrected_sentence": "他邪恶地咧嘴一笑。", "error_description": "错误形式：“邪恶的咧嘴一笑”；正确形式：“邪恶地咧嘴一笑”。修饰动词“笑”的状语要用“地”，用“的”会把“邪恶”当作定语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "正义终将战胜邪恶地敌人。", "corrected_sentence": "正义终将战胜邪恶的敌人。", "error_description": "错误形式：“邪恶地敌人”；正确形式：“邪恶的敌人”。“地”是状语标记，修饰名词“敌人”时要用“的”，用“地”句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
