INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92035, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "师生是老师和学生。", "primary_collocate": null, "pronunciation": "shī shēng", "ipa": "ʂɻ̩˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "开学第一天，师生都很高兴。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆对全校师生开放。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会上，师生一起为比赛加油。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动由师生共同完成。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师病了，全班师生都很担心。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师生们在花园里种了很多树。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的食堂师生都可以用。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班师生感情很深。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在会上对师生说了几句话。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师生一起参加了植树活动。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "師生", "label": "繁体"}], "register": "中性", "sense_fingerprint": "老师和学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92035, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "师生", "is_correct": true, "explanation": "师生（shī shēng）指老师和学生，正是听到的词。"}, {"text": "牺牲", "is_correct": false, "explanation": "xī（第一声）与 shī 声母不同（x / sh），意思是牺牲。"}, {"text": "湿身", "is_correct": false, "explanation": "湿身（shī shēn）第二音节韵母不同（-en / -eng），意思是身上被弄湿。"}, {"text": "诗圣", "is_correct": false, "explanation": "诗圣（shī shèng）第二音节是第四声，与 shēng（第一声）声调不同，意思是伟大的诗人。"}], "explanations": {"师生": "师生（shī shēng）指老师和学生，正是听到的词。", "牺牲": "xī（第一声）与 shī 声母不同（x / sh），意思是牺牲。", "湿身": "湿身（shī shēn）第二音节韵母不同（-en / -eng），意思是身上被弄湿。", "诗圣": "诗圣（shī shèng）第二音节是第四声，与 shēng（第一声）声调不同，意思是伟大的诗人。"}, "sentence_index": null, "correct_answer": "师生"}, "level_3": {"options": [{"text": "师生", "is_correct": true, "explanation": "师生指老师和学生，开学第一天师生都很高兴，符合句意。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是外出旅游的人，与开学第一天的学校情境无关。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人指生病在接受治疗的人，开学日不会这样描述。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“乘客”指搭乘交通工具的人，与“开学第一天”不搭配。"}], "explanations": {"师生": "师生指老师和学生，开学第一天师生都很高兴，符合句意。", "游客": "语义：游客是外出旅游的人，与开学第一天的学校情境无关。", "病人": "语义：病人指生病在接受治疗的人，开学日不会这样描述。", "乘客": "搭配：“乘客”指搭乘交通工具的人，与“开学第一天”不搭配。"}, "sentence_index": 0, "correct_answer": "师生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯鸡尾酒由师生共同调制。", "explanation": "这里应该用〈调酒师〉。师生只指学校里的老师和学生，调制鸡尾酒的是调酒师，不能说师生。"}, {"text": "这次运输由师生共同完成。", "explanation": "这里应该用〈司机〉。师生只指学校里的老师和学生，负责运输的是司机，不能说师生。"}, {"text": "这次抓捕由师生共同完成。", "explanation": "这里应该用〈警察〉。师生只用于学校场合，抓捕行动是警察做的，不能说师生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92035, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "师生", "is_correct": true, "explanation": "师生指老师和学生，学校的食堂师生都可以用，符合句意。"}, {"text": "居民", "is_correct": false, "explanation": "语义：居民指住在某地的人，学校食堂不对居民开放。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民是从事农业的人，与学校食堂的使用对象无关。"}, {"text": "士兵", "is_correct": false, "explanation": "搭配：“士兵”一般不与学校食堂的使用对象搭配，这种说法不通。"}], "explanations": {"师生": "师生指老师和学生，学校的食堂师生都可以用，符合句意。", "居民": "语义：居民指住在某地的人，学校食堂不对居民开放。", "农民": "语义：农民是从事农业的人，与学校食堂的使用对象无关。", "士兵": "搭配：“士兵”一般不与学校食堂的使用对象搭配，这种说法不通。"}, "sentence_index": 6, "correct_answer": "师生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市的师生都很热情。", "explanation": "这里应该用〈员工〉。师生只指学校里的老师和学生，超市里的工作人员应说员工，不用师生。"}, {"text": "这次植树活动的师生只有老师参加，没有学生。", "explanation": "这里应该用〈教师〉。师生指老师和学生两方，这句只剩老师一方，应说教师，不用师生。"}, {"text": "我家的小狗和我是师生，每天一起散步。", "explanation": "这里应该用〈伙伴〉。师生只指学校里的老师和学生，小狗不是老师或学生，我和它的关系应说伙伴，而不是师生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个师生都很努力。", "corrected_sentence": "这群师生都很努力。", "error_description": "“师生”指一群人，量词要用“群”，不能用“个”。应改为“这群师生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次会议有两百多名师生们参加。", "corrected_sentence": "这次会议有两百多名师生参加。", "error_description": "“名”已经表示人数，“师生”后面不能再加“们”，应说“两百多名师生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
