INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老师和学生的合称。", "primary_collocate": null, "pronunciation": "shī shēng", "ipa": "ʂɻ̩˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "全校师生都去操场看升旗仪式。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的师生一起打扫了教室。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师很受师生欢迎。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年晚会上，师生一起唱歌跳舞。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师生之间应该互相尊重。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为全体师生准备了午饭。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，师生都在教室里上课。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校有两千多名师生。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师生关系好，学习气氛也好。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业那天，师生都舍不得分开。", "target_word": "师生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "師生", "label": "繁体"}], "register": "中性", "sense_fingerprint": "老师和学生的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "师生", "is_correct": true, "explanation": "师生（shī shēng）指老师和学生，正是听到的词。"}, {"text": "牺牲", "is_correct": false, "explanation": "xī（第一声）与 shī 声母不同（x / sh），意思是牺牲。"}, {"text": "湿身", "is_correct": false, "explanation": "湿身（shī shēn）第二音节韵母不同（-en / -eng），意思是身上被弄湿。"}, {"text": "诗圣", "is_correct": false, "explanation": "诗圣（shī shèng）第二音节是第四声，与 shēng（第一声）声调不同，意思是伟大的诗人。"}], "explanations": {"师生": "师生（shī shēng）指老师和学生，正是听到的词。", "牺牲": "xī（第一声）与 shī 声母不同（x / sh），意思是牺牲。", "湿身": "湿身（shī shēn）第二音节韵母不同（-en / -eng），意思是身上被弄湿。", "诗圣": "诗圣（shī shèng）第二音节是第四声，与 shēng（第一声）声调不同，意思是伟大的诗人。"}, "sentence_index": null, "correct_answer": "师生"}, "level_3": {"options": [{"text": "师生", "is_correct": true, "explanation": "师生指老师和学生，全校的老师和学生都去看升旗仪式，符合句意。"}, {"text": "居民", "is_correct": false, "explanation": "语义：居民指住在某个地区的人，学校里不说“全校居民”去看升旗。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是到别处参观旅游的人，与学校的升旗仪式无关。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“乘客”指搭乘车船飞机的人，不能用来指学校里去操场的人。"}], "explanations": {"师生": "师生指老师和学生，全校的老师和学生都去看升旗仪式，符合句意。", "居民": "语义：居民指住在某个地区的人，学校里不说“全校居民”去看升旗。", "游客": "语义：游客是到别处参观旅游的人，与学校的升旗仪式无关。", "乘客": "搭配：“乘客”指搭乘车船飞机的人，不能用来指学校里去操场的人。"}, "sentence_index": 0, "correct_answer": "师生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位师生一个人在办公室批改作业。", "explanation": "这里应该用〈教师〉。师生指老师和学生的合称，是一群人，不能用“那位”指单独一人。"}, {"text": "一个师生迟到了，老师很生气。", "explanation": "这里应该用〈学生〉。师生指老师和学生的合称，不能用“一个”计数单个学生。"}, {"text": "这家公司的师生都很努力。", "explanation": "这里应该用〈员工〉。师生只用于学校里的老师和学生，公司里的人不说师生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUD