INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "师生", "is_correct": true, "explanation": "师生指老师和学生，下雨时师生都在教室里上课，符合句意。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是到别处参观旅游的人，与教室里上课的情境无关。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人指生病在接受治疗的人，不会在教室里上课。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机是开车的人，与教室里上课的情境无关。"}], "explanations": {"师生": "师生指老师和学生，下雨时师生都在教室里上课，符合句意。", "游客": "语义：游客是到别处参观旅游的人，与教室里上课的情境无关。", "病人": "语义：病人指生病在接受治疗的人，不会在教室里上课。", "司机": "语义：司机是开车的人，与教室里上课的情境无关。"}, "sentence_index": 6, "correct_answer": "师生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和同桌是师生，我们常一起学习。", "explanation": "这里应该用〈同学〉。师生指老师与学生的关系，同桌之间是同学关系，不能说师生。"}, {"text": "这所学校的师生只有老师，没有学生。", "explanation": "这里应该用〈教师〉。师生指老师和学生两方，这句只剩老师一方，应单独说教师，不用师生。"}, {"text": "我家的花猫和我是师生，每天一起散步。", "explanation": "这里应该用〈伙伴〉。师生只指学校里的老师和学生，花猫不是老师或学生，我和它的关系应说伙伴，而不是师生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个师生在操场上排队。", "corrected_sentence": "一群师生在操场上排队。", "error_description": "“师生”指一群人，量词应用“群”（如“一群师生”）。“个”只用于单个的人或事物，这里说“一个师生”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的中学有一千多名师生们。", "corrected_sentence": "这个小镇的中学有一千多名师生。", "error_description": "“名”已经表示人数，“师生”后面不能再加“们”，应说“一千多名师生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
