INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钟是告诉我们现在几点的东西。", "primary_collocate": null, "pronunciation": "zhōng", "ipa": "ʈʂʊŋ˥", "syllable_count": 1, "sentences": [{"text": "墙上的钟指着三点。", "target_word": "钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看了看钟，已经八点了。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个钟不走了，需要换电池。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家的钟慢了，所以他上课迟到了。", "target_word": "钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看一下钟，现在几点？", "target_word": "钟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "客厅里的钟每小时响一次。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在墙上挂了一个新钟，用来看时间。", "target_word": "钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个钟走得很准，从来不慢。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上的钟告诉我，该起床了。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钟上的时针指着八，分针指着十二。", "target_word": "钟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个钟", "label": "量词"}, {"form": "闹钟", "label": "复合"}, {"form": "时钟", "label": "复合"}, {"form": "鐘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钟：显示时间的计时器具，挂钟、座钟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02255d63-88e7-4cee-a6d4-c25bafea51c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92037, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钟", "is_correct": true, "explanation": "zhōng，指计时的器具，如挂钟、座钟。"}, {"text": "种", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng（第一声）声调不同，意思是种子。"}, {"text": "冲", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同（ch/zh），意思是冲击。"}, {"text": "东", "is_correct": false, "explanation": "dōng 与 zhōng 声母不同（d/zh），意思是东方。"}, {"text": "肿", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng 声调不同，意思是肿胀。"}, {"text": "宗", "is_correct": false, "explanation": "zōng 与 zhōng 声母不同（z/zh），意思是宗族、宗旨。"}], "explanations": {"钟": "zhōng，指计时的器具，如挂钟、座钟。", "种": "zhǒng（第三声）与 zhōng（第一声）声调不同，意思是种子。", "冲": "chōng 与 zhōng 声母不同（ch/zh），意思是冲击。", "东": "dōng 与 zhōng 声母不同（d/zh），意思是东方。", "肿": "zhǒng（第三声）与 zhōng 声调不同，意思是肿胀。", "宗": "zōng 与 zhōng 声母不同（z/zh），意思是宗族、宗旨。"}, "sentence_index": null, "correct_answer": "钟"}, "level_3": {"options": [{"text": "钟", "is_correct": true, "explanation": "“钟”指计时器具。墙上的计时器有指针，能指着三点，符合句意。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯不是计时器，没有指针，不能指着三点。"}, {"text": "日历", "is_correct": false, "explanation": "语义：日历显示日期，不指示时刻，不能指着三点。"}, {"text": "温度计", "is_correct": false, "explanation": "搭配：温度计指示温度，“指着三点”不是它的搭配。"}], "explanations": {"钟": "“钟”指计时器具。墙上的计时器有指针，能指着三点，符合句意。", "灯": "语义：灯不是计时器，没有指针，不能指着三点。", "日历": "语义：日历显示日期，不指示时刻，不能指着三点。", "温度计": "搭配：温度计指示温度，“指着三点”不是它的搭配。"}, "sentence_index": 0, "correct_answer": "钟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我戴在手腕上的钟慢了五分钟，差点误了火车。", "explanation": "这里应该用〈表〉。钟指挂钟、座钟等挂放或摆放的计时器；戴在手腕上的计时器用“表”。"}, {"text": "护士用钟给我量了量体温。", "explanation": "这里应该用〈体温计〉。钟是看时间的器具，不能量体温。"}, {"text": "他把钟从口袋里掏出来，看了看时间。", "explanation": "这里应该用〈怀表〉。钟多指挂放或摆放的较大计时器，揣在口袋里的怀表不用“钟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92037, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "钟", "is_correct": true, "explanation": "zhōng，指计时的器具，如挂钟、座钟。"}, {"text": "重", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是分量大。"}, {"text": "众", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是人多、大众。"}, {"text": "充", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同（ch/zh），意思是充满、充足。"}, {"text": "通", "is_correct": false, "explanation": "tōng 与 zhōng 声母不同（t/zh），意思是通过、通达。"}, {"text": "冬", "is_correct": false, "explanation": "dōng 与 zhōng 声母不同（d/zh），意思是冬天。"}], "explanations": {"钟": "zhōng，指计时的器具，如挂钟、座钟。", "重": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是分量大。", "众": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是人多、大众。", "充": "chōng 与 zhōng 声母不同（ch/zh），意思是充满、充足。", "通": "tōng 与 zhōng 声母不同（t/zh），意思是通过、通达。", "冬": "dōng 与 zhōng 声母不同（d/zh），意思是冬天。"}, "sentence_index": null, "correct_answer": "钟"}, "level_3": {"options": [{"text": "钟", "is_correct": true, "explanation": "“钟”指计时器具。妈妈挂在墙上的新计时器用来看时间，符合句意。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子用来照见自己，不用来看时间，与“用来看时间”不相合。"}, {"text": "收音机", "is_correct": false, "explanation": "搭配：收音机一般不挂在墙上，也不用于看时间，与句中的搭配不当。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图用来看路线和方位，不用来看时间，句意不通。"}], "explanations": {"钟": "“钟”指计时器具。妈妈挂在墙上的新计时器用来看时间，符合句意。", "镜子": "语义：镜子用来照见自己，不用来看时间，与“用来看时间”不相合。", "收音机": "搭配：收音机一般不挂在墙上，也不用于看时间，与句中的搭配不当。", "地图": "语义：地图用来看路线和方位，不用来看时间，句意不通。"}, "sentence_index": 6, "correct_answer": "钟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他随身带的钟又快了两分钟，得调一调。", "explanation": "这里应该用〈手表〉。钟指挂在墙上或摆在桌上的计时器，随身携带的表不用“钟”。"}, {"text": "我看了看墙上的钟，知道今天是几月几号。", "explanation": "这里应该用〈日历〉。钟显示几点，不显示日期。"}, {"text": "老师把钟翻过来，开始计时三分钟。", "explanation": "这里应该用〈沙漏〉。钟是挂放或摆放的计时器，不能翻过来计时；翻转计时的是“沙漏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的钟走很准。", "corrected_sentence": "厨房的钟走得很准。", "error_description": "错误：“走很准”漏掉了补语标记“得”。正确：“走得很准”，“动词+得+形容词”表示程度或结果，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书房的墙上挂着一条钟，每天都要上发条。", "corrected_sentence": "书房的墙上挂着一个钟，每天都要上发条。", "error_description": "错误：“条”用于细长的东西，钟不用“条”计量。正确：“一个钟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
