INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "敲击发声的金属响器，如寺庙、教堂的大钟。", "primary_collocate": null, "pronunciation": "zhōng", "ipa": "ʈʂʊŋ˥", "syllable_count": 1, "sentences": [{"text": "寺庙里的钟很大，声音很远。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "寺庙的和尚在敲钟，天亮了。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的寺院每天早晚都要敲钟。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的钟响了，学生们进了教室。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的寺庙有一口大钟。", "target_word": "钟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用力敲了三下钟。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这口钟是铜做的，已经有五百年了。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教堂的钟每天中午十二点响。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远处的山寺里，有人在敲钟。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人每天早上都去敲钟。", "target_word": "钟", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一口钟", "label": "量词"}, {"form": "钟楼", "label": "复合"}, {"form": "钟声", "label": "复合"}, {"form": "鐘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钟：可敲击发声的金属响器，寺庙、教堂的大钟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02255d63-88e7-4cee-a6d4-c25bafea51c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92038, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钟", "is_correct": true, "explanation": "zhōng，指敲击发声的金属响器，如寺庙的大钟。"}, {"text": "肿", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng（第一声）声调不同，意思是肿胀。"}, {"text": "充", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同（ch/zh），意思是充满、充足。"}, {"text": "宗", "is_correct": false, "explanation": "zōng 与 zhōng 声母不同（z/zh），意思是宗族、宗旨。"}, {"text": "重", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是分量大。"}, {"text": "冬", "is_correct": false, "explanation": "dōng 与 zhōng 声母不同（d/zh），意思是冬天。"}], "explanations": {"钟": "zhōng，指敲击发声的金属响器，如寺庙的大钟。", "肿": "zhǒng（第三声）与 zhōng（第一声）声调不同，意思是肿胀。", "充": "chōng 与 zhōng 声母不同（ch/zh），意思是充满、充足。", "宗": "zōng 与 zhōng 声母不同（z/zh），意思是宗族、宗旨。", "重": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是分量大。", "冬": "dōng 与 zhōng 声母不同（d/zh），意思是冬天。"}, "sentence_index": null, "correct_answer": "钟"}, "level_3": {"options": [{"text": "钟", "is_correct": true, "explanation": "“钟”指敲击发声的大型响器。寺庙里的大钟很大，声音能传得很远，符合句意。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不发声，“声音很远”无法用于镜子。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子不发声，“声音很远”与帽子无关。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“声音很远”说的是能发出声音的物体，桌子一般不这样说。"}], "explanations": {"钟": "“钟”指敲击发声的大型响器。寺庙里的大钟很大，声音能传得很远，符合句意。", "镜子": "语义：镜子不发声，“声音很远”无法用于镜子。", "帽子": "语义：帽子不发声，“声音很远”与帽子无关。", "桌子": "搭配：“声音很远”说的是能发出声音的物体，桌子一般不这样说。"}, "sentence_index": 0, "correct_answer": "钟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猫脖子上挂着一个小钟。", "explanation": "这里应该用〈铃〉。钟多为较大的敲击响器，挂在猫脖子上的小响器用“铃”。"}, {"text": "这个钟我每天戴在手腕上，走得很准。", "explanation": "这里应该用〈表〉。钟多指挂放或摆放的较大计时器，戴在手腕上的计时器用“表”。"}, {"text": "比赛开始了，裁判用力吹响了钟。", "explanation": "这里应该用〈哨子〉。钟是敲击发声的，不能吹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92038, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "钟", "is_correct": true, "explanation": "zhōng，指敲击发声的金属响器，如寺庙的大钟。"}, {"text": "种", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng（第一声）声调不同，意思是种子。"}, {"text": "冲", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同（ch/zh），意思是冲击。"}, {"text": "众", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是人多、大众。"}, {"text": "通", "is_correct": false, "explanation": "tōng 与 zhōng 声母不同（t/zh），意思是通过、通达。"}, {"text": "东", "is_correct": false, "explanation": "dōng 与 zhōng 声母不同（d/zh），意思是东方。"}], "explanations": {"钟": "zhōng，指敲击发声的金属响器，如寺庙的大钟。", "种": "zhǒng（第三声）与 zhōng（第一声）声调不同，意思是种子。", "冲": "chōng 与 zhōng 声母不同（ch/zh），意思是冲击。", "众": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是人多、大众。", "通": "tōng 与 zhōng 声母不同（t/zh），意思是通过、通达。", "东": "dōng 与 zhōng 声母不同（d/zh），意思是东方。"}, "sentence_index": null, "correct_answer": "钟"}, "level_3": {"options": [{"text": "钟", "is_correct": true, "explanation": "“钟”指金属响器。这口器物是铜做的，已经有五百年，符合句意。"}, {"text": "猪", "is_correct": false, "explanation": "语义：猪不是铜做的，“用铜做的”与猪不相合。"}, {"text": "人", "is_correct": false, "explanation": "语义：人不能用铜做，“铜做的”与人的身份不相合。"}, {"text": "井", "is_correct": false, "explanation": "搭配：井是挖出来的，不是铸造的，一般不说“铜做的”。"}], "explanations": {"钟": "“钟”指金属响器。这口器物是铜做的，已经有五百年，符合句意。", "猪": "语义：猪不是铜做的，“用铜做的”与猪不相合。", "人": "语义：人不能用铜做，“铜做的”与人的身份不相合。", "井": "搭配：井是挖出来的，不是铸造的，一般不说“铜做的”。"}, "sentence_index": 6, "correct_answer": "钟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "军营里吹起了钟，大家都起床了。", "explanation": "这里应该用〈号〉。号是吹奏的乐器，钟是敲击的，不能说“吹钟”。"}, {"text": "她用手指轻轻弹着钟，弹出了一首曲子。", "explanation": "这里应该用〈琴〉。钟是敲击的响器，不能用手指弹奏曲子。"}, {"text": "他把钟揣进口袋里，出门去了。", "explanation": "这里应该用〈怀表〉。钟是挂放或摆放的较大计时器，揣在口袋里的计时器用“怀表”，不用“钟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寺庙里的钟敲很响，声音传得很远。", "corrected_sentence": "寺庙里的钟敲得很响，声音传得很远。", "error_description": "错误：“敲很响”漏掉了补语标记“得”。正确：“敲得很响”，动词后用“得”引出程度或结果补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座古老的寺庙里有一条大钟，声音很响。", "corrected_sentence": "这座古老的寺庙里有一口大钟，声音很响。", "error_description": "错误：“条”用于细长的东西，大钟用“口”计量。正确：“一口大钟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
