INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "过了一段时间以后；事后。", "primary_collocate": null, "pronunciation": "guò hòu", "ipa": "kwo⁵¹ xoʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "我当时没注意，过后才想起来。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先别急，过后我再给你打电话。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当时没说什么，过后才生气。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过后我才发现，钥匙放在包里了。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题太复杂，过后再讨论吧。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他嘴上答应了，过后却忘得一干二净。", "target_word": "过后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在人太多，过后你再来拿吧。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时他没提意见，过后才告诉我。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她当时很生气，过后就慢慢好了。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱过后再算，现在先吃饭。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "过后-过一段时间以后，事后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1253fbc-9288-40c9-a9b1-e95e77d08214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事先", "is_correct": false, "explanation": "语义：“事先”指事情发生之前，与“当时没注意…才想起来”的先后顺序相反。"}, {"text": "过后", "is_correct": true, "explanation": "正确：“过后”表示事后，当时没注意、后来才想起来，时间关系相符。"}, {"text": "首先", "is_correct": false, "explanation": "语义：“首先”表示第一步，与“才想起来”表示的迟来时间不合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行中，不能与“才”搭配表示事后。"}], "explanations": {"事先": "语义：“事先”指事情发生之前，与“当时没注意…才想起来”的先后顺序相反。", "过后": "正确：“过后”表示事后，当时没注意、后来才想起来，时间关系相符。", "首先": "语义：“首先”表示第一步，与“才想起来”表示的迟来时间不合。", "正在": "搭配：“正在”表示动作进行中，不能与“才”搭配表示事后。"}, "sentence_index": 0, "correct_answer": "过后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边吃饭，过后一边看书。", "explanation": "这里应该用〈同时〉。过后表示先后顺序，指一件事结束之后，不能与表示同时进行的“一边”搭配。"}, {"text": "现在过后，我们马上开始工作。", "explanation": "这里应该用〈以后〉。过后要接一段时间之后的情况，不能指“现在”这样的当下时点。"}, {"text": "这件事过后已经发生了。", "explanation": "这里应该用〈以前〉。过后指之后，与“已经发生”这种已完成的时间搭配矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示同一时间进行，与“过后再来拿”的先后安排矛盾。"}, {"text": "过后", "is_correct": true, "explanation": "正确：“过后”表示之后再做，与“现在人太多”的语境相符。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上做，与“过后再来”的安排冲突。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续不断，不能与“你再来拿”这样的一次性动作搭配。"}], "explanations": {"同时": "语义：“同时”表示同一时间进行，与“过后再来拿”的先后安排矛盾。", "过后": "正确：“过后”表示之后再做，与“现在人太多”的语境相符。", "立即": "语义：“立即”表示马上做，与“过后再来”的安排冲突。", "一直": "搭配：“一直”表示持续不断，不能与“你再来拿”这样的一次性动作搭配。"}, "sentence_index": 6, "correct_answer": "过后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我过后已经告诉过你了，你忘了吗？", "explanation": "这里应该用〈之前〉。过后指以后，不能与“已经…过”一起说过去早已做完的事。"}, {"text": "他一开始过后就很努力。", "explanation": "这里应该用〈起初〉。过后表示之后，不能指事情的开始。"}, {"text": "演出前过后，我们走出了剧场。", "explanation": "这里“前”与“过后”的先后关系矛盾。过后表示事情做完之后，不能与“前”同时使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他当时没说，过后以后才告诉我。", "corrected_sentence": "他当时没说，过后才告诉我。", "error_description": "错误形式“过后以后”，正确形式“过后”。“过后”本身已表示之后，再加“以后”语义重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当时没生气，很过后才生气。", "corrected_sentence": "他当时没生气，过后才生气。", "error_description": "错误形式“很过后”。“过后”是时间词，不能被程度副词“很”修饰，应直接用“过后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
