INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92041, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "帐篷是在外面睡觉用的布房子。", "primary_collocate": null, "pronunciation": "zhàng peng", "ipa": "ʈʂɑŋ˥˩ pʰɤŋ", "syllable_count": 2, "sentences": [{"text": "我们在山上搭了一顶帐篷，晚上睡在里面。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上很冷，我钻进帐篷，盖好了被子。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去河边玩，还带着帐篷。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们想在草地上搭一顶帐篷。", "target_word": "帐篷", "complexity_tier": "T3", "furigana": "Háizimen xiǎng zài cǎodì shang dā yì dǐng zhàngpeng.", "sentence_source": "generated"}, {"text": "这顶帐篷很轻，一个人就能背走。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帐篷里有两个睡袋，还有一盏小灯。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们赶快回到帐篷里。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在帮我把帐篷搭好。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的帐篷是蓝色的，在树下很好看。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次睡在帐篷里，一晚上没睡好。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "顶", "label": "量词"}, {"form": "帳篷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "帐篷：野外睡觉用的布房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92041, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帐篷", "is_correct": true, "explanation": "正确。“搭了一顶帐篷”指支起来的布房子，晚上可以睡在里面。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子是戴在头上的，搭不起来，也不能睡在里面。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“顶”用于帐篷、帽子，房子应说“一座”或“一栋”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是放东西用的，不能睡在里面。"}], "explanations": {"帐篷": "正确。“搭了一顶帐篷”指支起来的布房子，晚上可以睡在里面。", "帽子": "语义：帽子是戴在头上的，搭不起来，也不能睡在里面。", "房子": "搭配：量词“顶”用于帐篷、帽子，房子应说“一座”或“一栋”。", "桌子": "语义：桌子是放东西用的，不能睡在里面。"}, "sentence_index": 0, "correct_answer": "帐篷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把这顶帐篷贴在墙上，当装饰用。", "explanation": "这里应该用〈墙纸〉。帐篷是支起来住的，不能贴在墙上当装饰；贴在墙上的东西要用〈墙纸〉。"}, {"text": "我渴了，就打开帐篷喝了一口水。", "explanation": "这里应该用〈水壶〉。帐篷是睡觉用的布房子，不能装水喝。"}, {"text": "下雨了，他穿上了帐篷去上学。", "explanation": "这里应该用〈衣服〉。帐篷不是穿在身上的东西，“穿”要搭配衣服、鞋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92041, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帐篷", "is_correct": true, "explanation": "正确。“回到……里”后面接可以进入、可以住人的地方，帐篷正是这样的地方。"}, {"text": "雨衣", "is_correct": false, "explanation": "语义：雨衣是穿在身上的，不是可以回去住的地方。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“回到……里”接可以进入的场所，雨伞是撑在手上的，不能说“回到雨伞里”。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子是戴在头上的，不能回到它里面去。"}], "explanations": {"帐篷": "正确。“回到……里”后面接可以进入、可以住人的地方，帐篷正是这样的地方。", "雨衣": "语义：雨衣是穿在身上的，不是可以回去住的地方。", "雨伞": "搭配：“回到……里”接可以进入的场所，雨伞是撑在手上的，不能说“回到雨伞里”。", "帽子": "语义：帽子是戴在头上的，不能回到它里面去。"}, "sentence_index": 6, "correct_answer": "帐篷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顶帐篷的墙是用水泥砌的，很结实。", "explanation": "这里应该用〈房子〉。帐篷是布做的，不能用水泥砌墙，墙是水泥砌成的要用〈房子〉。"}, {"text": "他把帐篷戴在头上，出门去了。", "explanation": "这里应该用〈帽子〉。帐篷是睡觉用的布房子，不能戴在头上。"}, {"text": "他把帐篷贴好，屋子变亮了。", "explanation": "这里应该用〈墙纸〉。帐篷是支起来的，不能贴；说“贴”要用墙纸、海报一类的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座帐篷是去年夏天买的，还很新。", "corrected_sentence": "这顶帐篷是去年夏天买的，还很新。", "error_description": "量词错误：帐篷应用量词“顶”，不能用“座”。“座”用于山、房屋、桥梁等大型固定建筑。正确说法是“这顶帐篷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨停了，我们在一台帐篷里吃了晚饭。", "corrected_sentence": "雨停了，我们在一顶帐篷里吃了晚饭。", "error_description": "量词错误：帐篷应用量词“顶”，不能用“台”。“台”用于机器、电器等。正确说法是“一顶帐篷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
