INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92042, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92042, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用布等支起来的、可以遮蔽风雨的临时住处。", "primary_collocate": null, "pronunciation": "zhàng peng", "ipa": "ʈʂɑŋ˥˩ pʰɤŋ", "syllable_count": 2, "sentences": [{"text": "地震以后，很多人住在临时的帐篷里。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人在河边支起了几顶帐篷。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风把帐篷吹倒了，我们赶快扶起来。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帐篷可以挡风，也可以挡雨。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口的帐篷里有医生，可以免费看病。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上的牧民住在白色的帐篷里。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛场边搭着一排帐篷，让大家休息。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨时，帐篷里也有一点水。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在雪山上过夜，只有一顶小帐篷。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者给灾区的人送去了帐篷和被子。", "target_word": "帐篷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "顶", "label": "量词"}, {"form": "帳篷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "帐篷：用布支起、遮风挡雨的临时住处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帐篷", "is_correct": true, "explanation": "正确。“临时的帐篷里”指临时搭起来供人住的地方，符合句意。"}, {"text": "箱子", "is_correct": false, "explanation": "语义：箱子不能住人，“住在……里”要说可以住人的地方。"}, {"text": "雨衣", "is_correct": false, "explanation": "语义：雨衣是穿在身上的，不能住在里面。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“临时的……里”要说可以住人的场所，雨伞不能用来住人。"}], "explanations": {"帐篷": "正确。“临时的帐篷里”指临时搭起来供人住的地方，符合句意。", "箱子": "语义：箱子不能住人，“住在……里”要说可以住人的地方。", "雨衣": "语义：雨衣是穿在身上的，不能住在里面。", "雨伞": "搭配：“临时的……里”要说可以住人的场所，雨伞不能用来住人。"}, "sentence_index": 0, "correct_answer": "帐篷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这顶帐篷是用砖头垒起来的，很结实。", "explanation": "这里应该用〈房子〉。帐篷是布做的，不能用砖头垒，用砖头垒起来的要说〈房子〉。"}, {"text": "他戴上了帐篷去上学。", "explanation": "这里应该用〈帽子〉。帐篷不能戴在头上，“戴”只用于帽子、眼镜等东西。"}, {"text": "他把帐篷穿在身上去跑步。", "explanation": "这里应该用〈衣服〉。帐篷是住的地方，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帐篷", "is_correct": true, "explanation": "正确。“搭着一排帐篷”指支起来的布房子，可以让大家休息。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“搭”指支起、架设，行李不能说“搭着一排行李”。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子是戴在头上的，不能拿来让大家休息。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车不能“搭”，也不能“搭着一排”让大家在里面休息。"}], "explanations": {"帐篷": "正确。“搭着一排帐篷”指支起来的布房子，可以让大家休息。", "行李": "搭配：“搭”指支起、架设，行李不能说“搭着一排行李”。", "帽子": "语义：帽子是戴在头上的，不能拿来让大家休息。", "汽车": "搭配：汽车不能“搭”，也不能“搭着一排”让大家在里面休息。"}, "sentence_index": 6, "correct_answer": "帐篷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用这顶帐篷煮了汤。", "explanation": "这里应该用〈锅〉。帐篷不能用来煮东西，煮汤要用〈锅〉。"}, {"text": "我每天早上用帐篷刷牙。", "explanation": "这里应该用〈牙刷〉。帐篷是住的地方，不能用来刷牙。"}, {"text": "爸爸打开帐篷，看今天的新闻。", "explanation": "这里应该用〈报纸〉。看新闻要用报纸，帐篷不能用来看新闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里下起了大雨，我们钻进了那座帐篷。", "corrected_sentence": "夜里下起了大雨，我们钻进了那顶帐篷。", "error_description": "量词错误：帐篷应用量词“顶”，不能用“座”。“座”用于山、房屋、桥梁等大型固定建筑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把一条帐篷搭好了，准备过夜。", "corrected_sentence": "我们把一顶帐篷搭好了，准备过夜。", "error_description": "量词错误：帐篷应用量词“顶”，不能用“条”。“条”用于细长的东西，如绳子、河流、裤子。正确说法是“一顶帐篷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
