INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "牵涉到；对某事物有重要影响。", "primary_collocate": null, "pronunciation": "guān xì dào", "ipa": "kwan˥ ɕi˥˩ tau˥˩", "syllable_count": 3, "sentences": [{"text": "这件事关系到整个公司的未来。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "环境问题关系到每个人的生活。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题关系到国家的大事，不能马虎。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新办法关系到很多老人的生活。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个决定关系到一千人的工作。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "食品安全关系到千家万户。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次会议要谈的事关系到学校的未来。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话关系到我们的生意，你要听清楚。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱关系到孩子能不能上学。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教育关系到一个国家的未来。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "牵涉到重大事物，对其有重要影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62980f86-a355-48b6-b578-ee1687d5ac53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关系到", "is_correct": true, "explanation": "正确。“关系到”表示这件事会对公司的未来产生重大影响，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象是作品或景物等，不能说欣赏“公司的未来”。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”的施事应是人，“这件事”不能欺骗“公司的未来”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能用于“公司的未来”。"}], "explanations": {"关系到": "正确。“关系到”表示这件事会对公司的未来产生重大影响，符合句意。", "欣赏": "语义：“欣赏”的对象是作品或景物等，不能说欣赏“公司的未来”。", "欺骗": "语义：“欺骗”的施事应是人，“这件事”不能欺骗“公司的未来”。", "打扫": "搭配：“打扫”的对象是场所或物品，不能用于“公司的未来”。"}, "sentence_index": 0, "correct_answer": "关系到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我关系到这份名单。", "explanation": "这里应该用〈记住〉。“关系到”表示事情对另一件事的影响，不表示记忆；记住名单要用“记住”。"}, {"text": "我关系到老人的生活。", "explanation": "这里应该用〈陪伴〉。“陪伴”是人主动的行为，可以用人作主语；“关系到”只说事情的影响，不能用人作主语来表示陪同。"}, {"text": "这些商店关系到城里很多地方。", "explanation": "这里应该用〈分布〉。“分布”说事物散布在某些地方；“关系到”表示影响，不能用来说明范围或位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关系到", "is_correct": true, "explanation": "正确。这次会议要谈的事会对学校的未来产生重大影响，“关系到”符合句意。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”的对象是人或人的言行，“要谈的事”不能批评“学校的未来”。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是人或动物，不能用于“学校的未来”。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”要求以人为对象，“要谈的事”不能照顾“学校的未来”。"}], "explanations": {"关系到": "正确。这次会议要谈的事会对学校的未来产生重大影响，“关系到”符合句意。", "批评": "语义：“批评”的对象是人或人的言行，“要谈的事”不能批评“学校的未来”。", "喂养": "搭配：“喂养”的对象是人或动物，不能用于“学校的未来”。", "照顾": "语义：“照顾”要求以人为对象，“要谈的事”不能照顾“学校的未来”。"}, "sentence_index": 6, "correct_answer": "关系到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章关系到很长的篇幅。", "explanation": "这里应该用〈占〉。“关系到”表示影响，不表示占据的范围；说占了多少篇幅要用“占”。"}, {"text": "他的声音很关系到。", "explanation": "这里应该用〈响亮〉。“关系到”是动词，表示影响，不能用来形容声音；说声音大要用“很响亮”。"}, {"text": "我的朋友关系到了一本书。", "explanation": "这里应该用〈借〉。“关系到”表示影响，不表示借用物品；向别人借书要用“借”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项政策被关系到农民的收入。", "corrected_sentence": "这项政策关系到农民的收入。", "error_description": "错误：“关系到”前面多加了“被”，“关系到”不能用“被”构成被动。正确应说“这项政策关系到农民的收入”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次决定关系到到全体职工的利益。", "corrected_sentence": "这次决定关系到全体职工的利益。", "error_description": "错误：“关系到”后面多写了一个“到”，变成“关系到到”。正确应删去多余的“到”，说“关系到全体职工的利益”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "反义：“近”与“遥远”构成反义，指距离很近。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”说明晰，与距离远近无关，不是“遥远”的反义词。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：“热闹”说场面喧闹，与距离远近无关。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”说没有污物，与距离远近无关。"}], "correct_answer": "近", "explanations": {"近": "反义：“近”与“遥远”构成反义，指距离很近。", "清楚": "无关：“清楚”说明晰，与距离远近无关，不是“遥远”的反义词。", "热闹": "无关：“热闹”说场面喧闹，与距离远近无关。", "干净": "无关：“干净”说没有污物，与距离远近无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "反义：“近”与“遥远”构成反义，指距离很近。"}, {"text": "冰冷", "is_correct": false, "explanation": "无关：“冰冷”说温度低，与距离远近无关。"}, {"text": "迟缓", "is_correct": false, "explanation": "无关：“迟缓”说速度慢，与距离远近无关。"}, {"text": "精彩", "is_correct": false, "explanation": "无关：“精彩”说表演或内容好，与距离远近无关。"}], "correct_answer": "近", "explanations": {"近": "反义：“近”与“遥远”构成反义，指距离很近。", "冰冷": "无关：“冰冷”说温度低，与距离远近无关。", "迟缓": "无关：“迟缓”说速度慢，与距离远近无关。", "精彩": "无关：“精彩”说表演或内容好，与距离远近无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "离得很远很远。", "primary_collocate": null, "pronunciation": "yáo yuǎn", "ipa": "jɑʊ˧˥ ɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "那颗星星离我们非常遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡在遥远的北方。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里到那座山，路途很遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去一个遥远的国家看看。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞向遥远的天边。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遥远的星星在夜里一闪一闪。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了很久，才到那个遥远的小村子。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈住在遥远的南方，我很少见到她。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对孩子来说，月亮看起来既美丽又遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信从遥远的地方寄来。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "相隔非常远，远得几乎够不着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遥远", "is_correct": true, "explanation": "正确：遥远说距离很远，与“离我们非常”相合。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或外观，不能说离我们的距离，与“离我们非常”不合。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“离……非常”后面要接表示距离的形容词，“巨大”说体积，不能说离我们巨大。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”说质地，与星星和距离无关，句子讲不通。"}], "explanations": {"遥远": "正确：遥远说距离很远，与“离我们非常”相合。", "明亮": "体貌：“明亮”形容光线或外观，不能说离我们的距离，与“离我们非常”不合。", "巨大": "搭配：“离……非常”后面要接表示距离的形容词，“巨大”说体积，不能说离我们巨大。", "柔软": "语义：“柔软”说质地，与星星和距离无关，句子讲不通。"}, "sentence_index": 0, "correct_answer": "遥远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对我的态度很遥远，好像不想理我。", "explanation": "这里应该用〈疏远〉。遥远只指空间或时间上的距离，人与人之间的冷淡要用疏远。"}, {"text": "这件事对我们的影响很遥远。", "explanation": "这里应该用〈深远〉。遥远说距离，说影响广泛而持久要用深远。"}, {"text": "教室离这里只有两步遥远。", "explanation": "这里应该用〈近〉。遥远表示距离很远，不能用来说“只有两步”这样很近的距离；很近的距离要说近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遥远", "is_correct": true, "explanation": "正确：遥远说距离很远，与“走了很久，才到”相合。"}, {"text": "近", "is_correct": false, "explanation": "语义：“近”与“走了很久，才到”矛盾，走很久才到说明路途远。"}, {"text": "繁华", "is_correct": false, "explanation": "搭配：“繁华”形容城镇热闹，不能用来修饰“小村子”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或建筑的形体，与“小”矛盾，村子不说高大。"}], "explanations": {"遥远": "正确：遥远说距离很远，与“走了很久，才到”相合。", "近": "语义：“近”与“走了很久，才到”矛盾，走很久才到说明路途远。", "繁华": "搭配：“繁华”形容城镇热闹，不能用来修饰“小村子”。", "高大": "体貌：“高大”形容人或建筑的形体，与“小”矛盾，村子不说高大。"}, "sentence_index": 6, "correct_answer": "遥远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水很遥远，喝不得。", "explanation": "这里应该用〈烫〉。遥远只说距离，说水温高要用烫。"}, {"text": "我们签订了遥远的合作协议。", "explanation": "这里应该用〈长期〉。遥远不用来修饰合作、协议的持续时间，那要用长期。"}, {"text": "他遥远地完成了那项工作。", "explanation": "这里应该用〈远程〉。遥远只描述距离，不能修饰“完成工作”这类动作；通过网络远程完成要说远程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的老家在遥远南方。", "corrected_sentence": "他的老家在遥远的南方。", "error_description": "错误：遥远是双音节形容词，修饰名词时后面要加“的”；应为“遥远的南方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个村子离城里是遥远。", "corrected_sentence": "那个村子离城里很遥远。", "error_description": "错误：遥远前要用程度副词“很”，不能用判断动词“是”；应为“很遥远”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
