INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92046, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "距离很远。", "primary_collocate": null, "pronunciation": "yáo yuǎn", "ipa": "jɑʊ˧˥ ɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的学校路途遥远，每天要坐一个小时车。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个城市非常遥远，见面不容易。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火星离地球十分遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方太遥远了，我不想去。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间的距离非常遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在遥远的山里有一所小学校。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路太遥远，我们决定坐火车去。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友在遥远的海边工作。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路遥远又难走，大家都很累。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管多遥远，我都会去看你。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两地之间的距离很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遥远", "is_correct": true, "explanation": "正确：遥远说距离很远，与“路途”和“坐一个小时车”相合。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”说路面宽窄，不修饰“路途”的远近。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“紧张”形容心情或局势，路途不说紧张，句子讲不通。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或外观，与路途距离无关。"}], "explanations": {"遥远": "正确：遥远说距离很远，与“路途”和“坐一个小时车”相合。", "狭窄": "搭配：“狭窄”说路面宽窄，不修饰“路途”的远近。", "紧张": "语义：“紧张”形容心情或局势，路途不说紧张，句子讲不通。", "明亮": "体貌：“明亮”形容光线或外观，与路途距离无关。"}, "sentence_index": 0, "correct_answer": "遥远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的影响很遥远。", "explanation": "这里应该用〈深远〉。遥远说距离，说影响广泛而持久要用深远。"}, {"text": "我家离学校只有五步遥远。", "explanation": "这里应该用〈近〉。遥远表示距离很远，不能用来说“只有五步”这样很近的距离；很近的距离要说近。"}, {"text": "他对我的态度很遥远，不愿说话。", "explanation": "这里应该用〈疏远〉。遥远只指空间或时间上的距离，人与人之间的冷淡要用疏远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遥远", "is_correct": true, "explanation": "正确：遥远说距离很远，与“坐火车”的理由相合。"}, {"text": "近", "is_correct": false, "explanation": "语义：路太近就不必坐火车，与后句的理由相悖。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”说质地，不能修饰“路”的远近。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”说事物容易损坏，与路的远近无关，句子讲不通。"}], "explanations": {"遥远": "正确：遥远说距离很远，与“坐火车”的理由相合。", "近": "语义：路太近就不必坐火车，与后句的理由相悖。", "柔软": "搭配：“柔软”说质地，不能修饰“路”的远近。", "脆弱": "语义：“脆弱”说事物容易损坏，与路的远近无关，句子讲不通。"}, "sentence_index": 6, "correct_answer": "遥远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色很遥远，看起来像生病了。", "explanation": "这里应该用〈苍白〉。遥远只说距离，说脸色要用苍白。"}, {"text": "我们签订了遥远的合作协议。", "explanation": "这里应该用〈长期〉。遥远不用来修饰合作、协议的持续时间，那要用长期。"}, {"text": "老师遥远地指导我们做实验。", "explanation": "这里应该用〈远程〉。遥远只描述距离，不能修饰“指导”这类动作；隔着网络指导要说远程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路没遥远，走路就能到。", "corrected_sentence": "这条路不遥远，走路就能到。", "error_description": "错误：形容词前要用“不”否定，不能用“没”；应为“不遥远”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的表哥住在遥远山里。", "corrected_sentence": "我的表哥住在遥远的山里。", "error_description": "错误：双音节形容词“遥远”修饰名词时后面要加“的”；应为“遥远的山里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
