INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92047, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带上是拿着东西一起走。", "primary_collocate": null, "pronunciation": "dài shàng", "ipa": "tai˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "外面下雨，出门请带上伞。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去旅行时，别忘了带上照相机。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去公园野餐，带上水果和面包吧。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走得很快，忘了带上手机。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天有考试，请带上你的学生证。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气冷，你带上这件外套吧。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我带上书去图书馆看了一下午。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把礼物带上，去朋友家吃饭。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去海边游泳，要带上泳衣。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爬山的时候，带上足够的水。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "带上了", "label": "体标"}, {"form": "带上过", "label": "体标"}], "register": "口语", "sense_fingerprint": "出门前拿起东西一起带走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e5eb461-8e2e-4423-8692-ca4884dea8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92047, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带上", "is_correct": true, "explanation": "带上：随身拿着一起走，此处为动词。"}, {"text": "台上", "is_correct": false, "explanation": "tái（第二声）与 dài（第四声）声调不同，意思是台上（舞台或平台的上面）。"}, {"text": "带伤", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是带伤（身上有伤）。"}, {"text": "赖上", "is_correct": false, "explanation": "lài 与 dài 声母不同，意思是赖上（缠住不放）。"}], "explanations": {"带上": "带上：随身拿着一起走，此处为动词。", "台上": "tái（第二声）与 dài（第四声）声调不同，意思是台上（舞台或平台的上面）。", "带伤": "shāng（第一声）与 shàng（第四声）声调不同，意思是带伤（身上有伤）。", "赖上": "lài 与 dài 声母不同，意思是赖上（缠住不放）。"}, "sentence_index": null, "correct_answer": "带上"}, "level_3": {"options": [{"text": "带上", "is_correct": true, "explanation": "带上：随身拿着，此处指出门时把伞拿在身边。"}, {"text": "脱下", "is_correct": false, "explanation": "搭配：“脱”多用于衣物、鞋子，不能说“脱下伞”。"}, {"text": "放下", "is_correct": false, "explanation": "语义：“放下”是放在一边，与“出门”时随身携带的语境不合。"}, {"text": "收起", "is_correct": false, "explanation": "语义：收起伞通常在雨停之后，与“外面下雨”的语境冲突。"}], "explanations": {"带上": "带上：随身拿着，此处指出门时把伞拿在身边。", "脱下": "搭配：“脱”多用于衣物、鞋子，不能说“脱下伞”。", "放下": "语义：“放下”是放在一边，与“出门”时随身携带的语境不合。", "收起": "语义：收起伞通常在雨停之后，与“外面下雨”的语境冲突。"}, "sentence_index": 0, "correct_answer": "带上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把画带上了墙。", "explanation": "这里应该用〈挂〉。带上指随身携带，把画挂在墙上要用挂。"}, {"text": "他从口袋里带上一张纸。", "explanation": "这里应该用〈掏出〉。带上是随身带走，不是从口袋里取出。"}, {"text": "他把桌子带上屋里。", "explanation": "这里应该用〈搬〉。带上指随身带走，搬运大件家具要用搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带上", "is_correct": true, "explanation": "带上：随身带着，此处指去图书馆时把书拿在身边。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕书与“去图书馆看了一下午”的语境矛盾。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧书与“去图书馆看书”的语境矛盾。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋子等，不能说“穿书”。"}], "explanations": {"带上": "带上：随身带着，此处指去图书馆时把书拿在身边。", "撕": "语义：撕书与“去图书馆看了一下午”的语境矛盾。", "烧": "语义：烧书与“去图书馆看书”的语境矛盾。", "穿": "搭配：“穿”用于衣服、鞋子等，不能说“穿书”。"}, "sentence_index": 6, "correct_answer": "带上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把行李从车上带上了。", "explanation": "这里应该用〈卸下〉。带上是随身拿走，要把行李从车上取下应说卸下。"}, {"text": "她把衣服带上衣柜里。", "explanation": "这里应该用〈挂进〉。带上指随身带走，把衣服放进衣柜要用挂进。"}, {"text": "我把杯子带上柜子。", "explanation": "这里应该用〈放进〉。带上指随身携带，把杯子放进柜子要用放进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我出门前总会带上了一把伞。", "corrected_sentence": "我出门前总会带上一把伞。", "error_description": "“了”用错了位置。“总会”表示习惯性动作，不表示已完成，“带上”后不能加“了”。应为“我出门前总会带上一把伞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把伞带上了过。", "corrected_sentence": "他把伞带上了。", "error_description": "“过”多余。“带上了”已表示完成，“了”与“过”不能同时用在动词后，句末不应再加“过”。应为“他把伞带上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
