INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92048, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "随身带着。", "primary_collocate": null, "pronunciation": "dài shàng", "ipa": "tai˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他每次出门，都带上一本笔记本，随时记事。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶出门总带上药，以防万一。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我习惯在包里带上一瓶水。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说你要随时带上这些药。", "target_word": "带上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑车时带上手机，有事可以打电话。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出国时带上了妈妈的照片。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在口袋里带上一支笔，随时写字。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸去工作，总带上他的旧手表。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人出门要带上电话，家里人才放心。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李每天上班，都带上一把钥匙。", "target_word": "带上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带上了", "label": "体标"}, {"form": "带上过", "label": "体标"}], "register": "口语", "sense_fingerprint": "把东西放在身上或包里，随时带着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e5eb461-8e2e-4423-8692-ca4884dea8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92048, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带上", "is_correct": true, "explanation": "带上：随身带着，此处为动词。"}, {"text": "台上", "is_correct": false, "explanation": "tái（第二声）与 dài（第四声）声调不同，意思是台上（舞台或平台的上面）。"}, {"text": "带伤", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是带伤（身上有伤）。"}, {"text": "赖上", "is_correct": false, "explanation": "lài 与 dài 声母不同，意思是赖上（缠住不放）。"}], "explanations": {"带上": "带上：随身带着，此处为动词。", "台上": "tái（第二声）与 dài（第四声）声调不同，意思是台上（舞台或平台的上面）。", "带伤": "shāng（第一声）与 shàng（第四声）声调不同，意思是带伤（身上有伤）。", "赖上": "lài 与 dài 声母不同，意思是赖上（缠住不放）。"}, "sentence_index": null, "correct_answer": "带上"}, "level_3": {"options": [{"text": "带上", "is_correct": true, "explanation": "带上：随身带着，此处指每次出门都把笔记本带在身上。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔掉笔记本与“随时记事”的语境矛盾。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉笔记本与“随时记事”的语境冲突。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋子等，不能说“穿一本笔记本”。"}], "explanations": {"带上": "带上：随身带着，此处指每次出门都把笔记本带在身上。", "扔": "语义：扔掉笔记本与“随时记事”的语境矛盾。", "烧": "语义：烧掉笔记本与“随时记事”的语境冲突。", "穿": "搭配：“穿”用于衣服、鞋子等，不能说“穿一本笔记本”。"}, "sentence_index": 0, "correct_answer": "带上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动带上了很多快乐。", "explanation": "这里应该用〈带来〉。带上指随身携带实物，不能用于快乐这类抽象的东西。"}, {"text": "医生让我每天带上三次药。", "explanation": "这里应该用〈吃〉。带上指随身携带，不表示按时服用药物。"}, {"text": "他在墙上带上了一个灯。", "explanation": "这里应该用〈装〉。带上指随身携带，把灯安在墙上要用装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带上", "is_correct": true, "explanation": "带上：随身带着，此处指在口袋里随身放着一支笔。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃笔与“随时写字”的语境矛盾。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬笔与“随时写字”的语境冲突。"}, {"text": "丢", "is_correct": false, "explanation": "语义：丢笔与“随时写字”的语境矛盾。"}], "explanations": {"带上": "带上：随身带着，此处指在口袋里随身放着一支笔。", "吃": "语义：吃笔与“随时写字”的语境矛盾。", "咬": "语义：咬笔与“随时写字”的语境冲突。", "丢": "语义：丢笔与“随时写字”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "带上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上带上了一幅画。", "explanation": "这里应该用〈挂〉。带上指随身携带，把画挂在墙上要用挂。"}, {"text": "他们在山上带上了一座小房子。", "explanation": "这里应该用〈盖〉。带上指随身携带，建造房屋要用盖。"}, {"text": "他把椅子带上屋里。", "explanation": "这里应该用〈搬〉。带上指随身带走，搬运家具要用搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他出门时带上着一本书。", "corrected_sentence": "他出门时带上了一本书。", "error_description": "体标用错。“带上”后表示完成的动作应用“了”，不能用“着”。“着”表示持续状态，与“带上”这个完成性动作不搭配，应说“带上了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都水壶带上。", "corrected_sentence": "他每天都把水壶带上。", "error_description": "语序错误。宾语“水壶”放在“带上”前面时必须用“把”引出，应说“把水壶带上”；也可以说“带上水壶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
