INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92049, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世界经济是世界上所有国家一起做买卖、挣钱的情况。", "primary_collocate": null, "pronunciation": "shì jiè jīng jì", "ipa": "ʂɻ̩˥˩ tɕjɛ˥˩ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "世界经济今年比去年好。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界经济不好，买卖也不好做。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天看新闻，关心世界经济。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家的经济都受世界经济影响。", "target_word": "世界经济", "complexity_tier": "T3", "furigana": "hěn duō guó jiā de jīng jì dōu shòu shì jiè jīng jì yǐng xiǎng.", "sentence_source": "generated"}, {"text": "世界经济好了，工作就多了。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界经济让各国的人都能做买卖。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在电视上谈世界经济。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近世界经济有一些问题。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为世界经济变慢，工厂的活儿少了。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友是研究世界经济的老师。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "各国做买卖挣钱的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92049, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界经济", "is_correct": true, "explanation": "正确：“世界经济”指各国做买卖挣钱的情况，可以说“今年比去年好”。"}, {"text": "大山", "is_correct": false, "explanation": "语义：大山是地貌，没有“今年比去年好”这样的经营状况比较。"}, {"text": "一把椅子", "is_correct": false, "explanation": "语义：椅子是器物，不能用“比去年好”来评价。"}, {"text": "池塘", "is_correct": false, "explanation": "搭配：“比去年好”多用于经济、业绩等状况，不搭配“池塘”。"}], "explanations": {"世界经济": "正确：“世界经济”指各国做买卖挣钱的情况，可以说“今年比去年好”。", "大山": "语义：大山是地貌，没有“今年比去年好”这样的经营状况比较。", "一把椅子": "语义：椅子是器物，不能用“比去年好”来评价。", "池塘": "搭配：“比去年好”多用于经济、业绩等状况，不搭配“池塘”。"}, "sentence_index": 0, "correct_answer": "世界经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试的世界经济很好。", "explanation": "这里应该用〈成绩〉。考试的好坏指成绩，“世界经济”指各国做买卖挣钱的情况，不能用来评价考试。"}, {"text": "今天的世界经济很蓝。", "explanation": "这里应该用〈天空〉。“蓝”形容颜色，“世界经济”没有颜色，不能这样说。"}, {"text": "他的世界经济很矮。", "explanation": "这里应该用〈身高〉。“矮”用于人或物的高矮，“世界经济”指经济状况，不能说矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92049, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界经济", "is_correct": true, "explanation": "正确：“谈”的对象可以是经济形势这类话题，可以说“谈世界经济”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地点，不是可以谈论的话题。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶是植物的一部分，一般不作电视上谈论的话题。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“谈”多搭配问题、话题、形势，不搭配“闹钟”。"}], "explanations": {"世界经济": "正确：“谈”的对象可以是经济形势这类话题，可以说“谈世界经济”。", "厨房": "语义：厨房是地点，不是可以谈论的话题。", "树叶": "语义：树叶是植物的一部分，一般不作电视上谈论的话题。", "闹钟": "搭配：“谈”多搭配问题、话题、形势，不搭配“闹钟”。"}, "sentence_index": 6, "correct_answer": "世界经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的世界经济很好。", "explanation": "这里应该用〈味道〉。“好”评价口味，“世界经济”指经济状况，不能用来评价汤。"}, {"text": "他得了世界经济。", "explanation": "这里应该用〈感冒〉。“得”后接病症，“世界经济”不是病，不能说“得”。"}, {"text": "她唱了一首世界经济。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌曲，“世界经济”不是歌，不能唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只世界经济慢慢好起来了。", "corrected_sentence": "世界经济慢慢好起来了。", "error_description": "错误：“这只世界经济”；正确：“世界经济”。“世界经济”是一个整体，前面不能加量词“只”，应去掉“这只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条世界经济去年受过一次冲击。", "corrected_sentence": "世界经济去年受过一次冲击。", "error_description": "错误：“这条世界经济”；正确：“世界经济”。“世界经济”是一个整体，前面不能加量词“条”，应去掉“这条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
