INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92050, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "各国经济相互联系而形成的整体经济。", "primary_collocate": null, "pronunciation": "shì jiè jīng jì", "ipa": "ʂɻ̩˥˩ tɕjɛ˥˩ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "世界经济是一个整体。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界经济的稳定需要各国合作。", "target_word": "世界经济", "complexity_tier": "T3", "furigana": "shì jiè jīng jì de wěn dìng xū yào gè guó hé zuò.", "sentence_source": "generated"}, {"text": "这个国家的变化会影响世界经济。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天讲了世界经济的历史。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界经济越来越像一个大家庭。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个大国出了问题，世界经济也会受影响。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里学习世界经济。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界经济的发展离不开各国的联系。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，世界经济的联系越来越紧密。", "target_word": "世界经济", "complexity_tier": "T3", "furigana": "bào zhǐ shàng shuō, shì jiè jīng jì de lián xì yuè lái yuè jǐn mì.", "sentence_source": "generated"}, {"text": "我想了解世界经济是怎么联系起来的。", "target_word": "世界经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "各国经济联系成的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界经济", "is_correct": true, "explanation": "正确：“世界经济”指各国经济相互联系形成的整体，可以说“是一个整体”。"}, {"text": "一盘散沙", "is_correct": false, "explanation": "语义：“一盘散沙”指松散、没有联系的状态，与“整体”相矛盾。"}, {"text": "一堆碎片", "is_correct": false, "explanation": "语义：“一堆碎片”是零散的东西，不构成整体，与“是一个整体”相矛盾。"}, {"text": "各自独立的个体", "is_correct": false, "explanation": "搭配：“各自独立”与“是一个整体”意思相反，不能搭配。"}], "explanations": {"世界经济": "正确：“世界经济”指各国经济相互联系形成的整体，可以说“是一个整体”。", "一盘散沙": "语义：“一盘散沙”指松散、没有联系的状态，与“整体”相矛盾。", "一堆碎片": "语义：“一堆碎片”是零散的东西，不构成整体，与“是一个整体”相矛盾。", "各自独立的个体": "搭配：“各自独立”与“是一个整体”意思相反，不能搭配。"}, "sentence_index": 0, "correct_answer": "世界经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上给世界经济浇水。", "explanation": "这里应该用〈花〉。浇水的对象是植物，“世界经济”是抽象概念，不能浇。"}, {"text": "世界经济向这家公司发放了贷款。", "explanation": "这里应该用〈世界银行〉。发放贷款的是金融机构，“世界经济”指经济整体，不能作施事。"}, {"text": "世界经济决赛在下周进行。", "explanation": "这里应该用〈世界杯〉。决赛属于体育赛事，“世界经济”不能举办比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界经济", "is_correct": true, "explanation": "正确：“学习”的对象可以是“世界经济”这门学问。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是场地，不能作“学习”的对象。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“学习”的宾语应是知识或技能，“早餐”不能搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是可以学习的内容。"}], "explanations": {"世界经济": "正确：“学习”的对象可以是“世界经济”这门学问。", "操场": "语义：操场是场地，不能作“学习”的对象。", "早餐": "搭配：“学习”的宾语应是知识或技能，“早餐”不能搭配。", "冰箱": "语义：冰箱是家用电器，不是可以学习的内容。"}, "sentence_index": 6, "correct_answer": "世界经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天中午吃世界经济。", "explanation": "这里应该用〈午饭〉。“吃”的对象是食物，“世界经济”是抽象概念，不能吃，应说“吃午饭”。"}, {"text": "他是世界经济。", "explanation": "这里应该用〈世界冠军〉。“是”后应为身份，“世界经济”指经济状况，不能指人。"}, {"text": "他的墙上挂着一张世界经济。", "explanation": "这里应该用〈世界地图〉。“挂”的对象是图片、字画，“世界经济”是抽象概念，不能挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座世界经济慢慢融合起来了。", "corrected_sentence": "世界经济慢慢融合起来了。", "error_description": "错误：“这座世界经济”；正确：“世界经济”。“世界经济”是一个整体，前面不能加量词“座”，应去掉“这座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
