INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92051, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "借书", "is_correct": true, "explanation": "反义：“借书”与“还书”构成反义，指把书借来。"}, {"text": "阅读", "is_correct": false, "explanation": "无关：“阅读”指看书的内容，与归还书籍无关。"}, {"text": "购买", "is_correct": false, "explanation": "无关：“购买”指花钱买，与归还无关。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”指把物品收拾有序，与归还无关。"}], "correct_answer": "借书", "explanations": {"借书": "反义：“借书”与“还书”构成反义，指把书借来。", "阅读": "无关：“阅读”指看书的内容，与归还书籍无关。", "购买": "无关：“购买”指花钱买，与归还无关。", "整理": "无关：“整理”指把物品收拾有序，与归还无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92051, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "借书", "is_correct": true, "explanation": "反义：“借书”与“还书”构成反义，指把书借来。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指保存珍品，与归还无关。"}, {"text": "编写", "is_correct": false, "explanation": "无关：“编写”指编辑成书，与归还无关。"}, {"text": "丢弃", "is_correct": false, "explanation": "无关：“丢弃”指扔掉，与归还无关。"}], "correct_answer": "借书", "explanations": {"借书": "反义：“借书”与“还书”构成反义，指把书借来。", "收藏": "无关：“收藏”指保存珍品，与归还无关。", "编写": "无关：“编写”指编辑成书，与归还无关。", "丢弃": "无关：“丢弃”指扔掉，与归还无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92051, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把借来的书送回去。", "primary_collocate": null, "pronunciation": "huán shū", "ipa": "xwan˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "我借的书看完了，明天再去还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑车去学校图书馆还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把借来的书看完了，今天去还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以后，我们一起去还书吧。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹生病了，我替她去还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我路过图书馆，顺便还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她早上拿着借来的三本书去图书馆还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的门关了，今天没办法还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末爸爸带我去图书馆还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书看完了，该去还书了。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "还过书", "label": "体标"}, {"form": "还了书", "label": "体标"}], "register": "中性", "sense_fingerprint": "把借来的书送回原来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还书", "is_correct": true, "explanation": "正确：还书指把借来的书送回去，与“借的书看完了”前后相承。"}, {"text": "撕书", "is_correct": false, "explanation": "语义：“撕书”是毁坏书籍，与“借的书”不合，句子讲不通。"}, {"text": "烧书", "is_correct": false, "explanation": "语义：“烧书”是毁坏书籍，借来的书不能烧掉再去。"}, {"text": "印书", "is_correct": false, "explanation": "搭配：“印书”的主体是出版社，不能对借来的书说印书。"}], "explanations": {"还书": "正确：还书指把借来的书送回去，与“借的书看完了”前后相承。", "撕书": "语义：“撕书”是毁坏书籍，与“借的书”不合，句子讲不通。", "烧书": "语义：“烧书”是毁坏书籍，借来的书不能烧掉再去。", "印书": "搭配：“印书”的主体是出版社，不能对借来的书说印书。"}, "sentence_index": 0, "correct_answer": "还书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下课以后，我们一起去图书馆还书看吧。", "explanation": "这里应该用〈借书〉。还书是把借来的书送回，要看书得先借书，不能说还书看。"}, {"text": "这本书买错了，我们一起去书店还书吧。", "explanation": "这里应该用〈退书〉。还书指归还借来的书，买错的书要去书店退书。"}, {"text": "下课以后，我们一起去银行还书吧。", "explanation": "这里应该用〈还钱〉。还书只用于归还书籍，去银行归还钱款要说还钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还书", "is_correct": true, "explanation": "正确：还书指把借来的书送回原处，与“拿着借来的三本书去图书馆”相合。"}, {"text": "丢书", "is_correct": false, "explanation": "语义：“丢书”是丢失，与“拿了三本书去”矛盾，句子讲不通。"}, {"text": "还钱", "is_correct": false, "explanation": "语义：“还钱”是归还款项，拿着书去还钱与句意不合。"}, {"text": "写书", "is_correct": false, "explanation": "搭配：“写书”是作者的行为，不说拿着书去写书。"}], "explanations": {"还书": "正确：还书指把借来的书送回原处，与“拿着借来的三本书去图书馆”相合。", "丢书": "语义：“丢书”是丢失，与“拿了三本书去”矛盾，句子讲不通。", "还钱": "语义：“还钱”是归还款项，拿着书去还钱与句意不合。", "写书": "搭配：“写书”是作者的行为，不说拿着书去写书。"}, "sentence_index": 6, "correct_answer": "还书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他花了三年时间还书，终于完成了。", "explanation": "这里应该用〈写书〉。还书指归还借来的书，花三年完成的著作要说写书。"}, {"text": "这本书要寄给朋友，该去还书了。", "explanation": "这里应该用〈寄书〉。还书是把借来的书送回原处，寄给朋友要说寄书。"}, {"text": "钱用完了，该去还书了。", "explanation": "这里应该用〈借钱〉。还书只用于书籍，钱用完了要去借钱，不能说还书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天去图书馆还书过。", "corrected_sentence": "我昨天去图书馆还过书。", "error_description": "错误：体标“过”位置不对，应紧跟动词放在“还”后、宾语“书”前，应为“还过书”，不能说“还书过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天还书了过，所以知道流程。", "corrected_sentence": "我今天还书了，所以知道流程。", "error_description": "错误：“了”和“过”不能同时用在同一个动词后，多余的“过”应去掉，应为“还书了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92052, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "借书", "is_correct": true, "explanation": "反义：“借书”与“还书”构成反义，指把书借来。"}, {"text": "阅读", "is_correct": false, "explanation": "无关：“阅读”指看书的内容，与归还书籍无关。"}, {"text": "购买", "is_correct": false, "explanation": "无关：“购买”指花钱买，与归还无关。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”指把物品收拾有序，与归还无关。"}], "correct_answer": "借书", "explanations": {"借书": "反义：“借书”与“还书”构成反义，指把书借来。", "阅读": "无关：“阅读”指看书的内容，与归还书籍无关。", "购买": "无关：“购买”指花钱买，与归还无关。", "整理": "无关：“整理”指把物品收拾有序，与归还无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
