INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92052, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把借的书归还。", "primary_collocate": null, "pronunciation": "huán shū", "ipa": "xwan˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "我今天下午要去图书馆还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还书的时候，别忘了带借书证。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天是最后一天，我必须去还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了还书，所以要交钱。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆星期天不能还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候还书？我想借那本。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都会按时还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我借了三本书，下周三要还书。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里可以自己还书，不用找人。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还书以前，我想再看一遍。", "target_word": "还书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "还过书", "label": "体标"}, {"form": "还了书", "label": "体标"}], "register": "中性", "sense_fingerprint": "把借的书归还给图书馆或别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还书", "is_correct": true, "explanation": "正确：还书指把借的书归还，与“去图书馆”相合。"}, {"text": "撕书", "is_correct": false, "explanation": "语义：“撕书”是损毁书籍，去图书馆不会这样做，与句意不合。"}, {"text": "烧书", "is_correct": false, "explanation": "语义：“烧书”是毁坏书籍，去图书馆不会这样做。"}, {"text": "印书", "is_correct": false, "explanation": "搭配：“印书”的主体是出版社，不说去图书馆印书。"}], "explanations": {"还书": "正确：还书指把借的书归还，与“去图书馆”相合。", "撕书": "语义：“撕书”是损毁书籍，去图书馆不会这样做，与句意不合。", "烧书": "语义：“烧书”是毁坏书籍，去图书馆不会这样做。", "印书": "搭配：“印书”的主体是出版社，不说去图书馆印书。"}, "sentence_index": 0, "correct_answer": "还书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天去图书馆还书看。", "explanation": "这里应该用〈借书〉。还书是把书归还，要先借书才能看，不能说去图书馆还书看。"}, {"text": "这本书买错了，我去书店还书。", "explanation": "这里应该用〈退书〉。还书指归还借来的书，买错的书要到书店退书。"}, {"text": "他借了我的钱，说好下周还书。", "explanation": "这里应该用〈还钱〉。还书只用于归还书籍，归还借来的钱款要说还钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还书", "is_correct": true, "explanation": "正确：还书指把借的书归还，与“按时”和“每个月”相合。"}, {"text": "迟还", "is_correct": false, "explanation": "语义：“迟还”与“按时”矛盾，不能说按时迟还。"}, {"text": "丢书", "is_correct": false, "explanation": "语义：“丢书”说丢失，与“按时”矛盾，句子讲不通。"}, {"text": "撕书", "is_correct": false, "explanation": "搭配：“撕书”是损毁书籍，不是借阅后的正常行为，与“按时”不搭。"}], "explanations": {"还书": "正确：还书指把借的书归还，与“按时”和“每个月”相合。", "迟还": "语义：“迟还”与“按时”矛盾，不能说按时迟还。", "丢书": "语义：“丢书”说丢失，与“按时”矛盾，句子讲不通。", "撕书": "搭配：“撕书”是损毁书籍，不是借阅后的正常行为，与“按时”不搭。"}, "sentence_index": 6, "correct_answer": "还书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的东西可以还书，你可以试试。", "explanation": "这里应该用〈还价〉。还书只说归还书籍，与商家讨价还价要说还价。"}, {"text": "他去书店还书，换了些钱。", "explanation": "这里应该用〈卖书〉。还书是归还借来的书，把书卖给书店换钱要说卖书。"}, {"text": "我们可以互相还书看。", "explanation": "这里应该用〈换书〉。互相交换书籍要说换书，还书没有交换的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他还书得很快。", "corrected_sentence": "他还书还得很快。", "error_description": "错误：带补语“得”的动词短语要重复动词，应说“还书还得很快”，不能只说“还书得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前在这里还书过，所以很熟悉流程。", "corrected_sentence": "他以前在这里还过书，所以很熟悉流程。", "error_description": "错误：“过”要紧跟动词，应说“还过书”，不说“还书过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
